local config = {
  ui_story_5035_50350101_1_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_5035_50350101_2_dialog_content = "하이~ 이렇게 하면 녹화가 시작된 거겠지?",
  ui_story_5035_50350101_3_dialog_content = "이얍! 이 카메라는 역시 좀 무겁네.",
  ui_story_5035_50350101_4_dialog_content = "누구부터 찍어야 좋을까나... 좋았어! 스크립터님을 찍어야겠어!",
  ui_story_5035_50350101_5_dialog_content = "네?! 저, 저요?",
  ui_story_5035_50350101_6_dialog_content = "근데... 아직 렌즈 캡도 안 벗기셨는데요...",
  ui_story_5035_50350101_7_dialog_content = "응? 앗! 내가 이런 실수를! 완전히 실수했네!",
  ui_story_5035_50350101_8_dialog_content = "그래도 정식 촬영은 아니니까 다행이야. 알려 줘서 고마워! 스크립터님!",
  ui_story_5035_50350101_9_dialog_content = "제, 제가 해야 할 일인걸요.",
  ui_story_5035_50350101_10_dialog_content = "자, 그럼 카메라를 보고 인사 한번 해 줘!",
  ui_story_5035_50350101_11_dialog_content = "여, 여러분 안녕하세요. 여긴 <color=#FFB400>《헌티드 하우스》</color> 촬영 현장이에요. 저는...",
  ui_story_5035_50350101_12_dialog_content = "그냥 촬영장 비하인드 찍는 거니까, 그렇게 진지하게 안 해도 돼!",
  ui_story_5035_50350101_13_dialog_content = "그치만, 이런 말이라도 안 하면... 카메라를 보고 무슨 얘길 해야 할지 모르겠는걸요.",
  ui_story_5035_50350101_14_dialog_content = "어차피 이 영화의 <color=#FFB400>여주인공</color>은 제가 아닌 당신이니까,\n역시 제가 찍어드리는 게 좋을 것 같아요.",
  ui_story_5035_50350101_15_dialog_content = "싫어~ 아직 더 찍고 싶단 말이야!",
  ui_story_5035_50350101_16_dialog_content = "으음, 그럼... 감독님! 감독님! 이쪽으로 좀 와 주세요!",
  ui_story_5035_50350101_17_dialog_content = "어쩔 수 없네.\n스크립터님한데 카메라 공포증이 좀 있는 것 같으니까 다른 사람을 찍어야겠어...",
  ui_story_5035_50350101_18_dialog_content = "쨔자잔! 바로 이 영화의 메가폰을 잡은! 조니 감독님이랍니다!",
  ui_story_5035_50350101_19_dialog_content = "하하, 더 찍고 싶다니 잘됐네.",
  ui_story_5035_50350101_20_dialog_content = "어차피 이제부터 꽤 오랫동안 그 카메라를 메고 다녀야 할 거거든.",
  ui_story_5035_50350101_21_dialog_content = "네? 그게 무슨 말이에요?",
  ui_story_5035_50350101_22_dialog_content = "새로운 시도를 해 볼 생각이야.\n이번 작품은 <color=#FFB400>페이크 다큐멘터리</color> 형식으로 촬영할 거야.",
  ui_story_5035_50350101_23_dialog_content = "그래서 여주인공인 네가 카메라를 메고 다녀야 해.\n우린 네 시점을 통해서 이 집을 탐사할 거야.",
  ui_story_5035_50350101_24_dialog_content = "네 이동 경로, 대사, 무의식적으로 하는 반응들이 전부\n날 것 그대로 카메라에 잡히게 될 거야.",
  ui_story_5035_50350101_25_dialog_content = "어때? 할 수 있겠어?",
  ui_story_5035_50350101_26_dialog_content = "정말요?! 그럼 저야 좋죠!",
  ui_story_5035_50350101_27_dialog_content = "하하, 자신감 있는 것도 확실히 우리 여주인공의 매력이지.\n극장에 이 영화가 걸리기만 하면, 넌 순식간에 유명해질 거야.",
  ui_story_5035_50350101_28_dialog_content = "그럼 조니 씨도 분명히 이 영화로 유명한 명감독이 될 수 있을 거예요!",
  ui_story_5035_50350101_29_dialog_content = "그렇게 되면 좋긴 하겠지만, 이젠 「유명 감독」이 되는 데는 조금 덤덤해졌어.",
  ui_story_5035_50350101_30_dialog_content = "지금까지 없었고, 앞으로도 없을 공포 영화를 만들 수만 있다면,\n나한테는 그게 곧 성공이거든.",
  ui_story_5035_50350101_31_dialog_content = "푸후후훕! 또 그런 얘길 하네요!",
  ui_story_5035_50350101_32_dialog_content = "아무튼, 카메라는 저한테 주시고, 걱정 마세요...",
  ui_story_5035_50350101_33_dialog_content = "으앗!",
  ui_story_5035_50350101_34_dialog_content = "괘, 괜찮아요?!",
  ui_story_5035_50350101_35_dialog_content = "그냥 케이블에 걸린 거야. 헤헤, 멀쩡해...",
  ui_story_5035_50350101_36_dialog_content = "촬영기사는 촬영 중에 여배우를 따라서 함께 이동해 주는 게 좋을 것 같습니다.",
  ui_story_5035_50350101_37_dialog_content = "네, 장비는 제가 잘 챙기겠습니다.",
  ui_story_5035_50350101_38_dialog_content = "그럼... 《헌티드 하우스》 신1, 테이크1. 레디, 액션!",
  ui_story_5035_50350101_39_dialog_content = "“어.머.나. 세.상.에! 내 눈앞에 있는 여기가 바로 귀신이 나온다는\n소문이 자자한 그 저택이구나!”",
  ui_story_5035_50350101_40_dialog_content = "“정.말 무.섭.네~ 이제부터 친구랑 같이 들어가서 소문이 진짜인지 확인해 봐야겠어!”",
  ui_story_5035_50350101_41_dialog_content = "“이런 순간에 조니 감독님이 우리랑 같이 들어가 줬으면 정말 좋았을 텐데...”",
  ui_story_5035_50350101_42_dialog_content = "“어.머.나! 도저히 믿을 수가 없어. 감독님이 사라져 버렸잖아!\n첫 번째 초자연적 현상이 벌써 일어나 버린 걸까!”",
  ui_story_5035_50350101_43_dialog_content = "컷!",
  ui_story_5035_50350101_44_dialog_content = "계속 그렇게 오버해서 대사를 하시면, 나중에 편집할 때 힘듭니다.",
  ui_story_5035_50350101_45_dialog_content = "방금 그 장면도 아마 편집될 겁니다. 지금부터는 평범하게 대사를 쳐 주세요.",
  ui_story_5035_50350101_46_dialog_content = "아하하! 그렇구나, 알겠어.",
  ui_story_5035_50350101_47_dialog_content = "그나저나 감독님은 대체 어디 간 걸까?",
  ui_story_5035_50350101_48_dialog_content = "정말이지... 프로듀서님은 어제부터 휴가를 내 버리더니, 이번엔 감독님이 없어져 버렸네.",
  ui_story_5035_50350101_49_dialog_content = "촬영은 다 나한테 떠맡기고 어디 가서 빈둥거리고 있는 거 아냐?",
  ui_story_5035_50350101_50_dialog_content = "아니면... 미리 이 저택에 들어가서 우릴 놀래줄 준비를 하고 있는 걸까?",
  ui_story_5035_50350101_51_dialog_content = "...컷! 이 부분도 편집입니다.",
  ui_story_5035_50350101_52_dialog_content = "잊지 마세요. 페이크 다큐멘터리는 「리얼리티」가 생명입니다.",
  ui_story_5035_50350101_53_dialog_content = "저택 안으로 들어가고 나면, 그 누구도 영화 제작에 대한 말을 꺼내면 안 됩니다.",
  ui_story_5035_50350101_54_dialog_content = "알겠어요...",
  ui_story_5035_50350101_55_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_5035_50350101_56_dialog_content = "이 앞 모퉁이에 바로 소문 속의 「죽음으로 통하는 계단」이 있어.",
  ui_story_5035_50350101_57_dialog_content = "그럼 촬영기사님은 기념사진을 찍어 주고, 스크립터님은 길을 기록해 줄 수 있을까?",
  ui_story_5035_50350101_58_dialog_content = "네, 그건 괜찮은데...",
  ui_story_5035_50350101_59_dialog_content = "제가 맨 앞에서 가는 건 좀...",
  ui_story_5035_50350101_60_dialog_content = "아! 그럼 내가 맨 앞에서 카메라를 들고 길을 찾을게!",
  ui_story_5035_50350101_61_dialog_content = "죽음의 계단~ 어디 어디 숨었나~♪",
  ui_story_5035_50350101_62_dialog_content = "이 앞에 계단이 있어. 고개를 숙이고 지나가야 해~",
  ui_story_5035_50350101_63_dialog_content = "난 괜찮지만, 스크립터님이랑 촬영기사님은 머릴 부딪힐 수도...",
  ui_story_5035_50350101_64_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5035_50350101_65_dialog_content = "벌써... 부딪혔어요...",
  ui_story_5035_50350101_66_dialog_content = "겁이 없다고 해야 할지, 머리가 안 좋다고 해야 할지 모르겠지만.",
  ui_story_5035_50350101_67_dialog_content = "제가 지금까지 봐 온 공포 영화들 속에선 당신 같은 사람이\n첫 희생자가 되는 경우가 많더군요.",
  ui_story_5035_50350101_68_dialog_content = "꺄악──!",
  ui_story_5035_50350101_69_dialog_content = "으아아아아아아악!",
  ui_story_5035_50350101_70_dialog_content = "또 뭡니까?!",
  ui_story_5035_50350101_71_dialog_content = "앞쪽에...",
  ui_story_5035_50350101_72_dialog_content = "앞쪽에 있는 계단은 막다른 길이야!",
  ui_story_5035_50350101_73_dialog_content = "...그게 답니까?",
  ui_story_5035_50350101_74_dialog_content = "그럼 스크립터님은 왜 비명을 지른 겁니까?",
  ui_story_5035_50350101_75_dialog_content = "저, 저는 제 앞에서 비명이 들리길래 덩달아서...",
  ui_story_5035_50350101_76_dialog_content = "......",
  ui_story_5035_50350101_77_dialog_content = "헤헤, 아무래도 소문이 좀 과장되긴 했죠. 스크린 앞의 우리 관객 여러분들은\n이런 부분에 너무 신경 쓰지 않으셨으면 좋겠네요~",
  ui_story_5035_50350101_78_dialog_content = "그럼 계속해서 다음 장소로 이동하자!",
  ui_story_5035_50350101_79_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5035_50350101_80_dialog_content = "내 착각인진 모르겠는데, 이상한 냄새가 나.",
  ui_story_5035_50350101_81_dialog_content = "뭔가... 썩은 냄새 같은걸.",
  ui_story_5035_50350101_82_dialog_content = "그, 그게 정말인가요?",
  ui_story_5035_50350101_83_dialog_content = "글쎄, 내 코에만 이런 걸지도?",
  ui_story_5035_50350101_84_dialog_content = "지금 눈앞에 있는 건 좀 웃기게 생긴 인형들뿐이니까...",
  ui_story_5035_50350101_85_dialog_content = "어라?",
  ui_story_5035_50350101_86_dialog_content = "설마 내가 또 착각했나? 이 인형이 원래 이쪽 방향을 보고 있었어?",
  ui_story_5035_50350101_87_dialog_content = "네에에?!",
  ui_story_5035_50350101_88_dialog_content = "긴가민가할 필요가 뭐 있습니까. 영상을 되감아 보면 바로 알 수 있잖습니까.",
  ui_story_5035_50350101_89_dialog_content = "좋은 생각이야, 촬영기사님!",
  ui_story_5035_50350101_90_dialog_content = "<color=#e8d9bb>지지직── 지지지지직── 지직── </color>",
  ui_story_5035_50350101_91_dialog_content = "이상하네...",
  ui_story_5035_50350101_92_dialog_content = "<color=#e8d9bb>치지직── 치지지직──</color>",
  ui_story_5035_50350101_93_dialog_content = "으앗! 카메라가 고장 나 버렸어!",
  ui_story_5035_50350101_94_dialog_content = "(설마 물어내라고 하진 않겠지?!)",
  ui_story_5035_50350101_95_dialog_content = "<color=#e8d9bb>치지지직──</color>",
  ui_story_5035_50350101_96_dialog_content = "(아, 아까 그건 뭐야?!)",
  ui_story_5035_50350101_97_dialog_content = "도대체 무슨 일입니까?",
  ui_story_5035_50350101_98_dialog_content = "아하하, 이게 대체 무슨 일일까? 일반 방 밖으로 나가서 한번 확인해 보면...",
  ui_story_5035_50350101_99_dialog_content = "어라?!",
  ui_story_5035_50350101_100_dialog_content = "뷰파인더에 보이는 화면이 다시 정상으로 돌아왔잖아?",
  ui_story_5035_50350101_101_dialog_content = "대체 무슨 짓을 하는 겁니까?",
  ui_story_5035_50350101_102_dialog_content = "그건 제작팀한테 물어봐야지!",
  ui_story_5035_50350101_103_dialog_content = "「소름 끼치는 유령 저택」에서 영화를 찍는다고 하더니,\n무서운 일이라곤 하나도 안 일어나고 있잖아.",
  ui_story_5035_50350101_104_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5035_50350101_105_dialog_content = "어휴, 정말. 이 지하실이 마지막 촬영 장소야.",
  ui_story_5035_50350101_106_dialog_content = "계속 이랬다간 오늘 촬영은 실패로 끝나 버린다구.",
  ui_story_5035_50350101_107_dialog_content = "<color=#e8d9bb>또옥... 똑...</color>",
  ui_story_5035_50350101_108_dialog_content = "이상하네요. 이 소린 또 어디서 나는 걸까요...",
  ui_story_5035_50350101_109_dialog_content = "그냥 물방울 떨어지는 소리일 뿐입니다. 지레 겁먹지 마세요.",
  ui_story_5035_50350101_110_dialog_content = "응? 물방울 떨어지는 소리라고?",
  ui_story_5035_50350101_111_dialog_content = "화장실은 위층에 있는데...?",
  ui_story_5035_50350101_112_dialog_content = "<color=#e8d9bb>휘잉──</color>",
  ui_story_5035_50350101_113_dialog_content = "이, 이 촛불들은 뭐지...?",
  ui_story_5035_50350101_114_dialog_content = "<color=#e8d9bb>딸랑... 딸랑...</color>",
  ui_story_5035_50350101_115_dialog_content = "<anim type=Shake><size=50>그어어──</size></anim>",
  ui_story_5035_50350101_116_dialog_content = "<anim type=Shake><size=50>꺄아아아아아악!</size></anim>",
  ui_story_5035_50350101_117_dialog_content = "<anim type=Shake><size=50>살려줘어어어어어! 난 아직 죽고 싶지 않...</size></anim>",
  ui_story_5035_50350101_118_dialog_content = "<color=#e8d9bb>콰당──</color>",
  ui_story_5035_50350101_119_dialog_content = "<color=#e8d9bb>치직... 치직... 치지지지직...</color>",
  ui_story_5035_50350101_120_dialog_content = "<color=#e8d9bb>스카이워커호, 함교</color>",
  ui_story_5035_50350101_121_dialog_content = "으음...",
  ui_story_5035_50350101_122_dialog_content = "어라?",
  ui_story_5035_50350101_123_dialog_content = "이런 일이 다 있네...!",
  ui_story_5035_50350101_124_dialog_content = "바이스, 뭐 보고 있어?",
  ui_story_5035_50350101_125_dialog_content = "아, PlayerName. 일어났구나? 좋은 아침이야!",
  ui_story_5035_50350101_126_dialog_content = "「데일리 스쿠프 속보」 읽고 있었어.",
  ui_story_5035_50350101_127_dialog_content = "어? 이런 아침부터 움브라톤 신문이 어디서 난 건데?",
  ui_story_5035_50350101_128_dialog_content = "아까 웬디가 배달하러 왔을 때 같이 가져온 건데, 재미있어 보여서 받아 뒀어.",
  ui_story_5035_50350101_129_dialog_content = "PlayerName, 여기 이 기사 좀 봐!",
  ui_story_5035_50350101_130_dialog_content = "음, 어디 볼까...",
  ui_story_5035_50350101_131_dialog_content = "「바람과 함께 사라지다! 어떤 삼류 공포 영화 여주인공의 기묘한 실종」?!",
  ui_story_5035_50350101_132_dialog_content = "확실히 움브라톤은 이런 사건이 일어나도 이상할 게 없는 곳이긴 한데...",
  ui_story_5035_50350101_133_dialog_content = "아무래도 노이즈 마케팅 냄새가 나는걸?",
  ui_story_5035_50350101_134_dialog_content = "그거 말고, PlayerName. 더 위에 있는 거, 더 위에 있는 기사 말한 거야...",
  ui_story_5035_50350101_135_dialog_content = "「권투 시합 현장 취재」, 「메가톤급 인기 가수 데뷔」...",
  ui_story_5035_50350101_136_dialog_content = "<color=#FFB400>「안데르센 비명의 집 그랜드 오픈」?!</color>",
  ui_story_5035_50350101_137_dialog_content = "바로 그거야~",
  ui_story_5035_50350101_138_dialog_content = "광고 문구가 엄청 무시무시해!\n「진짜 100% 리얼 초자연적 현상! 막다른 길에 울려 퍼지는 절규!」",
  ui_story_5035_50350101_139_dialog_content = "(이 「안데르센 비명의 집」이란 거 설마 니나가...)",
  ui_story_5035_50350101_140_dialog_content = "어때? 재미있을 것 같지~?",
  ui_story_5035_50350101_141_dialog_content = "전혀! 광고 문구만 봐도 대충 만든 티가 나잖아!",
  ui_story_5035_50350101_142_dialog_content = "에이, PlayerName 넌 하나도 안 궁금해? 진짜 리얼 초자연적 현상이라는데...",
  ui_story_5035_50350101_143_dialog_content = "(아, 바이스가 엄청 가고 싶어 하는 눈치네...)",
  ui_story_5035_50350101_144_dialog_content = "바이스, 정 그러면 우리 같이...",
  ui_story_5035_50350101_145_dialog_content = "더군다나! 맨 아래 쓰여 있는 한 줄을 빼 먹으면 안 되지, PlayerName!",
  ui_story_5035_50350101_146_dialog_content = "...「오픈 기념 고객 감사 혜택! 2인 동행 시 반값 할인」?!",
  ui_story_5035_50350101_147_dialog_content = "후후후훗~ PlayerName~",
  ui_story_5035_50350101_148_dialog_content = "내가 그럴 줄 알았어!",
  ui_story_5035_50350201_1_dialog_content = "<color=#e8d9bb>움브라톤 변경, 안데르센 비명의 집</color>",
  ui_story_5035_50350201_2_dialog_content = "정말 외진 곳이네.",
  ui_story_5035_50350201_3_dialog_content = "헤헤, 유령의 집은 이렇게 외딴곳에 지어야 더 으스스한 느낌이 드는 거야!",
  ui_story_5035_50350201_4_dialog_content = "쓱 보기만 해도 진짜 좀 음산한 느낌이 드는걸.",
  ui_story_5035_50350201_5_dialog_content = "저 앞에 있는 낡은 대문이 아마 입구겠지?",
  ui_story_5035_50350201_6_dialog_content = "빨리 와, PlayerName. 티켓도 꺼내구.",
  ui_story_5035_50350201_7_dialog_content = "음? PlayerName 님이시군요.",
  ui_story_5035_50350201_8_dialog_content = "역시... 이 유령의 집 이름을 봤을 때부터 이럴 것 같았다니까.",
  ui_story_5035_50350201_9_dialog_content = "또 만났네, 미노스! 여기서도 집사 일을 하는 거야?",
  ui_story_5035_50350201_10_dialog_content = "그렇습니다. 더 일찍 맞이하러 나왔어야 하는 건데, 제 응대에 부족함이 있었군요.",
  ui_story_5035_50350201_11_dialog_content = "그럼, PlayerName 님의 티켓도 제게 주시면 됩니다.",
  ui_story_5035_50350201_12_dialog_content = "미노스는 언제나처럼 친절하네.",
  ui_story_5035_50350201_13_dialog_content = "내 옆에 있는 얘는 바이스라고 해. 내 친한 친구야...",
  ui_story_5035_50350201_14_dialog_content = "검표원 씨, 안녕하세요! 궁금한 게 있는데요. 광고 문구에 나온 게 사실인가요?\n진짜로 「리얼 초자연적 현상」이 일어나는 건가요?",
  ui_story_5035_50350201_15_dialog_content = "...음, 초자연적 현상 마니아이기도 해.",
  ui_story_5035_50350201_16_dialog_content = "하하하, 물론입니다. 바이스 양, 이 저택에서 일어나는 초자연적 현상은 다 사실이랍니다.\n거짓일 경우 티겟을 100% 환불해 드리고 있습니다.",
  ui_story_5035_50350201_17_dialog_content = "아무쪼록 안데르센 비명의 집에서 짜릿하고 소름 돋는 여행을 즐겨 주시길 바랍니다.",
  ui_story_5035_50350201_18_dialog_content = "정말 너무너무 기대돼요!",
  ui_story_5035_50350201_19_dialog_content = "그러고 보니까 말인데, 설마 여기도... 니나가 최근 새로 시작한 사업 아이템이야?",
  ui_story_5035_50350201_20_dialog_content = "그렇습니다. 아가씨께선 최근 부동산 투자에 눈을 돌리셨습니다.\n그래서 사업 목적으로 이 저택을 사들여 유령의 집을 개장하셨지요.",
  ui_story_5035_50350201_21_dialog_content = "예상과는 조금 다른 결과이긴 하지만, 이 저택은 아가씨께서 구매하신 첫 부동산입니다.",
  ui_story_5035_50350201_22_dialog_content = "그래서 전 제가 가진 모든 능력을 발휘해 아가씨를 전력으로 지원해 드릴 겁니다.",
  ui_story_5035_50350201_23_dialog_content = "그리고 이 저택은 아가씨와 제가 심혈을 기울여 고른 결과물이기도 합니다.",
  ui_story_5035_50350201_24_dialog_content = "이런 대저택이라면 구매할 때 비용도 엄청 많이 들었겠지?",
  ui_story_5035_50350201_25_dialog_content = "그건 아닙니다. 오히려 이 저택은 이상할 정도로 저렴했거든요.",
  ui_story_5035_50350201_26_dialog_content = "게다가 유령의 집처럼 인테리어를 하는 데도 그다지 비용이 들지 않았지요.",
  ui_story_5035_50350201_27_dialog_content = "그래서 전 아가씨의 이번 선택이 아주 성공적일 것이라 예상합니다.\n어쩌면 정말로 돈을 버실 수 있을지도 모릅니다.",
  ui_story_5035_50350201_28_dialog_content = "<color=#e8d9bb>휘이잉── 휘이잉──</color>",
  ui_story_5035_50350201_29_dialog_content = "하하, 아직은 영업 초기 단계인 만큼 인기는 앞으로 차차 늘어날 겁니다...",
  ui_story_5035_50350201_30_dialog_content = "그렇지 않습니까, 아가씨?",
  ui_story_5035_50350201_31_dialog_content = "......",
  ui_story_5035_50350201_32_dialog_content = "이런, 아가씨께서 못 들으신 모양이군요.",
  ui_story_5035_50350201_33_dialog_content = "우리도 니나 양한테 인사하러 가자, PlayerName.",
  ui_story_5035_50350201_34_dialog_content = "앗... 잠깐만 기다려 주세요. 한 분씩 확인할게요.",
  ui_story_5035_50350201_35_dialog_content = "여 받으시라예! 참하게 생긴 검표원 언니야!",
  ui_story_5035_50350201_36_dialog_content = "빨리빨리! 이제 내 차례라구!",
  ui_story_5035_50350201_37_dialog_content = "페피, 뭐가 그렇게 급한 거야! 새치기하지 마!",
  ui_story_5035_50350201_38_dialog_content = "하이고? PlayerName 오빠야랑 바이스 언니 아입니꺼!",
  ui_story_5035_50350201_39_dialog_content = "좋은 아침이야, PlayerName! 오랜만에 보는구나.",
  ui_story_5035_50350201_40_dialog_content = "안데르센 비명의 집에 온 걸 환영해.\n미노스한테 말해서 두 사람 티켓값은 지인 특가로 계산하라고 해 둘게.",
  ui_story_5035_50350201_41_dialog_content = "저, 정말 고마워요!",
  ui_story_5035_50350201_42_dialog_content = "역시 널 데려오길 잘했다니까, PlayerName.",
  ui_story_5035_50350201_43_dialog_content = "어휴, 정말...",
  ui_story_5035_50350201_44_dialog_content = "그러고 보니까, 왜 갑자기 유령의 집을 차릴 생각을 하게 된 거야?",
  ui_story_5035_50350201_45_dialog_content = "왠지 모르겠지만 니나는 이런 걸 아주 무서워할 것 같았는데 말이지...",
  ui_story_5035_50350201_46_dialog_content = "그, 그거 정말 실례되는 말이거든, PlayerName!",
  ui_story_5035_50350201_47_dialog_content = "<color=#e8d9bb>싹둑!</color>",
  ui_story_5035_50350201_48_dialog_content = "다 확인했어~ 꼬마 손님들, 티켓 잘 챙겨~",
  ui_story_5035_50350201_49_dialog_content = "고맙심더!\n고마워!\n고마워요!",
  ui_story_5035_50350201_50_dialog_content = "근데... 지금 보니까 옆에 <color=#FFB400>한 명</color>이 없네?",
  ui_story_5035_50350201_51_dialog_content = "어라?",
  ui_story_5035_50350201_52_dialog_content = "<size=50>히이이익?!</size>",
  ui_story_5035_50350201_53_dialog_content = "차, 참한 언니야. 괜히 겁주지 마이소!",
  ui_story_5035_50350201_54_dialog_content = "푸훗, 내 말은 할인을 받으려면 한 사람 더 있어야 한단 뜻이야.",
  ui_story_5035_50350201_55_dialog_content = "다음엔 잊지 말고 친구들을 더 많이 데려와 줘~",
  ui_story_5035_50350201_56_dialog_content = "그, 그라모 먼저 드가 보겠심더!",
  ui_story_5035_50350201_57_dialog_content = "재미있게 구경해~",
  ui_story_5035_50350201_58_dialog_content = "PlayerName, 봤지? 나처럼 유령을 무서워하는 사람들이 많으니까...",
  ui_story_5035_50350201_59_dialog_content = "유령의 집을 개업하려고 마음먹은 거야!",
  ui_story_5035_50350201_60_dialog_content = "이게 바로 내 창업 계획이야!",
  ui_story_5035_50350201_61_dialog_content = "일리가 있긴 한데...",
  ui_story_5035_50350201_62_dialog_content = "<color=#e8d9bb>바스락... 바스락...</color>",
  ui_story_5035_50350201_63_dialog_content = "히익?!",
  ui_story_5035_50350201_64_dialog_content = "설마 이 이상한 소리도 니나 양이 준비한 건가...?",
  ui_story_5035_50350201_65_dialog_content = "어? 니나?",
  ui_story_5035_50350201_66_dialog_content = "나, 난 모르는 일이야아아아!",
  ui_story_5035_50350201_67_dialog_content = "크오오...",
  ui_story_5035_50350201_68_dialog_content = "캬악!",
  ui_story_5035_50350201_69_dialog_content = "암귀였잖아?!",
  ui_story_5035_50350201_70_dialog_content = "으, 진짜! 몰래 숨어서 사람 놀래키지 좀 말란 말이야!",
  ui_story_5035_50350202_1_dialog_content = "<color=#e8d9bb>타앙!</color>",
  ui_story_5035_50350202_2_dialog_content = "다행히 옷은 더러워지지 않았군요.",
  ui_story_5035_50350202_3_dialog_content = "미노스, 이건 네 탓이야. 손님들이랑 날 위해서 이런 위험은 미리 알아챘어야지.",
  ui_story_5035_50350202_4_dialog_content = "옳으신 말씀입니다, 아가씨. 이에 대한 벌은 달게 받겠습니다.",
  ui_story_5035_50350202_5_dialog_content = "(오늘따라 니나가 많이 엄격하네.)",
  ui_story_5035_50350202_6_dialog_content = "PlayerName 일행은 오늘 여기 처음 온 거니까, 네가 두 사람을 안내해 줘.",
  ui_story_5035_50350202_7_dialog_content = "그리고 저택 안에 있는 <color=#FFB400>그 사람</color>도 파트너십 계약이랑 금액 문제를\n논의하려고 널 기다리고 있을 거야.",
  ui_story_5035_50350202_8_dialog_content = "아까부터 참고 기다리기 힘들었겠네?",
  ui_story_5035_50350202_9_dialog_content = "그렇지 않습니다, 아가씨를 도와 이 유령의 집을 잘 경영하는 것만이 제...",
  ui_story_5035_50350202_10_dialog_content = "됐어. 벌이니까 지금 내 눈앞에서 사라져.",
  ui_story_5035_50350202_11_dialog_content = "...알겠습니다, 아가씨.",
  ui_story_5035_50350202_12_dialog_content = "<color=#e8d9bb>안데르센 비명의 집, 1층 복도</color>",
  ui_story_5035_50350202_13_dialog_content = "이곳이 바로 안데르센 비명의 집의 첫 번째 층입니다.",
  ui_story_5035_50350202_14_dialog_content = "이 저택은 구조가 복잡한 편입니다.\n사람을 현혹하는 가짜 문과 가짜 창문이 아주 많이 있지요.",
  ui_story_5035_50350202_15_dialog_content = "이동 경로를 기억해 두지 않으면 쉽게 길을 잃어버리고 말 겁니다.",
  ui_story_5035_50350202_16_dialog_content = "만약 두 분께서 첫 번째 층에 가 보고 싶으시다면 저를 따라...",
  ui_story_5035_50350202_17_dialog_content = "아, 죄송합니다. 만약 두 번째 층에 가 보고 싶으시다면...",
  ui_story_5035_50350202_18_dialog_content = "(미노스가 정신이 다른 데 팔려 있는 것 같네.)",
  ui_story_5035_50350202_19_dialog_content = "미노스, 혹시 니나랑 또 다퉜어?",
  ui_story_5035_50350202_20_dialog_content = "니나가 아까 말한 「그 사람」은 누구고?",
  ui_story_5035_50350202_21_dialog_content = "약간의 의견 충돌이 있었을 뿐입니다.\nPlayerName 님과 바이스 양께 못난 모습을 보여드리고 말았군요.",
  ui_story_5035_50350202_22_dialog_content = "구체적으로는 이틀 전에 아가씨를 만나러 이곳에 온 남자 때문입니다.",
  ui_story_5035_50350202_23_dialog_content = "그때 안데르센 비명의 집은 막 개업한 상태였는데,\n그 남자는 단번에 이곳을 장기간 대여하고 싶다고 하더군요.",
  ui_story_5035_50350202_24_dialog_content = "이곳을 영화 촬영지로 사용하려던 것 같았습니다.",
  ui_story_5035_50350202_25_dialog_content = "그런 일이 있었어요? 근데 유령의 집은 이미 영업을 시작했잖아요.",
  ui_story_5035_50350202_26_dialog_content = "저도 그래서 거절했습니다. 하지만 그쪽에선 뜻을 거둘 생각이 없었는지,\n대여 비용으로 적지 않은 값을 제시했습니다.",
  ui_story_5035_50350202_27_dialog_content = "미노스 너 설마... 그래서 바로 좋다고 해 버린 건 아니지?",
  ui_story_5035_50350202_28_dialog_content = "당연히 아닙니다만... 아가씨와 그 남자 사이에서 교섭을 하려니,\n어쩔 수 없이 입장이 조금 난처해졌습니다.",
  ui_story_5035_50350202_29_dialog_content = "미노스도 난처하다고 느낄 때가 있구나.",
  ui_story_5035_50350202_30_dialog_content = "하하, PlayerName 님, 놀리지 마십시오.",
  ui_story_5035_50350202_31_dialog_content = "제가 문제를 해결할 때의 모습만 본다면 뭐든 다 할 수 있어 보이겠지만,\n저도 난감할 때가 있습니다.",
  ui_story_5035_50350202_32_dialog_content = "아무튼 이 문제를 해결할 방법을 하나 생각해 내긴 했습니다.",
  ui_story_5035_50350202_33_dialog_content = "전 일단 그 남자의 제안에 동의했고, 함께 협력 작업을 진행하기로 했습니다.\n제가 임시 프로듀서 역할을 맡아 이 저택의 홍보 영상을 촬영하는 겁니다.",
  ui_story_5035_50350202_34_dialog_content = "임시 프로듀서 역할을 맡는다면, 협력 작업이 마무리되고 난 후,\n그 남자가 아가씨의 비즈니스 파트너가 될 자격이 있는지 판단할 자격이 생길 테니까요.",
  ui_story_5035_50350202_35_dialog_content = "니나 양한테 그 부분에 대해 제대로 설명해 줬나요?",
  ui_story_5035_50350202_36_dialog_content = "어젯밤에 갑자기 결정된 사안이기 때문에 아직...",
  ui_story_5035_50350202_37_dialog_content = "니나 양이 왜 화가 난 건지 알겠네요.",
  ui_story_5035_50350202_38_dialog_content = "아무튼 두 분께선 손님이시니, 아가씨와 제 일 때문에 그렇게 염려하지 않으셔도 됩니다.",
  ui_story_5035_50350202_39_dialog_content = "그저 편하게 저를 따라 이 비명의 집의 모든 곳을 둘러봐 주시면 됩니다.",
  ui_story_5035_50350202_40_dialog_content = "아니면 두 분의 의향대로 자유롭게 둘러볼 수 있는 방식을 더 선호하십니까?",
  ui_story_5035_50350202_41_dialog_content = "바이스, 넌 어때?",
  ui_story_5035_50350202_42_dialog_content = "으음, 유령의 집인데 관리자가 안내해 준다면,\n역시 스릴과 재미가 좀 줄어드는 느낌이긴 해...",
  ui_story_5035_50350202_43_dialog_content = "그러니까 어디에 갈지는 우리가 선택하는 게 더 좋겠어!",
  ui_story_5035_50350202_44_dialog_content = "이제 곧 보게 될 「리얼 초자연적 현상」이 어떨지 진짜 너무 기대돼!",
  ui_story_5035_50350202_45_dialog_content = "하하, 그렇다면 저는 뒤에서 따라갈 테니 앞장서시지요.",
  ui_story_5035_50350202_46_dialog_content = "응!",
  ui_story_5035_50350202_47_dialog_content = "그러고 보니까 궁금한 게 있는데요, 미노스 씨...",
  ui_story_5035_50350202_48_dialog_content = "이 저택에 진짜로 그 유령이란 게 있어요? 니나 양은 유령 같은 걸 아주 무서워하잖아요?",
  ui_story_5035_50350202_49_dialog_content = "근데 물건들을 어떻게 이 저택 안까지 옮길 수 있었던 거죠?",
  ui_story_5035_50350202_50_dialog_content = "으음, 아가씨께선 뭔가 생각하고 계신 게 있으니 그런 광고를 내신 것이라 생각합니다.",
  ui_story_5035_50350202_51_dialog_content = "후후후! 당연히 존재하지! 그리고 그건 반드시 이 저택 안에 있어!",
  ui_story_5035_50350202_52_dialog_content = "어? 앞에 누가 있네?",
  ui_story_5035_50350202_53_dialog_content = "난 이 저택에서 일어나는 현상을 낱낱이 파헤치기 위해 여기 왔어!",
  ui_story_5035_50350202_54_dialog_content = "흥미가 있다면 너도 내 「미스터리 탐험대」에 들어올래?",
  ui_story_5035_50350202_55_dialog_content = "우와! 들어갈래! 들어갈래!",
  ui_story_5035_50350202_56_dialog_content = "이게 아니지, 잠깐만! 저기, 넌...?",
  ui_story_5035_50350202_57_dialog_content = "내 이름은 리리카, 유명한 「심령 탐정」이야!",
  ui_story_5035_50350202_58_dialog_content = "으윽?!",
  ui_story_5035_50350202_59_dialog_content = "내 이름... 한번도 들어 본 적 없어?",
  ui_story_5035_50350202_60_dialog_content = "저, 전혀 들어 본 적 없는데.",
  ui_story_5035_50350202_61_dialog_content = "휴...",
  ui_story_5035_50350202_62_dialog_content = "그럼 다시 한번 물어볼게. 내 「미스터리 탐험대」에 들어올래?",
  ui_story_5035_50350202_63_dialog_content = "이건 진짜 얻기 힘든 기회라구!",
  ui_story_5035_50350202_64_dialog_content = "기회?",
  ui_story_5035_50350202_65_dialog_content = "그래, 내 옆에 있는 「세로로」 보여?",
  ui_story_5035_50350202_66_dialog_content = "카메라를 들고 있는... 작은 새 말하는 거야?",
  ui_story_5035_50350202_67_dialog_content = "새가 아니라 박쥐 같은데.",
  ui_story_5035_50350202_68_dialog_content = "세로로는 새가 아니야! 박쥐도 아니고! 얘는 내 촬영 파트너란 말이야!",
  ui_story_5035_50350202_69_dialog_content = "(촬영 파트너?)",
  ui_story_5035_50350202_70_dialog_content = "미노스, 설마 이 사람이 아까 네가 같이 협력 작업을 하기로 했다는 제작 스태프야?",
  ui_story_5035_50350202_71_dialog_content = "아닙니다. 리리카 양은 제가 기억하기론... 오늘 오신 관람객 중 한 분이십니다.",
  ui_story_5035_50350202_72_dialog_content = "다른 스태프는 없어. 이건 나만의 촬영 기획이니까!",
  ui_story_5035_50350202_73_dialog_content = "안데르센 비명의 집의 수수께끼를 파헤치는 과정을 다큐멘터리로 찍을 거야!",
  ui_story_5035_50350202_74_dialog_content = "요즘 움브라톤 영화 업계에선 이렇게 일상처럼 찍는 생활 다큐멘터리가 유행하고 있거든.",
  ui_story_5035_50350202_75_dialog_content = "내 다큐멘터리에 출연만 하면, 대스타가 될 수 있을지도 몰라!",
  ui_story_5035_50350202_76_dialog_content = "아, 참. 그러고 보니까 아직 세 사람한테 이름을 안 물어봤네.",
  ui_story_5035_50350202_77_dialog_content = "난 PlayerName, 얘는 바이스야. 그리고 여기 이쪽은...",
  ui_story_5035_50350202_78_dialog_content = "미노스 씨 맞지? 아까 들었어!",
  ui_story_5035_50350202_79_dialog_content = "하하, 리리카 양은 기억력이 좋으시군요.",
  ui_story_5035_50350202_80_dialog_content = "당연하지! 난 프로 탐정이라구. 자, 그럼 카메라 쪽 보고~ 스마일!",
  ui_story_5035_50350202_81_dialog_content = "<color=#e8d9bb>찰칵──</color>",
  ui_story_5035_50350202_82_dialog_content = "헤헷, 같이 사진도 찍었으니까 세 사람은 이제부터 내 탐험대원이야!",
  ui_story_5035_50350202_83_dialog_content = "열심히 할게!",
  ui_story_5035_50350202_84_dialog_content = "손님들이 즐거우시다면 저는 만족합니다.",
  ui_story_5035_50350202_85_dialog_content = "저기... 일단 내 의견도 물어 봐주긴 해야 하는 거 아닐까...",
  ui_story_5035_50350301_1_dialog_content = "자, 그럼 촬영을 시작하자!",
  ui_story_5035_50350301_2_dialog_content = "앗, 잠깐만...",
  ui_story_5035_50350301_3_dialog_content = "도움이 필요하십니까?",
  ui_story_5035_50350301_4_dialog_content = "스토리라인의 완성도를 위해서 입구 쪽을 먼저 촬영하는 게 좋지 않을까?",
  ui_story_5035_50350301_5_dialog_content = "그런 거 있잖아...",
  ui_story_5035_50350301_6_dialog_content = "「여러분 안녕하세요. 오늘은 여러분과 함께 안데르센 비명의 집을 탐험할 거예요」 같은 거.",
  ui_story_5035_50350301_7_dialog_content = "(그런 장면들도 다 설정에 따라 찍는 거였어?!)",
  ui_story_5035_50350301_8_dialog_content = "오른쪽에 있는 출구로 나가시면 됩니다.\n입구 쪽에서 이 저택의 주인이신 니나 아가씨께서 맞이해 주실 겁니다.",
  ui_story_5035_50350301_9_dialog_content = "안심하십시오. 짧게 나갔다 오는 것이니 재입장을 위해\n티겟을 다시 구매하실 필요는 없습니다.",
  ui_story_5035_50350301_10_dialog_content = "오케이! 그럼 됐어. 이따 다시 만나!",
  ui_story_5035_50350301_11_dialog_content = "리리카 말인데, 프로 느낌이 물씬 나는걸!",
  ui_story_5035_50350301_12_dialog_content = "왠지 리리카가 찍은 다큐멘터리의 결과물이 어떨지 기대되기 시작했어.",
  ui_story_5035_50350301_13_dialog_content = "바이스, 너도 영화 촬영에 대해 좀 알아?",
  ui_story_5035_50350301_14_dialog_content = "음... 잘 아는 수준은 아니고 조금 아는 정도야.",
  ui_story_5035_50350301_15_dialog_content = "<size=30>스카이워커호 휴식실에서 있는 프로젝터로 이런 영상을 몇 편 봤었거든...</size>",
  ui_story_5035_50350301_16_dialog_content = "뭐어?!",
  ui_story_5035_50350301_17_dialog_content = "난 전혀 몰랐는데? 테, 테이프는 어디서 난 거야?",
  ui_story_5035_50350301_18_dialog_content = "우리가 움브라톤에 갈 때마다 샀지.",
  ui_story_5035_50350301_19_dialog_content = "돌아오기 전에 항상 거리에서 파격 세일 중인 비디오테이프를 사곤 하거든.",
  ui_story_5035_50350301_20_dialog_content = "맞다! 저번엔 그렇게 산 테이프들 중에서 내 인생 감독을 찾았다니까!",
  ui_story_5035_50350301_21_dialog_content = "갑자기 「인생 감독」...?",
  ui_story_5035_50350301_22_dialog_content = "공포 영화를 잘 찍더라구. 소재도 내 취향이랑 딱 맞고!",
  ui_story_5035_50350301_23_dialog_content = "PlayerName 너도 관심 있으면 빌려줄게! 내 추천작은...",
  ui_story_5035_50350301_24_dialog_content = "스톱! 소, 소개 안 해 줘도 돼!",
  ui_story_5035_50350301_25_dialog_content = "여기도 공포 영화 마니아가 있었습니까?",
  ui_story_5035_50350301_26_dialog_content = "어떤 작품을 추천해 주실지 꼭 들어보고 싶군요.",
  ui_story_5035_50350301_27_dialog_content = "아, 좋은 아침입니다, 조니 감독님. 스태프들은 이제부터 일을 시작하려는 모양이군요.",
  ui_story_5035_50350301_28_dialog_content = "자, 스태프들, 여기 있는 물건들을 다 서쪽 복도에 옮겨 두면 돼.\n그래, 부딪히지 않게 조심하고.",
  ui_story_5035_50350301_29_dialog_content = "그렇습니다. 미노스 씨.\n도와주실 게 아니라면 지나갈 수 있게 길을 좀 비켜 주실 수 있을까요?",
  ui_story_5035_50350301_30_dialog_content = "그러지요.",
  ui_story_5035_50350301_31_dialog_content = "<color=#e8d9bb>딸랑딸랑── 딸랑──</color>",
  ui_story_5035_50350301_32_dialog_content = "음? 저것도... 촬영 소품 중 하나입니까?",
  ui_story_5035_50350301_33_dialog_content = "저 관 말입니까? 이건 클라이맥스 장면에서만 사용할 소품입니다. 진짜 같지 않습니까?",
  ui_story_5035_50350301_34_dialog_content = "음, 고증이 꽤 잘 되어 있군요.",
  ui_story_5035_50350301_35_dialog_content = "정확히 어떤 장면에 사용되는 겁니까?",
  ui_story_5035_50350301_36_dialog_content = "...그건 일단 비밀입니다.",
  ui_story_5035_50350301_37_dialog_content = "앗, 조니... 제작 스태프...?",
  ui_story_5035_50350301_38_dialog_content = "(저 옷차림은...)",
  ui_story_5035_50350301_39_dialog_content = "서, 설마, 설마 당신이 바로...",
  ui_story_5035_50350301_40_dialog_content = "그 <color=#FFB400>조니 감독</color>, 조니 매들린?!",
  ui_story_5035_50350301_41_dialog_content = "네, 접니다. 당신은...?",
  ui_story_5035_50350301_42_dialog_content = "저 완전 팬이에요!",
  ui_story_5035_50350301_43_dialog_content = "(서, 설마? 진짜 이 사람이라고?)",
  ui_story_5035_50350301_44_dialog_content = "......",
  ui_story_5035_50350301_45_dialog_content = "하하...",
  ui_story_5035_50350301_46_dialog_content = "그것참 영광이군요. 제 신작 《비명을 멈추면 안 돼!》를 많이 기대해 주시기 바랍니다.",
  ui_story_5035_50350301_47_dialog_content = "앞으로도 차차 더 좋은 작품을 선보일 예정입니다.",
  ui_story_5035_50350301_48_dialog_content = "이 안데르센 비명의 집에 찾아온 이유도 바로 그것 때문이죠.",
  ui_story_5035_50350301_49_dialog_content = "하룻밤이 지났는데, 그래서 생각은 좀 해 보셨습니까? 미노스 씨.",
  ui_story_5035_50350301_50_dialog_content = "제가 중요한 비즈니스 사안을 숙고 없이 결정한 적은 지금껏 단 한 번도 없었습니다.\n이 파트너십도 일단은 단기간만 유효합니다.",
  ui_story_5035_50350301_51_dialog_content = "그러시다면 이번 영화의 출연진부터 소개해 드리죠.",
  ui_story_5035_50350301_52_dialog_content = "이쪽은 골디라고 합니다. 베일에 싸인 배역과 연기 대결을 펼치게 될 겁니다.\n이번 작품의 주인공이라고 할 수 있죠.",
  ui_story_5035_50350301_53_dialog_content = "골디는 얼마 전에 데뷔한 가수이기도 합니다. 인기가 아주 대단하죠.",
  ui_story_5035_50350301_54_dialog_content = "하이~ 골디예요! 잘 부탁드려요!",
  ui_story_5035_50350301_55_dialog_content = "어? 움브라톤 신문에서 본...",
  ui_story_5035_50350301_56_dialog_content = "「권투 시합 현장 취재」, 「메가톤급 인기 가수 데뷔」...",
  ui_story_5035_50350301_57_dialog_content = "<color=#FFB400>「안데르센 비명의 집 그랜드 오픈」?!</color>",
  ui_story_5035_50350301_58_dialog_content = "바로 그 인기 가수?!",
  ui_story_5035_50350301_59_dialog_content = "유후~ 그거 저 맞아요! 그렇다구 너무 크게 소리 지르진 마세요~",
  ui_story_5035_50350301_60_dialog_content = "조니 감독님이 완전 운이 좋았죠. 이번 촬영은 제가 데뷔하기 전에 계약한 거거든요.",
  ui_story_5035_50350301_61_dialog_content = "지금이었으면 그 정도 게런티론 턱도 없었을 거예요!",
  ui_story_5035_50350301_62_dialog_content = "그건...",
  ui_story_5035_50350301_63_dialog_content = "아하하, 농담이에요! 이러나저러나 전 아직 신인인걸요.",
  ui_story_5035_50350301_64_dialog_content = "이 영화는 제 데뷔 후 첫 영상 작품이니까, 두 배로 더 노력할 거예요.",
  ui_story_5035_50350301_65_dialog_content = "저랑 제 「행운의 탄환」이 계속 감독님을 지켜 줄 거예요!",
  ui_story_5035_50350301_66_dialog_content = "하하, 당신의 잠재력에 거는 기대가 큽니다.",
  ui_story_5035_50350301_67_dialog_content = "아, 잊을 뻔했군요. 이쪽에 있는 다른 한 분은 여자2 역을 맡은 새디입니다.",
  ui_story_5035_50350301_68_dialog_content = "......",
  ui_story_5035_50350301_69_dialog_content = "난 진지하게 소개할 가치도 없단 거야?",
  ui_story_5035_50350301_70_dialog_content = "그래, 휴, 어차피 난 엑스트라일 뿐이니까, 내 비위를 맞춰 줄 필요는 없겠네.",
  ui_story_5035_50350301_71_dialog_content = "난 「666 새디」라는 의적, 난 절대 안 해 뻔뻔한 척♪",
  ui_story_5035_50350301_72_dialog_content = "그냥 새디라고 불러.",
  ui_story_5035_50350301_73_dialog_content = "배우 일도... 의적이 해야 하는 일인 거야?",
  ui_story_5035_50350301_74_dialog_content = "음... 경기가 안 좋을 땐 의적이란 신분은 잠깐 내려놓고, 다른 의뢰를 받기도 하거든.",
  ui_story_5035_50350301_75_dialog_content = "그래도 언제나 의적 정신을 지키면서 일을 하고 있어.",
  ui_story_5035_50350301_76_dialog_content = "너희는? 방금 도착한 단체 엑스트라야?",
  ui_story_5035_50350301_77_dialog_content = "아! 아, 아니야! 우린 그냥 유령의 집에 놀러 온 관람객이야.",
  ui_story_5035_50350301_78_dialog_content = "음, 정확히 말하면 <color=#FFB400>「진짜 초자연적 현상」</color>을 보려고 여기 온 사람들이지!",
  ui_story_5035_50350301_79_dialog_content = "「진짜 초자연적 현상」?",
  ui_story_5035_50350301_80_dialog_content = "진짜 이 세상에 유령이랑 초자연적 현상이 있단 말이야?",
  ui_story_5035_50350301_81_dialog_content = "응, 난 쭉 그렇다고 믿어 왔어!",
  ui_story_5035_50350301_82_dialog_content = "유령이 있고... 초자연적 현상이 일어난단 거지? 이 안데르센 비명의 집에서?",
  ui_story_5035_50350301_83_dialog_content = "응, 미노스 씨가 그렇다고 했어!",
  ui_story_5035_50350301_84_dialog_content = "후훗, 혹시 무섭다면 제가 지켜 줄게요, 새디! 난 안 무섭거든요!",
  ui_story_5035_50350301_85_dialog_content = "재미없어.",
  ui_story_5035_50350301_86_dialog_content = "?!",
  ui_story_5035_50350301_87_dialog_content = "다 티켓 팔려고 그러는 거잖아. 난 그런 거 안 믿어.",
  ui_story_5035_50350301_88_dialog_content = "그런 것치곤 엄청 관심 있어 보이는데...",
  ui_story_5035_50350301_89_dialog_content = "하하하, 새디 양은 참 솔직한 성격이시군요.",
  ui_story_5035_50350301_90_dialog_content = "미노스 씨, 더는 망설일 시간이 없습니다. 저흰 이미 현장 체크를 시작했습니다.",
  ui_story_5035_50350301_91_dialog_content = "그렇다면 편한 대로 하십시오.",
  ui_story_5035_50350301_92_dialog_content = "그러죠. 골디, 새디, 가자.",
  ui_story_5035_50350301_93_dialog_content = "...새디?",
  ui_story_5035_50350301_94_dialog_content = "뭐, 뭘 좀 떨어트린 것 같아. 잠깐 좀 찾아볼게.",
  ui_story_5035_50350301_95_dialog_content = "그렇게 해. 어차피 지금부터 찍을 몇 장면은 새디가 안 나오기도 하니까.",
  ui_story_5035_50350301_96_dialog_content = "찾고 나면 미노스 씨랑 같이 현장으로 와.",
  ui_story_5035_50350301_97_dialog_content = "네, 제가 안내하도록 하지요.",
  ui_story_5035_50350301_98_dialog_content = "그럼 우린 여기서 리리카를 기다리자. 기다리는 동안 새디를 도와주면 될 것 같아.",
  ui_story_5035_50350301_99_dialog_content = "네. 지금쯤 리리카 양이 돌아올 때가 됐군요.",
  ui_story_5035_50350301_100_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5035_50350301_101_dialog_content = "발소리가 들려!",
  ui_story_5035_50350301_102_dialog_content = "리리카, 여기야!",
  ui_story_5035_50350301_103_dialog_content = "......?",
  ui_story_5035_50350301_104_dialog_content = "『...날 부르는 건가?』",
  ui_story_5035_50350301_105_dialog_content = "뭐, 뭐라는 거야?!",
  ui_story_5035_50350301_106_dialog_content = "이 암귀들은 길도 안 잃어버린답니까?",
  ui_story_5035_50350301_107_dialog_content = "지금 그게 문제가 아니잖아! 우선은...",
  ui_story_5035_50350301_108_dialog_content = "빨리 녀석들을 쓰러트려야 해!",
  ui_story_5035_50350302_1_dialog_content = "암귀가 어떻게 들어온 거지...",
  ui_story_5035_50350302_2_dialog_content = "개장하기 전에 아가씨와 제가 모든 방을 돌며 안전 검사를 진행했습니다.",
  ui_story_5035_50350302_3_dialog_content = "하지만 이 저택은 구조가 무척 복잡합니다.\n설령 암귀가 다른 입구를 통해 들어왔다 해도, 당장은 파악하기 어렵습니다.",
  ui_story_5035_50350302_4_dialog_content = "(입구 쪽에 계시는 아가씨께서 무사하셨으면 좋겠습니다만...)",
  ui_story_5035_50350302_5_dialog_content = "여러분, 다친 곳은 없으십니까?",
  ui_story_5035_50350302_6_dialog_content = "암귀 같은 건 한두 번 붕 휘둘러 주면 휙 날아가서 괜찮아.",
  ui_story_5035_50350302_7_dialog_content = "그나저나, 새디가 잃어버렸다는 게 뭐야?",
  ui_story_5035_50350302_8_dialog_content = "으엑, 그건...",
  ui_story_5035_50350302_9_dialog_content = "그냥 조니한테 둘러대려고 한 소리야.",
  ui_story_5035_50350302_10_dialog_content = "이래 봬도 난 의적이야. 자기 물건을 잃어버릴 리가 없잖아.",
  ui_story_5035_50350302_11_dialog_content = "그냥 조니랑 같이 가서 현장 체크하기 귀찮아서 그런 거야.\n계속 설교 듣기 싫어서 그런 거도 있고.",
  ui_story_5035_50350302_12_dialog_content = "그, 그래?",
  ui_story_5035_50350302_13_dialog_content = "게다가 아까 얘기하면서 겸사겸사 조니의 현장 체크리스트도 가져왔어.",
  ui_story_5035_50350302_14_dialog_content = "(그렇게 아무렇지 않게 얘기하면 안 되지! 그건 절도잖아!)",
  ui_story_5035_50350302_15_dialog_content = "나, 난 그냥 현장 체크리스트에 어떤 장소들이 나와 있을까\n궁금해서 그런 거야. 근데 못 알아보겠더라구.",
  ui_story_5035_50350302_16_dialog_content = "그래서 여기 남아 있으려고 핑계 좀 댄 거야.",
  ui_story_5035_50350302_17_dialog_content = "부탁 좀 할게... 여기에 뭐라고 쓰여 있는지 좀 봐주라.",
  ui_story_5035_50350302_18_dialog_content = "아하~ 감이 딱 왔어~",
  ui_story_5035_50350302_19_dialog_content = "새디 너도 우리 「미스터리 탐험대」에 들어오고 싶은 거지?",
  ui_story_5035_50350302_20_dialog_content = "뭐어어어어?",
  ui_story_5035_50350302_21_dialog_content = "아, 아니거든! 너희 하고 싶은 거 다 해 Make a fuss♪\n아니 근데 말은 최소한 Make sense♪",
  ui_story_5035_50350302_22_dialog_content = "<anim type=Shake><size=45>잘</size> 봐 난 제대로 된 <size=45>백점짜리</size> 의적, <size=45>저</size> 가짜에 <size=30>놀란다면</size> <size=45>코찔찔이 인정</size>♪</anim>",
  ui_story_5035_50350302_23_dialog_content = "<anim type=Shake><size=50>내가</size> 온 <size=45>이유</size> 그건 <size=30>그저</size> <size=45>구경</size>♪</anim>",
  ui_story_5035_50350302_24_dialog_content = "<anim type=Shake><size=45>너흰</size> <size=30>걸려들지</size> <size=45>저 흰</size> 머리 <size=45>수작</size>♪</anim>",
  ui_story_5035_50350302_25_dialog_content = "(풉, 완전 열정적인 반응이네!)",
  ui_story_5035_50350302_26_dialog_content = "어차피 이렇게 됐으니까, 그 체크리스트에 어떤 곳들이 적혀 있는지 내가 좀 볼게!",
  ui_story_5035_50350302_27_dialog_content = "그럼 부탁해. 자, 여기.",
  ui_story_5035_50350302_28_dialog_content = "어디 보자. 음, 목적지는 세 곳이네...",
  ui_story_5035_50350302_29_dialog_content = "<color=#FFB400>1층 침실</color>, <color=#FFB400>2층 전시실</color>, <color=#FFB400>지하실</color>, 이렇게 적혀 있어.",
  ui_story_5035_50350302_30_dialog_content = "그렇군요. 확실히 그 세 곳을 화면에 담으면 뛰어난 시각적 효과를 얻을 수 있을 겁니다.",
  ui_story_5035_50350302_31_dialog_content = "그러면 이 세 곳을 하나씩 답사해 보도록 하지요.",
  ui_story_5035_50350302_32_dialog_content = "답사? 무슨 답사?",
  ui_story_5035_50350302_33_dialog_content = "아하하! 내 「미스터리 탐험대」가 벌써 행동을 시작한 거야?",
  ui_story_5035_50350302_34_dialog_content = "난 가서 오프닝 부분을 찍어 왔는데, 여긴 어땠어?",
  ui_story_5035_50350302_35_dialog_content = "아, 리리카! 왔구나!",
  ui_story_5035_50350302_36_dialog_content = "소개해 줄게! 여기 있는 여자애는 우리의 새로운 멤버... 새디야!",
  ui_story_5035_50350302_37_dialog_content = "멤버 안 할 거야.",
  ui_story_5035_50350302_38_dialog_content = "안녕, 새디! 난 리리카라고 해.\n취미는 영상 촬영, 초자연적 현상 조사야! 좋아하는 음식은 해산물 요리고!",
  ui_story_5035_50350302_39_dialog_content = "멤버 안 한다니까...",
  ui_story_5035_50350302_40_dialog_content = "자~ 카메라를 보고 웃어 봐! 우리랑 같이 유령의 정체를 파헤쳐 보는 거야!",
  ui_story_5035_50350302_41_dialog_content = "그러니까 멤버 안 할 거... 됐어, 그래, 앞으로 잘 부탁해.",
  ui_story_5035_50350302_42_dialog_content = "예~이!",
  ui_story_5035_50350302_43_dialog_content = "수수께끼 탐험대! 전원 집합 완료!",
  ui_story_5035_50350302_44_dialog_content = "어때, 어때? 다들 어디부터 탐험을 시작할지 단서는 좀 찾았어?",
  ui_story_5035_50350302_45_dialog_content = "응! 새디가 영화 제작팀의 장소 체크리스트를 가져와 줬거든.\n그래서 거기에 나와 있는 장소에 가 보기로 했어.",
  ui_story_5035_50350302_46_dialog_content = "우와, 만들어 놓은 장소 체크리스트가 있었다니 엄청 운이 좋았네!",
  ui_story_5035_50350302_47_dialog_content = "새디 대원! 우리 《비명의 집 탐험》에 아주 큰 공을 세워 줬구나!",
  ui_story_5035_50350302_48_dialog_content = "오프닝 크레딧에 커다랗게 이름을 넣어 줄게!",
  ui_story_5035_50350302_49_dialog_content = "됐어.",
  ui_story_5035_50350302_50_dialog_content = "그리고 엔딩 크레딧이랑 홍보 포스터에도!",
  ui_story_5035_50350302_51_dialog_content = "그러지 마...",
  ui_story_5035_50350302_52_dialog_content = "Special Thanks에도 넣고! 테이프 커버랑...",
  ui_story_5035_50350302_53_dialog_content = "..................",
  ui_story_5035_50350302_54_dialog_content = "그럼 시간이 없으니까 빨리 첫 번째 장소에 가 보자!",
  ui_story_5035_50350302_55_dialog_content = "좋아, 1층 침실을 향해... 출발!",
  ui_story_5035_50350302_56_dialog_content = "《비명의 집 탐험》의 정식 촬영이 시작됐어! 원하는 만큼 비명 질러도 돼!",
  ui_story_5035_50350401_1_dialog_content = "<color=#e8d9bb>안데르센 비명의 집, 1층 복도</color>",
  ui_story_5035_50350401_2_dialog_content = "(길이 이리저리 너무 많이 구부러져 있어서 머리가 다 어지러워...)",
  ui_story_5035_50350401_3_dialog_content = "여러분, 조금만 더 참으십시오. 앞에 있는 두 복도만 더 돌면 도착합니다.",
  ui_story_5035_50350401_4_dialog_content = "미노스는 역시 참 섬세하고 자상하다니까.",
  ui_story_5035_50350401_5_dialog_content = "이렇게 보니까 이 유령의 집을 꽤 잘 꾸며 놨구나.",
  ui_story_5035_50350401_6_dialog_content = "천장이랑 이어져 있는 계단, 거미줄 모양의 창문...\n놀러 온 사람 모두 어쩌지 하면서 길을 빙빙 돌겠어.",
  ui_story_5035_50350401_7_dialog_content = "아닙니다. 사실은 이 저택의 원래 모습을 보존해 둔 것뿐입니다.",
  ui_story_5035_50350401_8_dialog_content = "이 디자인들은 모두 이 저택의 첫 번째 주인... 에스더 부인의 작품입니다.",
  ui_story_5035_50350401_9_dialog_content = "「에스더 부인」은 어떤 사람이죠?",
  ui_story_5035_50350401_10_dialog_content = "우와! 시작됐다, 시작됐어! 이 저택의 역사적인 배경을 설명하는 전개!",
  ui_story_5035_50350401_11_dialog_content = "영상에 이 부분이 들어가면 으시시한 분위기를 고조시킬 수 있을 거야!",
  ui_story_5035_50350401_12_dialog_content = "미노스 씨, 이쪽으로 조금만 더 와 줘. 응, 좋아, 조금만 더.",
  ui_story_5035_50350401_13_dialog_content = "이 정도면 되겠습니까, 리리카 양?",
  ui_story_5035_50350401_14_dialog_content = "좋아요! 그럼 시작해 주세요!",
  ui_story_5035_50350401_15_dialog_content = "크흠, 이 저택의 주인이 몇 번 바뀌었는지는 알 수 없지만,\n에스더 부인은 지금까지도 그 이름이 전해져 내려오는 이 저택의 첫 주인이었습니다.",
  ui_story_5035_50350401_16_dialog_content = "에스더 부인은 가족들이 없었기에, 자신의 하인들과 이곳에서 생활했습니다.",
  ui_story_5035_50350401_17_dialog_content = "또한 그 부인은 성격이 괴팍했고, 심각한 수준의 망상증을 앓고 있었습니다.",
  ui_story_5035_50350401_18_dialog_content = "매일 해 질 무렵이 되면, 그녀는 더러운 무언가가 저택에 침입해서\n자신의 목숨을 거둬 갈까 걱정하기 시작했지요...",
  ui_story_5035_50350401_19_dialog_content = "꺄아아아아아!",
  ui_story_5035_50350401_20_dialog_content = "왜, 왜 그래? 바이스!",
  ui_story_5035_50350401_21_dialog_content = "아하하... 아무것도 아니야. 중요한 부분에선 나도 모르게 비명을 지르곤 하거든.",
  ui_story_5035_50350401_22_dialog_content = "그리곤요? 그다음엔 어떻게 됐죠?",
  ui_story_5035_50350401_23_dialog_content = "그리고...",
  ui_story_5035_50350401_24_dialog_content = "에스더 부인은 자신의 모든 재산을 투자해 저택을 「미궁」으로 개조했습니다.",
  ui_story_5035_50350401_25_dialog_content = "쓸모없는 창문과 계단을 많이 추가했지요. 잠도 매일 다른 침실에서 잤습니다.",
  ui_story_5035_50350401_26_dialog_content = "그리고 그녀의 침대 앞엔 항상 양초가 켜져 있었습니다.\n온종일 벽에 그녀의 흔들리는 얼굴을 비추면서 말입니다.",
  ui_story_5035_50350401_27_dialog_content = "꺄악──!",
  ui_story_5035_50350401_28_dialog_content = "양초가 꺼지면 그녀는 비명을 질렀습니다.\n모든 하인들을 놀라게 만들 정도로 아주 처량한 비명이었지요.",
  ui_story_5035_50350401_29_dialog_content = "결국, 에스더 부인은 거대한 화재 때문에 사망했습니다.",
  ui_story_5035_50350401_30_dialog_content = "촛불이 방을 불태웠고, 화마에 휩싸인 부인은 당황한 나머지 살기 위해 무작정 도망쳤습니다.",
  ui_story_5035_50350401_31_dialog_content = "그러나 그녀 자신이 만든 「미궁」이 오히려 그녀의 목숨을 위협하는\n감옥이 되어 버린 겁니다.",
  ui_story_5035_50350401_32_dialog_content = "하인들 역시 그녀를 찾기 위해 황급히 여러 방을 돌아다녔지만,\n끝내 그녀는 그 불바다 속에서 숨을 거두고 말았습니다.",
  ui_story_5035_50350401_33_dialog_content = "이전 주인들도 잘 때 하인들이 분주하게 뛰어다니는 소리를 들었다고 하더군요.",
  ui_story_5035_50350401_34_dialog_content = "저택의 모든 층은 제가 청소해 두긴 했습니다만, 혹시 모르지요.\n어쩌면 제가 발견하지 못한 구석에 아직도 그때 빠져나오지 못한 하인의...",
  ui_story_5035_50350401_35_dialog_content = "꺄아아아아아!",
  ui_story_5035_50350401_36_dialog_content = "이 이야기는 여기까지입니다.",
  ui_story_5035_50350401_37_dialog_content = "컷! 좋아요! 아주 훌륭했어요!",
  ui_story_5035_50350401_38_dialog_content = "때마침 저희도 1층 침실에 도착했군요. 다들 부딪히지 않게 조심...",
  ui_story_5035_50350401_39_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_5035_50350401_40_dialog_content = "아... 죄송합니다.",
  ui_story_5035_50350401_41_dialog_content = "보신 것처럼 방금 제가 연 문도 가짜 문이었군요.",
  ui_story_5035_50350401_42_dialog_content = "저처럼 벽에 부딪히지 않게 여러분 모두 조심하시기 바랍니다...",
  ui_story_5035_50350401_43_dialog_content = "괜찮아?",
  ui_story_5035_50350401_44_dialog_content = "이 옆, 오른쪽에 있는 게 진짜 문입니다. 다들 저를 따라오시지요.",
  ui_story_5035_50350401_45_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5035_50350401_46_dialog_content = "와───",
  ui_story_5035_50350401_47_dialog_content = "어라?",
  ui_story_5035_50350401_48_dialog_content = "이 침실... 좀 평범하게 생겼네. 심지어 좀 낡았어.",
  ui_story_5035_50350401_49_dialog_content = "하지만 위압감이 느껴지는 실내 장면을 찍기엔 좋은 채광을 가지고 있군요.",
  ui_story_5035_50350401_50_dialog_content = "새디 님, 현장 체크리스트를 건네주시겠습니까?\n구체적으로 어떤 장면들을 찍으려고 하는지 확인을 좀 해야겠군요.",
  ui_story_5035_50350401_51_dialog_content = "받아.",
  ui_story_5035_50350401_52_dialog_content = "아, 그렇군요, 이런 장면을...",
  ui_story_5035_50350401_53_dialog_content = "다들! 빨리 와 봐! 와서 이거 좀 봐!",
  ui_story_5035_50350401_54_dialog_content = "여기 진짜 텔레비전 같이 생긴 소품이 있어!",
  ui_story_5035_50350401_55_dialog_content = "우리 이 텔레비전 앞에서 기념사진 한 장 찍자!",
  ui_story_5035_50350401_56_dialog_content = "하하, 이 텔레비전은 유령의 집의 세트나 촬영용 소품이 아니랍니다.",
  ui_story_5035_50350401_57_dialog_content = "그 화재 속에서 살아남은 유물 중 하나라고 할 수 있지요.",
  ui_story_5035_50350401_58_dialog_content = "(대단하네. 이런 건 일루미나에나 있는 줄 알았는데...)",
  ui_story_5035_50350401_59_dialog_content = "흥, 평범해 보이는데. 그냥 흔히 보이는 골동품이잖아.",
  ui_story_5035_50350401_60_dialog_content = "텔레비전을 얕보면 안 돼! 잘만 사용하면 훌륭한 공포 영화 소품이 되어 주거든.",
  ui_story_5035_50350401_61_dialog_content = "새카만 브라운관에 자기가 아닌 뭔가의 모습이 비친다거나...",
  ui_story_5035_50350401_62_dialog_content = "브라운관에서 갑자기 긴 머리의 무서운 여자가 기어 나온다든가...",
  ui_story_5035_50350401_63_dialog_content = "아무튼, 이 옆에서 같이 사진 찍자!",
  ui_story_5035_50350401_64_dialog_content = "<color=#e8d9bb>치지직...</color>",
  ui_story_5035_50350401_65_dialog_content = "어...?",
  ui_story_5035_50350401_66_dialog_content = "서, 설마... 아니지?",
  ui_story_5035_50350401_67_dialog_content = "설마 진짜...",
  ui_story_5035_50350401_68_dialog_content = "<color=#e8d9bb>치직... 치지지직...</color>",
  ui_story_5035_50350401_69_dialog_content = "안녕하신가.",
  ui_story_5035_50350401_70_dialog_content = "뭔가 나타났다아아아아아!",
  ui_story_5035_50350401_71_dialog_content = "오! 좋아, 이거야! 유령 등장씬은 절대 못 놓치지!",
  ui_story_5035_50350401_72_dialog_content = "안녕! 혹시 이 유령의 집의 출연자야? 아니면 가면을 쓴 변태야?\n그것도 아니면 영상에 씐 유령?",
  ui_story_5035_50350401_73_dialog_content = "(그런 게 어딨어!)",
  ui_story_5035_50350401_74_dialog_content = "당신은 날 모르겠지만, 난 당신을 알고 있지.",
  ui_story_5035_50350401_75_dialog_content = "괜찮아, 이제부터 알아가면 되잖아. 카메라를 보고 인사나 해 봐. 치즈~!",
  ui_story_5035_50350401_76_dialog_content = "게임을 하나 하고 싶군.",
  ui_story_5035_50350401_77_dialog_content = "좋아! 문제없어!",
  ui_story_5035_50350401_78_dialog_content = "(그렇게 마음대로 좋다고 하면 어떡해!)",
  ui_story_5035_50350401_79_dialog_content = "이거, 분명히 유령의 집에서 준비해 둔 테이프일 거야.",
  ui_story_5035_50350401_80_dialog_content = "맞은 편에 있는 저 가면 쓴 사람, 리리카의 질문에 대답도 안 하잖아.",
  ui_story_5035_50350401_81_dialog_content = "묻는 말에 모두 대답해 줄 이유는 없다.",
  ui_story_5035_50350401_82_dialog_content = "?!",
  ui_story_5035_50350401_83_dialog_content = "왜냐하면 내가 준비해 둔 퀴즈 세 가지가 자네들을 기다리고 있기 때문이지.",
  ui_story_5035_50350401_84_dialog_content = "지금부터 게임을 시작하지.",
  ui_story_5035_50350401_85_dialog_content = "자네들이 이 침실에 들어선 순간, 이 방의 문은 잠겼네.",
  ui_story_5035_50350401_86_dialog_content = "<color=#e8d9bb>철컥, 철컥──</color>",
  ui_story_5035_50350401_87_dialog_content = "안 열려... 저, 저 사람이 한 말이 진짠가 봐!",
  ui_story_5035_50350401_88_dialog_content = "자네들이 너무 불리한 상황에 놓이지 않도록...",
  ui_story_5035_50350401_89_dialog_content = "열쇠가 어디에 숨겨져 있는지 알려주겠네.",
  ui_story_5035_50350401_90_dialog_content = "살든지 죽든지, 선택은 자네들 몫이야.",
  ui_story_5035_50350401_91_dialog_content = "저기, 미노스. 지금 이 상황은 뭐야?",
  ui_story_5035_50350401_92_dialog_content = "PlayerName 님, 집사의 미덕은 언제나 침착함을 유지하는 것이지만,\n이 점은 분명히 말씀을 드려야 할 것 같습니다...",
  ui_story_5035_50350401_93_dialog_content = "지금 눈앞에서 벌어지고 있는 이 일은 제게도 돌발 상황입니다.",
  ui_story_5035_50350401_94_dialog_content = "잘 듣게. 첫 번째 문제일세. 이 저택의 주인은 누구인가?",
  ui_story_5035_50350401_95_option_content = "(에스더 부인)",
  ui_story_5035_50350401_96_dialog_content = "정말 어처구니가 없군...",
  ui_story_5035_50350401_97_dialog_content = "누가 이 저택에 새로운 생명을 부여했는지 까맣게 잊어버릴 줄이야.",
  ui_story_5035_50350401_98_dialog_content = "안타깝게도 자네들이 그녀를 만나 사죄하긴 어렵겠군.",
  ui_story_5035_50350401_99_dialog_content = "PlayerName 님, 니나 아가씨를 잊으시면 안 됩니다...",
  ui_story_5035_50350401_100_option_content = "(니나)",
  ui_story_5035_50350401_101_dialog_content = "정말 어처구니가 없군...",
  ui_story_5035_50350401_102_dialog_content = "첫 번째 소유주였던 그 부인을 전혀 신경 쓰지 않는다니.",
  ui_story_5035_50350401_103_dialog_content = "「지옥」에서 그녀와 만나면 경외심을 보이도록 하게.",
  ui_story_5035_50350401_104_dialog_content = "PlayerName 님, 제가 에스더 부인의 이야기를 들려드린 지\n아직 10분밖에 지나지 않았습니다만...",
  ui_story_5035_50350401_105_dialog_content = "불공평해! 이, 이거 완전 말장난이잖아!",
  ui_story_5035_50350401_106_dialog_content = "두 번째 문제일세. 이 저택에는 총 몇 개의 문이 있지?",
  ui_story_5035_50350401_107_dialog_content = "(좋아, 이번 문제의 답은 정해져 있으니까...)",
  ui_story_5035_50350401_108_dialog_content = "미노스, 부탁해.",
  ui_story_5035_50350401_109_dialog_content = "마침 이 저택의 지도를 가지고 있긴 하지만,\n혹시 모르니 다시 한번 자세히 확인해 보겠습니다...",
  ui_story_5035_50350401_110_dialog_content = "그런 걸 누가 알아? 솔직히 가면 쓴 그쪽의 변태 씨도 모르지?",
  ui_story_5035_50350401_111_dialog_content = "......",
  ui_story_5035_50350401_112_dialog_content = "...망했다!",
  ui_story_5035_50350401_113_dialog_content = "답이 없는 것도 답이라네. 안타깝게도 오답이군.",
  ui_story_5035_50350401_114_dialog_content = "엣?! 그런 게 어디 있어! 난 내가 대답하겠다고 한 적 없단 말이야!",
  ui_story_5035_50350401_115_dialog_content = "나중에 내 영상이 공개되고 나면, 관객들이 너한테 어떤 평가를 남길지\n잘 생각해 보는 게 좋을걸!",
  ui_story_5035_50350401_116_dialog_content = "망했어. 마지막 문제도 못 맞히면...",
  ui_story_5035_50350401_117_dialog_content = "세 번째 문제일세. 텔레비전 밑에는 열쇠가 없네.",
  ui_story_5035_50350401_118_dialog_content = "어? 이번 문제는... 질문이 아니라 그냥 서술인데?",
  ui_story_5035_50350401_119_dialog_content = "PlayerName, 일단 안전하게 확인이나 한 번 해보자.",
  ui_story_5035_50350401_120_dialog_content = "나한테 맡겨.",
  ui_story_5035_50350401_121_dialog_content = "...앗!",
  ui_story_5035_50350401_122_dialog_content = "진짜로 열쇠가 있어... 정말 이렇게 간단하게 찾도록 해 뒀다고?",
  ui_story_5035_50350401_123_dialog_content = "음, 내가 가져올게...",
  ui_story_5035_50350401_124_dialog_content = "정답이 아닐세. 지름길로 통하는 환상을 너무 쉽게 믿어 버렸군.",
  ui_story_5035_50350401_125_dialog_content = "정답률이 0이 되었으니, 이제부터는 <color=#FFB400>심판의 시간</color>일세.",
  ui_story_5035_50350401_126_dialog_content = "뭐라고?!",
  ui_story_5035_50350401_127_dialog_content = "이건 너무 불합리하잖아... 미노스, 무슨 대책 없어?",
  ui_story_5035_50350401_128_dialog_content = "그래! 방에 있는 밀실이라든가, 비밀 문이라든가, 집사용 열쇠 같은 거 없을까?",
  ui_story_5035_50350401_129_dialog_content = "지금이 바로 연달아 발생한 위기 상황이 반전되는 스토리가 등장할 타이밍이야!",
  ui_story_5035_50350401_130_dialog_content = "<color=#e8d9bb>쿠르르릉... 쿠르르릉...</color>",
  ui_story_5035_50350401_131_dialog_content = "뭔가 이 방을 향해 달려오고 있는 것 같은데...",
  ui_story_5035_50350401_132_dialog_content = "짧게 말하겠습니다. 우선 제 제안이라는 건 그저...",
  ui_story_5035_50350401_133_dialog_content = "크아아~",
  ui_story_5035_50350401_134_dialog_content = "<anim type=Shake><size=45>크어어~!</size></anim>",
  ui_story_5035_50350401_135_dialog_content = "암귀가 문을 부수고 들어올 겁니다. 지금입니다, 도망치십시오!",
  ui_story_5035_50350501_1_dialog_content = "키이익~!",
  ui_story_5035_50350501_2_dialog_content = "내가 나서야겠네!",
  ui_story_5035_50350501_3_dialog_content = "크르르르~!",
  ui_story_5035_50350501_4_dialog_content = "(어라? 이 암귀... 때렸는데 뭔가 말랑말랑하네?)",
  ui_story_5035_50350501_5_dialog_content = "(느낌이 꼭... 엄청 푹신한 매트리스에 주먹질을 한 것 같잖아?!)",
  ui_story_5035_50350501_6_dialog_content = "우아아아, 안 돼! 집중하자!",
  ui_story_5035_50350501_7_dialog_content = "세로로, 출동!",
  ui_story_5035_50350501_8_dialog_content = "크어억~!",
  ui_story_5035_50350501_9_dialog_content = "(어라? 때리지도 않았는데 쓰러져 버렸잖아? 뭐야... 장난치는 건가?)",
  ui_story_5035_50350501_10_dialog_content = "너도 꽤 하는구나. 몰랐네.",
  ui_story_5035_50350501_11_dialog_content = "아...",
  ui_story_5035_50350501_12_dialog_content = "흐응, 알면 됐어!",
  ui_story_5035_50350501_13_dialog_content = "이러나저러나 내가 바로 수수께끼 탐험대의 대장이니까.",
  ui_story_5035_50350501_14_dialog_content = "여기야! 여기! 돌파구를 찾았어! 《비명의 집 탐험》의 반전 스토리 등장!",
  ui_story_5035_50350501_15_dialog_content = "휴우~ 정말 주인공만이 겪을 수 있는 스토리라인이었어!",
  ui_story_5035_50350501_16_dialog_content = "PlayerName, 우리도 단숨에 가자!",
  ui_story_5035_50350501_17_dialog_content = "응!",
  ui_story_5035_50350501_18_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5035_50350501_19_dialog_content = "아야야...",
  ui_story_5035_50350501_20_dialog_content = "넌...!",
  ui_story_5035_50350501_21_dialog_content = "게임 오버.",
  ui_story_5035_50350501_22_dialog_content = "?!",
  ui_story_5035_50350501_23_dialog_content = "(이건 <color=#FFB400>그분</color>의 목소리군요.)",
  ui_story_5035_50350501_24_dialog_content = "여, 영상 속 유령이... 유령이 나타났잖아?!",
  ui_story_5035_50350501_25_dialog_content = "가면 쓴 변태라고 해서 미, 미안해요!",
  ui_story_5035_50350501_26_dialog_content = "여, 여러분. 보시는 것처럼 여기 이분이 바로 이 저택에 감춰져 있던 「유령」 중 하나예요...",
  ui_story_5035_50350501_27_dialog_content = "카메라가 조금 떨리긴 하지만, 이 저택의 초자연적 현상을 밝히는 게 제 사명이니까...",
  ui_story_5035_50350501_28_dialog_content = "쉽게 물러서진 않을 거예요. 오히려...",
  ui_story_5035_50350501_29_dialog_content = "어, 음, 저... 더 가까이 가 볼게요. 더 잘 보일 수 있도록요.",
  ui_story_5035_50350501_30_dialog_content = "더, 더 가까이...",
  ui_story_5035_50350501_31_dialog_content = "......",
  ui_story_5035_50350501_32_dialog_content = "리리카! 다, 당장 돌아와!",
  ui_story_5035_50350501_33_dialog_content = "바이스, PlayerName. 마, 마, 만약에 나한테 무슨 일이 생기면...\n이 다큐멘터리를 부탁해...",
  ui_story_5035_50350501_34_dialog_content = "너희들...",
  ui_story_5035_50350501_35_dialog_content = "흐에에에에에엥...",
  ui_story_5035_50350501_36_dialog_content = "도망칠 길은 없다네.",
  ui_story_5035_50350501_37_dialog_content = "<color=#e8d9bb>위잉! 위이이이이잉!</color>",
  ui_story_5035_50350501_38_dialog_content = "어, 어쩐지 암귀가 전기톱을 들고나올 것 같더라!",
  ui_story_5035_50350501_39_dialog_content = "(어? 내가 왜 「어쩐지」라고 말한 거지?)",
  ui_story_5035_50350501_40_dialog_content = "소년들이여, 저자들에게 비명을 선사해 주게나.",
  ui_story_5035_50350502_1_dialog_content = "(이상해. 원래라면 난 「초자연적 현상」 같은 건 절대 안 믿었을 거야...)",
  ui_story_5035_50350502_2_dialog_content = "(눈앞에 있는 이 「가면을 쓴 사람」이 암귀를 제어하고 있는 걸 보면,\n이클립스 쪽 녀석이 분명해.)",
  ui_story_5035_50350502_3_dialog_content = "(근데 저 사람한테선 다크매터가 하나도 느껴지지 않아.)",
  ui_story_5035_50350502_4_dialog_content = "(설마 진짜 초자연적 현상인 건가...?)",
  ui_story_5035_50350502_5_dialog_content = "받아라!",
  ui_story_5035_50350502_6_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5035_50350502_7_dialog_content = "(어? 내 공격을 피했잖아?)",
  ui_story_5035_50350502_8_dialog_content = "그럼 한 번 더! 속사...",
  ui_story_5035_50350502_9_dialog_content = "잠깐만!",
  ui_story_5035_50350502_10_dialog_content = "어?",
  ui_story_5035_50350502_11_dialog_content = "진짜 무기로 싸우는 것도 이 정도면 됐잖아. 이러다 업무 중 상해라도 입으면 큰일이라고.",
  ui_story_5035_50350502_12_dialog_content = "맞아, 맞아.",
  ui_story_5035_50350502_13_dialog_content = "연기는 이 정도 했으면 됐다구!",
  ui_story_5035_50350502_14_dialog_content = "...이 옷 너무 더워.",
  ui_story_5035_50350502_15_dialog_content = "코르곤이랑 쿠마, 그리고 페기?!",
  ui_story_5035_50350502_16_dialog_content = "그렇다는 건, 가면을 쓴 그 이상한 사람은 바로...",
  ui_story_5035_50350502_17_dialog_content = "후후, 다들 아까 《샤크 쏘우》는 어땠어? 재밌었지?",
  ui_story_5035_50350502_18_dialog_content = "그럼 내가 이 방에서 데리고 나가 줄게.",
  ui_story_5035_50350502_19_dialog_content = "역시 니나였구나!",
  ui_story_5035_50350502_20_dialog_content = "으, 정말이지... 니나 양 때문에 진짜 깜짝 놀랐잖아요!",
  ui_story_5035_50350502_21_dialog_content = "미노스 씨만 빼고, 우리 다 깜빡 속은 거야?",
  ui_story_5035_50350502_22_dialog_content = "아까 전투가 끝나고 나서 미노스 씨가 나한테 잠깐 카메라로 찍지 말아 달라고 했었거든.",
  ui_story_5035_50350502_23_dialog_content = "뭐야, 난 또 금기 같은 걸 깰까 봐 그런 건 줄 알았는데,\n그냥 영업 비밀이 유출될까 봐 그런 거였네!",
  ui_story_5035_50350502_24_dialog_content = "하하, 변명을 해 보자면 이 공포 이벤트는 온전히 아가씨께서 직접 기획하신 겁니다.",
  ui_story_5035_50350502_25_dialog_content = "저도 모르고 있다가, 아가씨께서 저 문으로 걸어 들어오실 때가 돼서야\n가면을 쓴 사람이 아가씨라는 사실을 눈치챘습니다.",
  ui_story_5035_50350502_26_dialog_content = "아무래도 아가씨의 목소리와 체형은 아주 익숙하니까요.",
  ui_story_5035_50350502_27_dialog_content = "진짜 짜증 나...",
  ui_story_5035_50350502_28_dialog_content = "(평소랑은 전혀 다른 말투까지 썼는데!)",
  ui_story_5035_50350502_29_dialog_content = "미노스 말이 맞아. 이건 내가 특별히 손님들을 위해 준비한 추가 체험이야.",
  ui_story_5035_50350502_30_dialog_content = "오늘 처음으로 선보인 거니까, 여러분의 소중한 의견을 들려주면 고맙겠어!",
  ui_story_5035_50350502_31_dialog_content = "음, 그럼 나부터 얘기할게.",
  ui_story_5035_50350502_32_dialog_content = "우선, 텔레비전으로 메시지를 전달하는 거 말인데,\n우리랑 실시간으로 소통하곤 있었지만 내용이 너무 딱딱했어.",
  ui_story_5035_50350502_33_dialog_content = "으, 기억해 둘게.",
  ui_story_5035_50350502_34_dialog_content = "퀴즈로 출제한 세 문제도 별로였어. 좀 낚인 것 같다는 느낌이야.",
  ui_story_5035_50350502_35_dialog_content = "아하하, 그랬구나...",
  ui_story_5035_50350502_36_dialog_content = "샌드백 역할로 나온 그 아인족 오로리안들은 더 말할 것도 없고...",
  ui_story_5035_50350502_37_dialog_content = "후후... 이제 드디어 내가 설명해 줄 차례가 됐네!",
  ui_story_5035_50350502_38_dialog_content = "다들 저 사람들이 벗어 둔 암귀 코스튬을 확인해 봐!",
  ui_story_5035_50350502_39_dialog_content = "어?! 손에 느껴지는 이 질감...",
  ui_story_5035_50350502_40_dialog_content = "그래! 이건 내가 저 사람들을 위해 특수 제작한 업무용 코스튬이야.",
  ui_story_5035_50350502_41_dialog_content = "입고 나면, 평범한 루미나틱스 공격은 통증 없이 막을 수 있어!",
  ui_story_5035_50350502_42_dialog_content = "쳇, 유일한 단점이라면...",
  ui_story_5035_50350502_43_dialog_content = "...그 옷 너무 더워.",
  ui_story_5035_50350502_44_dialog_content = "(왜 이런 이상한 물건까지 만든 거야?!)",
  ui_story_5035_50350502_45_dialog_content = "이러면 일반 손님들도 암귀랑 맞설 때의 긴장감과 공포를 맛볼 수 있잖아!",
  ui_story_5035_50350502_46_dialog_content = "이게 바로 리얼하고 만질 수도 있는 「초자연적 현상」인 거야~",
  ui_story_5035_50350502_47_dialog_content = "가슴 속 깊은 곳에 잠들어 있는 어둠에 대한 공포를 이겨낼 수 있는\n오로리안은 거의 없는 법이니까. 그리고...",
  ui_story_5035_50350502_48_dialog_content = "이번에 갑자기 느낀 건데, 감시 카메라로 통해 나 때문에 놀란 사람들의\n얼굴을 보니까 조금 재미있더라구.",
  ui_story_5035_50350502_49_dialog_content = "후후후훗~!",
  ui_story_5035_50350502_50_dialog_content = "(역시 부자야... 비싸고 귀한 감시 카메라를 이런 일에 쓸 수 있다니...)",
  ui_story_5035_50350502_51_dialog_content = "(아가씨께서 이상한 취미에 눈을 뜨신 것 같군요...)",
  ui_story_5035_50350502_52_dialog_content = "그랬구나. 어쨌든 조니가 맡긴 의뢰보단 조금 더 믿음이 가네.",
  ui_story_5035_50350502_53_dialog_content = "장소 세팅, 스태프 모집, 코스튬 제작까지... 다 네가 혼자서 한 거야?",
  ui_story_5035_50350502_54_dialog_content = "정말 대단하네... 난 너처럼 자기 사업을 하는 멋진 언니라면 리스펙트해.",
  ui_story_5035_50350502_55_dialog_content = "저, 정말?!",
  ui_story_5035_50350502_56_dialog_content = "크흠... 그럼 언제든 우리 안데르센 비명의 집에 아르바이트하러 와~",
  ui_story_5035_50350502_57_dialog_content = "그건 좀 천천히 생각해 볼게.",
  ui_story_5035_50350502_58_dialog_content = "조니가 맡긴 임무를 그냥 생각 없이 받은 거긴 하지만,\n하기로 한 건 끝까지 해 줄 생각이거든.",
  ui_story_5035_50350502_59_dialog_content = "아... 그랬구나.",
  ui_story_5035_50350502_60_dialog_content = "「진짜 100% 리얼 초자연적 현상」이라는 게\n암귀 코스튬을 입은 친구들을 말하는 거였다니...",
  ui_story_5035_50350502_61_dialog_content = "왜 그래, 바이스?\n수수께끼 탐험대의 대장인 내가 보기엔 너 지금 좀 실망한 것 같아!",
  ui_story_5035_50350502_62_dialog_content = "그게... 신문에서 광고 문구를 봤을 때부터 엄청 기대했었거든.",
  ui_story_5035_50350502_63_dialog_content = "근데 이 「초자연적 현상」의 실체가 드러나는 걸 보고 있으니까,\n꼭 마술 트릭을 알아버린 것 같이 마음이 괴로워졌어.",
  ui_story_5035_50350502_64_dialog_content = "(...바이스가 실망하는 것도 어느 정도 이해가 돼.)",
  ui_story_5035_50350502_65_dialog_content = "괘, 괜찮아, 바이스! 아직 우리가 안 가 본 구석엔 네가 말한 그런 게 있을지도 몰라...",
  ui_story_5035_50350502_66_dialog_content = "진짜 그럴까...",
  ui_story_5035_50350502_67_dialog_content = "(아, 내가 지금 뭔 소리를 하고 있는 거야!)",
  ui_story_5035_50350502_68_dialog_content = "죄송합니다, 바이스 양. 아가씨와 제가 실제 초자연적 현상을 기대하시는\n손님 여러분의 마음을 충분히 헤아리지 못했습니다.",
  ui_story_5035_50350502_69_dialog_content = "미안해, 바이스.",
  ui_story_5035_50350502_70_dialog_content = "사, 사과할 필요까진 없어...\n사실 「초자연적 현상을 코앞에서 일어나게」 만드는 건 역시 좀...",
  ui_story_5035_50350502_71_dialog_content = "가능할 수도 있어!",
  ui_story_5035_50350502_72_dialog_content = "뭐?!",
  ui_story_5035_50350502_73_dialog_content = "심령 탐정을 하고 있는 내가 볼 땐, 초자연적 현상은 여전히 이 방에 존재할 가능성이 커!",
  ui_story_5035_50350502_74_dialog_content = "근데 니나 양이랑 미노스 씨가 벌써 다 얘기했잖아...",
  ui_story_5035_50350502_75_dialog_content = "맞아, 그치만 그건 두 사람이 인위적으로 세팅한 계획을 우리한테 알려 준 것뿐이잖아.",
  ui_story_5035_50350502_76_dialog_content = "그럼 두 사람이 세팅을 해 두지 않은 곳은 어떨까?",
  ui_story_5035_50350502_77_dialog_content = "가능성이 아예 없지는 않겠지만...",
  ui_story_5035_50350502_78_dialog_content = "완전히 가능성이 없는 게 아니라면, 완전히 가능성이 있는 거야!",
  ui_story_5035_50350502_79_dialog_content = "우리 수수께끼 탐험대가 추구하는 건 「공정한 절차」와\n「유령의 존재를 긍정하는 추정 원칙」이야!",
  ui_story_5035_50350502_80_dialog_content = "여긴 우리가 이 저택에서 돌아보려고 했던 곳 중에서 첫 번째 장소일 뿐이야.\n여기서 그만둬 버리면 다른 곳은 어떤지 어떻게 알겠어?",
  ui_story_5035_50350502_81_dialog_content = "그 말도 일리가 있는 것 같아!",
  ui_story_5035_50350502_82_dialog_content = "(저게 뭐가 일리가 있다는 거야!)",
  ui_story_5035_50350502_83_dialog_content = "맞아. 리리카의 말 논리 타당, 남았어 내겐 해야 할 임무 낭낭♪",
  ui_story_5035_50350502_84_dialog_content = "마침 시간은 일러, 빨리 출발하면 더 Easier♪",
  ui_story_5035_50350502_85_dialog_content = "예~이! 그럼 빨리 2층 전시실에 가 보자!",
  ui_story_5035_50350502_86_dialog_content = "《비명의 집 탐험》, 다시 한번 크랭크인!",
  ui_story_5035_50350502_87_dialog_content = "그렇다면 제가 계속 여러분을 안내할 수 있도록 해 주시면 감사하겠습니다.",
  ui_story_5035_50350502_88_dialog_content = "다만, 아가씨, 이 저택 안에 진짜 암귀가 몇 마리 들어와 있으므로 각별히 유의해 주십시오.",
  ui_story_5035_50350502_89_dialog_content = "그런 일이 있었어?",
  ui_story_5035_50350502_90_dialog_content = "내가 부주의했네... 물론 너도 마찬가지야!",
  ui_story_5035_50350502_91_dialog_content = "일이 이렇게 됐으니 우리도 꼬마 사장님을 돕자고.",
  ui_story_5035_50350502_92_dialog_content = "겸사겸사 내 톱한테도 진짜 처리할 만한 걸 던져줘야겠어.",
  ui_story_5035_50350502_93_dialog_content = "우리도 같이할래. 당연히 식량은 넉넉히 줘야 해!",
  ui_story_5035_50350502_94_dialog_content = "그리고 찬 바람도 충분히 쐬게 해 줘.",
  ui_story_5035_50350502_95_dialog_content = "그럼 여기서 갈라지자. 다들 조심해!",
  ui_story_5035_50350601_1_dialog_content = "<color=#e8d9bb>칙── 지직...</color>",
  ui_story_5035_50350601_2_dialog_content = "으앗?!",
  ui_story_5035_50350601_3_dialog_content = "리리카, 왜 그래?",
  ui_story_5035_50350601_4_dialog_content = "뷰파인더가... 갑자기 '번쩍'했어.",
  ui_story_5035_50350601_5_dialog_content = "고, 고장 났나...?",
  ui_story_5035_50350601_6_dialog_content = "응? 뭐가 고장 났다고?",
  ui_story_5035_50350601_7_dialog_content = "아, 아니야! 잠깐 확인 좀 해 볼게!",
  ui_story_5035_50350601_8_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5035_50350601_9_dialog_content = "에, 에...",
  ui_story_5035_50350601_10_dialog_content = "엣취──!",
  ui_story_5035_50350601_11_dialog_content = "여기 공기는 축축해, like 곰팡이 핀 카펫처럼 눅눅해♪",
  ui_story_5035_50350601_12_dialog_content = "<color=#e8d9bb>찰팍!</color>",
  ui_story_5035_50350601_13_dialog_content = "으, 이 카펫 무슨 물에 담궜다 뺀 것 같아!",
  ui_story_5035_50350601_14_dialog_content = "죄송합니다! 미끄러지지 않게 조심하십시오.",
  ui_story_5035_50350601_15_dialog_content = "최근 날씨가 무척 습한 탓입니다. 앞으로 이곳의 환기 시설을 보강하겠습니다.",
  ui_story_5035_50350601_16_dialog_content = "아, 이러면 안 돼요. 여기엔 이런저런 물건이 많이 있으니까 제대로 제습을 해야죠.",
  ui_story_5035_50350601_17_dialog_content = "이 물건들도... 첫 번째 집주인이 남겨 놓은 거야?",
  ui_story_5035_50350601_18_dialog_content = "네, 사들인 후에 발견했습니다만, 전 주인들이 잘 보관해 두었더군요.",
  ui_story_5035_50350601_19_dialog_content = "아가씨께서는 그들을 향한 존중의 의미로, 이 방을 원래 모습 그대로 유지하기로 하셨습니다.",
  ui_story_5035_50350601_20_dialog_content = "유지해 둔다면 손님들께서도 옛 주인의 취향을 느낄 수 있을 테고 말이지요.",
  ui_story_5035_50350601_21_dialog_content = "이 방을 촬영지로 선택한 건 상당히 훌륭한 선택입니다.",
  ui_story_5035_50350601_22_dialog_content = "옛 주인은 취향이... 참 독특했군요.",
  ui_story_5035_50350601_23_dialog_content = "왜 이렇게 만들었는지 모를 가구들은 일단 그렇다 치고...",
  ui_story_5035_50350601_24_dialog_content = "이 인형들은 보고만 있어도 좀 거북하네요.",
  ui_story_5035_50350601_25_dialog_content = "아, 먼지들도 좀 털어야 좋을 것 같아요. 쌓이면 치우기 어렵거든요...",
  ui_story_5035_50350601_26_dialog_content = "저... 바이스 양, 손님으로 오셨으니 그런 쪽에는 신경 써 주시지 않으셔도 됩니다.",
  ui_story_5035_50350601_27_dialog_content = "괜찮아요, 벌써 다 치웠어요!",
  ui_story_5035_50350601_28_dialog_content = "방문 쪽에 수건이 있으니 가져다드리겠습니다.",
  ui_story_5035_50350601_29_dialog_content = "으음?",
  ui_story_5035_50350601_30_dialog_content = "리리카 양, 왜 계속 문 근처에 서 계십니까? 혹시 도움이 필요하십니까?",
  ui_story_5035_50350601_31_dialog_content = "난 지금 초자연적인 사건이 일어나길 기다리고 있어!",
  ui_story_5035_50350601_32_dialog_content = "(기다린다고 일어날 리 없잖아!)",
  ui_story_5035_50350601_33_dialog_content = "흐이익!",
  ui_story_5035_50350601_34_dialog_content = "와아! 일어난 건가? 일어났어?",
  ui_story_5035_50350601_35_dialog_content = "아깐 못 봤는데, 인형 더미 속에 카드가 한 장 숨겨져 있었어.",
  ui_story_5035_50350601_36_dialog_content = "아... 또 니나가 준비한 무시무시한 소품인가?",
  ui_story_5035_50350601_37_dialog_content = "내 생각에도 그럴 것 같아. 위에 짧은 시가 적혀 있는데, 내용이 좀 이상해.",
  ui_story_5035_50350601_38_dialog_content = "앗, 가, 가까이 보여 줘. 찍어 둘 거야.",
  ui_story_5035_50350601_39_dialog_content = "그래? 자, 그럼 받아, 이러면 카메라 쪽을 향해 읽어 줄 수도 있잖아.",
  ui_story_5035_50350601_40_dialog_content = "그, 그럼 읽을게. 무서워지면 언제든 멈춰 달라고 해줘!",
  ui_story_5035_50350601_41_dialog_content = "「한 꼬마, 두 꼬마...」",
  ui_story_5035_50350601_42_dialog_content = "<color=#e8d9bb>끼릭끼릭──</color>",
  ui_story_5035_50350601_43_dialog_content = "「한 꼬마, 두 꼬마, 세 꼬마 인형♪」",
  ui_story_5035_50350601_44_dialog_content = "「네 꼬마, 다섯 꼬마, 여섯 꼬마 인형♪」",
  ui_story_5035_50350601_45_dialog_content = "「일곱 꼬마, 여덟 꼬마, 아홉 꼬마 인형♪」",
  ui_story_5035_50350601_46_dialog_content = "「아홉 꼬마 인형... 머리는 여덟♪」",
  ui_story_5035_50350601_47_dialog_content = "<color=#e8d9bb>또옥... 똑...</color>",
  ui_story_5035_50350601_48_dialog_content = "이, 이 소린...",
  ui_story_5035_50350601_49_dialog_content = "너무 싸구려 티가 나잖아!",
  ui_story_5035_50350601_50_dialog_content = "하하, 아무래도 아가씨의 세팅이 간파당한 모양이군요.",
  ui_story_5035_50350601_51_dialog_content = "이 카드가 바로 녹음된 노래를 재생하는 스위치입니다.",
  ui_story_5035_50350601_52_dialog_content = "으... 진짜 놀랐다구.",
  ui_story_5035_50350601_53_dialog_content = "리리카 너도 이런 거 무서워하는구나?",
  ui_story_5035_50350601_54_dialog_content = "무, 무섭다기보단 감정이 격해진 거야.",
  ui_story_5035_50350601_55_dialog_content = "그럼 의적 정신에 따라 네가 무서워할 때면 내가 널 조금은 지켜 줄게.",
  ui_story_5035_50350601_56_dialog_content = "물론, 보수는 받을 거야.",
  ui_story_5035_50350601_57_dialog_content = "이건 다 사람이 만든 싸구려 효과들이라는 거 이제 너도 다 봤잖아.",
  ui_story_5035_50350601_58_dialog_content = "음질도 나쁘고, 배경음인 물방울 떨어지는 소리는 리듬이 엉망이고, 심지어는 라임도 구려.",
  ui_story_5035_50350601_59_dialog_content = "그리고 밑도 끝도 없이 계속 재생되고.",
  ui_story_5035_50350601_60_dialog_content = "조언 감사합니다. 이 부분에 대해서는 아가씨와 제가 앞으로 계속 보완해 나가겠...",
  ui_story_5035_50350601_61_dialog_content = "<color=#e8d9bb>끼릭──</color>",
  ui_story_5035_50350601_62_dialog_content = "이상하군요. 테이프 재생이 멈추다니...",
  ui_story_5035_50350601_63_dialog_content = "서, 설마 테이프에 씐 유령이 우리가 한 평가를 들은 건 아니겠지?!",
  ui_story_5035_50350601_64_dialog_content = "제가 제어실에 가서 확인해 보겠습니다.\n여러분께서는 잠시 이 방에서 기다려 주십시오.",
  ui_story_5035_50350601_65_dialog_content = "(리리카의 반응이 처음 만났을 때랑은 확실히 다르네...)",
  ui_story_5035_50350601_66_dialog_content = "무서워할 거 없어, 리리카. 우연히 재생이 멈춘 거겠지.",
  ui_story_5035_50350601_67_dialog_content = "우리가 그 노래를 정지하고 재생할 수도 없잖아.",
  ui_story_5035_50350601_68_dialog_content = "그, 그렇네. 여기서 우리가 「시작」이라고 외쳐 봐야 아무 일도...",
  ui_story_5035_50350601_69_dialog_content = "<color=#e8d9bb>끼릭끼릭──</color>",
  ui_story_5035_50350601_70_dialog_content = "「한 꼬마, 두 꼬마, 세 꼬마 인형♪」",
  ui_story_5035_50350601_71_dialog_content = "「네 꼬마, 다섯 꼬마...」",
  ui_story_5035_50350601_72_dialog_content = "꺄...야아아아아악! 또 시작이야!",
  ui_story_5035_50350601_73_dialog_content = "...당황하지 마! 가사를 들어 봐. 우리가 의견을 냈다고 해서 바뀐 건 없어.",
  ui_story_5035_50350601_74_dialog_content = "내, 내 생각엔 미노스 쪽에서 녹음 재생 기능을 고친 거 아닐까?",
  ui_story_5035_50350601_75_dialog_content = "분명 그럴 거야...",
  ui_story_5035_50350601_76_dialog_content = "<color=#e8d9bb>또옥... 똑...</color>",
  ui_story_5035_50350601_77_dialog_content = "<color=#e8d9bb>또옥, 똑... 똑똑똑, 또옥...</color>",
  ui_story_5035_50350601_78_dialog_content = "물방울이 떨어지는 리듬이 바뀌었어.",
  ui_story_5035_50350601_79_dialog_content = "이 부분도 미노스 씨가 그 짧은 시간에 마음대로 조절할 수 있...을까?",
  ui_story_5035_50350601_80_dialog_content = "으... 안 돼! 이런 일로 도망칠 순 없어!",
  ui_story_5035_50350601_81_dialog_content = "(리리카... 그래도 중요한 순간엔 책임감이 있는 모양이네...)",
  ui_story_5035_50350601_82_dialog_content = "천천히, 천천히 이 방에서 나가야 해. 카메라가 흔들리지 않게...",
  ui_story_5035_50350601_83_dialog_content = "......",
  ui_story_5035_50350601_84_dialog_content = "휴우~",
  ui_story_5035_50350601_85_dialog_content = "등골이 오싹하긴 했지만, 별일 없어서 다행이야.",
  ui_story_5035_50350601_86_dialog_content = "아, 침착해지고 나니까 고민되기 시작했어!",
  ui_story_5035_50350601_87_dialog_content = "방금 전 그 노래를 OST로 삽입하는 건 어떨까?",
  ui_story_5035_50350601_88_dialog_content = "그리고 아까 전시실에서 기념사진 찍는 거 잊어버렸네!",
  ui_story_5035_50350601_89_dialog_content = "넌 금방 안정되는 타입이구나.",
  ui_story_5035_50350601_90_dialog_content = "헤헷~",
  ui_story_5035_50350601_91_dialog_content = "으앗?!",
  ui_story_5035_50350601_92_dialog_content = "아파! 누가 내 어깨 꼬집었어?!",
  ui_story_5035_50350601_93_dialog_content = "미안해, 바바 야가가 그런 거야.",
  ui_story_5035_50350601_94_dialog_content = "바바 야가 대신 내가 사과할게. PlayerName, 많이 아파?",
  ui_story_5035_50350601_95_dialog_content = "아니, 안 아파. 아픈 것보단 깜짝 놀라서 그랬어.",
  ui_story_5035_50350601_96_dialog_content = "근데 왜 미아 너까지 여기 있는 거야?",
  ui_story_5035_50350601_97_dialog_content = "바바 야가랑 같이 왔어. 여기가 많이 신경 쓰인대.",
  ui_story_5035_50350601_98_dialog_content = "어떻게 해도 반값 티켓은 얻을 수 없었지만...",
  ui_story_5035_50350601_99_dialog_content = "내가 미아한테 검표원하고 말싸움은 내가 할 테니까, 얼른 몸을 바꾸자고 했어!",
  ui_story_5035_50350601_100_dialog_content = "미아는 항상 부끄럼쟁이잖아, 안 그래? PlayerName~",
  ui_story_5035_50350601_101_dialog_content = "우리가 여기서 널 만난 것도 인연 아니겠어~?",
  ui_story_5035_50350601_102_dialog_content = "이 발톱에 찔렸을 때 네 표정... 꽤 귀엽던데.",
  ui_story_5035_50350601_103_dialog_content = "바바 야가, 미아... 뒤쪽에...!",
  ui_story_5035_50350601_104_dialog_content = "아이, 참~ 왜 또 그런 표정을 짓는 거야?",
  ui_story_5035_50350601_105_dialog_content = "내 얼굴이... 그렇게 무서워?",
  ui_story_5035_50350601_106_dialog_content = "크오오!",
  ui_story_5035_50350601_107_dialog_content = "꺄아아아아아악!",
  ui_story_5035_50350601_108_dialog_content = "암귀라면 그렇게 무서워할 거 없잖아!",
  ui_story_5035_50350601_109_dialog_content = "의적 수칙 제2조!\n남에게 곤란한 일이 있으면 도망치지 않는다! 나서야 할 땐 나선다!",
  ui_story_5035_50350601_110_dialog_content = "내 「쿠쿠」를 멋지게 휘둘러 줘야겠어!",
  ui_story_5035_50350702_1_dialog_content = "휴... 암귀 몇 마리 가지고 왜 비명을 지르는 건지 진짜 모르겠네, 알 수가 없다니까.",
  ui_story_5035_50350702_2_dialog_content = "너무 멋있었어! 고문 도구 아가씨! 각도를 좀 바꿔서 몇 번 찍어도 될까?",
  ui_story_5035_50350702_3_dialog_content = "후후후후훗, 그래~",
  ui_story_5035_50350702_4_dialog_content = "하지만 찍어도 공개는 하면 안 돼. 미아는 사람들한테 모습을 드러내는 걸 별로 안 좋아하거든~",
  ui_story_5035_50350702_5_dialog_content = "안 그러면... 네 카메라랑 네 곁에 있는 그 자그마한 녀석을 밟아서... 부서트릴... 거야.",
  ui_story_5035_50350702_6_dialog_content = "으... 아, 알겠어!",
  ui_story_5035_50350702_7_dialog_content = "그런 말은 하지 마...",
  ui_story_5035_50350702_8_dialog_content = "미안해. 우린 널 위협하려던 건 아니야...",
  ui_story_5035_50350702_9_dialog_content = "괜찮아, 진짜로 괜찮아. 난 출연자의 의견을 아주 중요하게 생각하거든!",
  ui_story_5035_50350702_10_dialog_content = "여러분, 모두 괜찮으십니까?",
  ui_story_5035_50350702_11_dialog_content = "1층에서부터 소란스러운 소리가 들렸는데, 다행히 그저 암귀 몇 마리였군요.",
  ui_story_5035_50350702_12_dialog_content = "전시실의 녹음 재생 관련 문제는 이미 해결됐습니다. 더 안쪽으로 들어가 보시려면...",
  ui_story_5035_50350702_13_dialog_content = "아니에요! 그, 그럴 필요 없어요. 아하하...",
  ui_story_5035_50350702_14_dialog_content = "계속해서 다음 장소로 이동해요!",
  ui_story_5035_50350702_15_dialog_content = "그럼 난 여기서 인사할게.",
  ui_story_5035_50350702_16_dialog_content = "이왕 이렇게 만났는데, 뭐 하나만 물어봐도 될까~?",
  ui_story_5035_50350702_17_dialog_content = "너, 음... 아니, 너희들! 우리 미스터리 탐험대에 들어오지 않을래?",
  ui_story_5035_50350702_18_dialog_content = "사양할게. 왜냐면... 난 모두랑 같이 돌아다니는 것보단 혼자서 여길 경험해 보고 싶거든.",
  ui_story_5035_50350702_19_dialog_content = "그럼 둘 다 조심해서 다녀.",
  ui_story_5035_50350702_20_dialog_content = "잠깐, 너희한테 해 줄 말이 있어.",
  ui_story_5035_50350702_21_dialog_content = "PlayerName... 아직 <color=#FFB400>그녀</color>가 네 곁에 없는 것 같아.",
  ui_story_5035_50350702_22_dialog_content = "아마 내가 너희보다 먼저 <color=#FFB400>그녀</color>를 알아챈 모양이네.",
  ui_story_5035_50350702_23_dialog_content = "...「그녀」?",
  ui_story_5035_50350702_24_dialog_content = "응. 하지만 난 <color=#FFB400>그녀</color>와 만나기가 힘들거든~",
  ui_story_5035_50350702_25_dialog_content = "여기서 너희랑 같이 <color=#FFB400>그녀</color>를 못 만나서 조금 실망했어...",
  ui_story_5035_50350702_26_dialog_content = "네, 네가 말하는 그 사람이 대체 누군데...?",
  ui_story_5035_50350702_27_dialog_content = "후훗, 농담이야~ 나랑 미아 둘이서도 <color=#FFB400>그녀</color>를 찾을 수 있거든.",
  ui_story_5035_50350702_28_dialog_content = "그래도... PlayerName 너한테 당부해 둘 게 있어...",
  ui_story_5035_50350702_29_dialog_content = "<color=#FFB400>그녀한테 사로잡히지 않도록 조심해...</color>",
  ui_story_5035_50350702_30_dialog_content = "왜냐하면, 오직 나만이 <color=#FFB400>그녀를 사랑의 「만찬」으로 끌어들일 수 있으니까</color>.",
  ui_story_5035_50350702_31_dialog_content = "그건 또... 무슨 소리야?",
  ui_story_5035_50350702_32_dialog_content = "후후후훗~ 그 얼떨떨한 표정도 정말 귀엽네.",
  ui_story_5035_50350702_33_dialog_content = "그럼, 다음에 또 만나~",
  ui_story_5035_50350702_34_dialog_content = "으... 정말이지...",
  ui_story_5035_50350702_35_dialog_content = "왜 여기 주인은 나한테 안데르센 비명의 집에 대한 무서운 이야기를\n써 달라고 하지 않는 걸까...",
  ui_story_5035_50350702_36_dialog_content = "가버렸어...",
  ui_story_5035_50350702_37_dialog_content = "(아까 바바 야가가 말한 사람은 대체 누굴 얘기하는 거지? 설마...)",
  ui_story_5035_50350702_38_dialog_content = "(근데 자세히는 설명해 주고 싶지 않은 것 같았어...)",
  ui_story_5035_50350702_39_dialog_content = "(어쩔 수 없지. 곧 직접 알게 됐으면 좋겠는데.)",
  ui_story_5035_50350702_40_dialog_content = "텔레비전 앞에 있을 미래의 여러분, 여길 보세요.\n이 사람이 바로 전설 속의 아이테르랍니다.",
  ui_story_5035_50350702_41_dialog_content = "저 사람은 저택 깊은 곳을 배회하는 처형자 소녀예요.",
  ui_story_5035_50350702_42_dialog_content = "과연 이 알쏭달쏭 뭔지 모를 대화가 앞으로 어떤 결과를 가져오게 될까요...?",
  ui_story_5035_50350702_43_dialog_content = "리리카, 그런 말은 함부로 하는 거 아냐!",
  ui_story_5035_50350702_44_dialog_content = "장난이야, 장난! 아까 그거 녹화 안 했어~!",
  ui_story_5035_50350702_45_dialog_content = "Hold on, hold on... 소란은 여기서 Shut down, 다음 장소를 향해 Move down♪",
  ui_story_5035_50350702_46_dialog_content = "컴컴한 지하실을 향한 우리의 방문은 like Dawn♪",
  ui_story_5035_50350702_47_dialog_content = "새디 양은 나이는 어려 보이지만 침착하고 프로답군요.",
  ui_story_5035_50350702_48_dialog_content = "?!",
  ui_story_5035_50350702_49_dialog_content = "별거 아니야. 머, 멋진 의적은 보통 다 이러니까!",
  ui_story_5035_50350702_50_dialog_content = "그럼 우리 계속 지하실로 가 보자...!",
  ui_story_5035_50350702_51_dialog_content = "제가 계속 여러분을 안내해 드리겠습니다.",
  ui_story_5035_50350702_52_dialog_content = "그래, 그럼 《비명의 집 탐험》 촬영을 재개하자!",
  ui_story_5035_50350801_1_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_5035_50350801_2_dialog_content = "유령 저택은 인기가 없지, 찾아볼까 마지막 촬영지♪",
  ui_story_5035_50350801_3_dialog_content = "현장 체크리스트에는 지하실이라고 적혀 있어.\n집사 씨, 그럼 거기까지 안내를 부탁할게.",
  ui_story_5035_50350801_4_dialog_content = "그러고 보면 제가 조니 감독님과 파트너십을 체결할 때,\n이 저택의 사용 가능 범위에 대해 모두 정해 뒀었습니다.",
  ui_story_5035_50350801_5_dialog_content = "지하실은 유령 저택의 영업장소에 포함되지 않으니,\n내일 다시 비용 부분에 대해 논의해 봐야겠군요.",
  ui_story_5035_50350801_6_dialog_content = "그래. 아무튼 갑자기 금전적인 얘길 꺼내서 우리의 《비명의 집 탐험》에\n영향을 주진 마. 일단 출발하자.",
  ui_story_5035_50350801_7_dialog_content = "저기, 리리카. 뭐 하는 거야? 얼른 따라 와.",
  ui_story_5035_50350801_8_dialog_content = "배터리는 아직 충분한 것 같고, 렌즈 캡도 벗겨 놨어. 초점은 미리 좀 맞춰 둬야겠네.",
  ui_story_5035_50350801_9_dialog_content = "다 됐어! PlayerName, 이쪽으로 좀 와 줘!",
  ui_story_5035_50350801_10_dialog_content = "어? 나?",
  ui_story_5035_50350801_11_dialog_content = "응, 넌 센스가 좀 있는 것 같거든.",
  ui_story_5035_50350801_12_dialog_content = "그러니까 내 촬영 기사를 맡아주지 않을래? 엄청 재미있을 거야.",
  ui_story_5035_50350801_13_dialog_content = "촬영 기사? 지금까지 너 혼자 찍고 있었잖아. 갑자기 왜 촬영 기사가 필요해?",
  ui_story_5035_50350801_14_dialog_content = "나 혼자 나오는 장면을 찍고 싶어서 그래. 이렇게 부탁할게, 도와줘!",
  ui_story_5035_50350801_15_dialog_content = "으, 해 줄 수 있긴 한데, 어떻게 찍어야...",
  ui_story_5035_50350801_16_dialog_content = "자, 이거 줄게. 어깨에 메 줘.",
  ui_story_5035_50350801_17_dialog_content = "으앗!",
  ui_story_5035_50350801_18_dialog_content = "엄청 비싼 거니까 제대로 메고 있어야 해.",
  ui_story_5035_50350801_19_dialog_content = "떨어트려서 고장이라도 나면, 너한테 보상금으로 어마어마한 나이티움을 청구할지도 몰라.",
  ui_story_5035_50350801_20_dialog_content = "위험성이 높아도 너무 높잖아! 나 안 해!",
  ui_story_5035_50350801_21_dialog_content = "아하하, 장난이야~ 장난~ 자, 카메라를 내 쪽으로 향해 줘.",
  ui_story_5035_50350801_22_dialog_content = "응, 바로 그렇게.",
  ui_story_5035_50350801_23_dialog_content = "리리카, 왜 또 캠코더를 만지작거리고 있어?",
  ui_story_5035_50350801_24_dialog_content = "아, 그게 말이지...",
  ui_story_5035_50350801_25_dialog_content = "혹시 뜻밖의 일이 생기면 캠코더가 뭘 좀 기록해 줄 수도 있잖아.",
  ui_story_5035_50350801_26_dialog_content = "그게 무슨 말이야? 이따가 뜻밖의 상황이 발생한다는 소리야?",
  ui_story_5035_50350801_27_dialog_content = "아이, 그런 게 아니라. 내 말은...",
  ui_story_5035_50350801_28_dialog_content = "음, 아까 미노스 씨가 지하실은 유령 저택의 영업장소에 포함되지 않는다고 했었지?",
  ui_story_5035_50350801_29_dialog_content = "네, 그렇게 말씀드렸습니다.",
  ui_story_5035_50350801_30_dialog_content = "그럼 내가 지하실에서 촬영을 진행해도 규칙 위반은 아닌 거네!",
  ui_story_5035_50350801_31_dialog_content = "네, 촬영을 진행하셔도 됩니다.",
  ui_story_5035_50350801_32_dialog_content = "좋았어~ 캠코더까지 가져왔으니까 되도록 많은 장면을 찍어 둬야지.",
  ui_story_5035_50350801_33_dialog_content = "자, 그럼 출발하자.",
  ui_story_5035_50350801_34_dialog_content = "그래. 근데 미리 말해 두지만, 내가 등장하는 장면을 쓰려면 초상권 비용은 두둑이 든든히♪",
  ui_story_5035_50350801_35_dialog_content = "아까 누가 「금전적인 얘길 꺼내서 우리의 《비명의 집 탐험》에\n영향을 주진 마」라고 했더라?",
  ui_story_5035_50350801_36_dialog_content = "지하실은 이쪽입니다. 길이 지나다니기 조금 불편하니 조심해 주십시오.",
  ui_story_5035_50350801_37_dialog_content = "PlayerName, 너 캠코더 쓸 줄 알아?",
  ui_story_5035_50350801_38_dialog_content = "그냥 들고 찍는 건 할 줄 알아.",
  ui_story_5035_50350801_39_dialog_content = "근데... 렌즈에 이렇게 가까이 붙어 있으면, 얼굴이 엄청 크게 나올걸.",
  ui_story_5035_50350801_40_dialog_content = "어? 빠, 빨리 치워 줘!",
  ui_story_5035_50350801_41_dialog_content = "얼른 쫓아가자. 카메라로 나 계속 찍어야 하는 거 잊지 마~",
  ui_story_5035_50350801_42_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5035_50350801_43_dialog_content = "참, 미노스 씨. 왜 지하실은 영업장소에 포함되지 않는 거야?",
  ui_story_5035_50350801_44_dialog_content = "유령 저택의 지하실이라면 굉장히 매력적이잖아. 티켓도 훨씬 더 많이 팔릴 것 같은데.",
  ui_story_5035_50350801_45_dialog_content = "그 부분이라면 아가씨께서 이 저택을 구매하셨을 때의 이야기부터 말씀드려야겠군요.",
  ui_story_5035_50350801_46_dialog_content = "이전 소유주는 아주 급했던 모양인지, 이 저택을 매우 싼값에 내놓았습니다.",
  ui_story_5035_50350801_47_dialog_content = "얼마나 급했으면 저택 면적을 계산할 때, 그 지하실은 포함시키지도 않았더군요.",
  ui_story_5035_50350801_48_dialog_content = "다시 말해서, 그 지하실은 덤이었다는 겁니다.",
  ui_story_5035_50350801_49_dialog_content = "어라? 그렇게 마음씨 고운 집주인도 있어?",
  ui_story_5035_50350801_50_dialog_content = "저는 아가씨를 대신해 이 저택을 인계받던 중에 이 지하실을 발견하게 됐습니다.\n발견 후 전 즉시 이전 소유주에게 어떻게 된 일인지 물었지요.",
  ui_story_5035_50350801_51_dialog_content = "이전 소유주는 지하실이 오래전부터 방치된 상태라,\n안이 매우 지저분하고 악취가 난다고 했습니다.",
  ui_story_5035_50350801_52_dialog_content = "그런 상태이니 돈을 받고 팔 수가 없어서 면적을 계산할 때 빼놓았던 것이었습니다.",
  ui_story_5035_50350801_53_dialog_content = "게다가 그 난장판을 치우려면 배보다 배꼽이 더 클 테니,\n지하실에는 들어가지 않는 편이 좋을 거라고 하더군요.",
  ui_story_5035_50350801_54_dialog_content = "그냥 없는 셈 치고 흙과 돌로 입구를 막아 버리라고도 했었지요.",
  ui_story_5035_50350801_55_dialog_content = "그래서 이전 소유주의 제안을 받아들인 거야?",
  ui_story_5035_50350801_56_dialog_content = "일부는 수용했습니다. 저택에 인테리어를 할 시간이 매우 촉박해서\n지하실을 정리할 시간이 없었기 때문입니다.",
  ui_story_5035_50350801_57_dialog_content = "다만, 지하실을 철저하게 묻어 버리지도 않았습니다.",
  ui_story_5035_50350801_58_dialog_content = "오히려 저는 지하실 입구를 비밀 문으로 개조했습니다.\n나중에 유령 저택이 비수기가 되면 새로 단장할 시간을 낼 수 있을 테니까요.",
  ui_story_5035_50350801_59_dialog_content = "미노스 씨는 친절하면서 똑똑하기까지 하구나...",
  ui_story_5035_50350801_60_dialog_content = "도착했군요. 바로 여깁니다.",
  ui_story_5035_50350801_61_dialog_content = "<color=#e8d9bb>휙──!</color>",
  ui_story_5035_50350801_62_dialog_content = "우와! 카펫 아래에 숨겨져 있었네!",
  ui_story_5035_50350801_63_dialog_content = "이 안은 조금 어두우니 저를 바짝 따라오십시오.",
  ui_story_5035_50350801_64_dialog_content = "PlayerName, 카메라 안 부딪히게 조심해야 해~",
  ui_story_5035_50350801_65_dialog_content = "그래그래.",
  ui_story_5035_50350801_66_dialog_content = "이, 이게 조금 어두운 거야? 아무것도 안 보이는데?!",
  ui_story_5035_50350801_67_dialog_content = "주변에 깔린 건 어두운 칠흑,\n공기 중에... 콜록... 떠도는 건 무거운 먼지흙♪",
  ui_story_5035_50350801_68_dialog_content = "미노스 씨, 어디 있어? 미노스 씨가 어디 있는지 못 찾겠어...",
  ui_story_5035_50350801_69_dialog_content = "불을 켜러 가고 있었습니다.",
  ui_story_5035_50350801_70_dialog_content = "으앗, 눈부셔.",
  ui_story_5035_50350801_71_dialog_content = "지하실은 저택 인테리어를 할 때 딱 한 번 와 본 게 전부입니다.\n자세히 살펴본 적도 없었지요.",
  ui_story_5035_50350801_72_dialog_content = "이곳에서 뭐가 나타날지는 저도 잘 모르니, 각별히 주의하셔야 합니다.",
  ui_story_5035_50350801_73_dialog_content = "상태가 생각했던 거만큼 끔찍하진 않은 것 같아.",
  ui_story_5035_50350801_74_dialog_content = "물건들이 어지럽게 놓여 있는 건 맞는데, 더럽다고 할 정도까진 아니고,\n이전 소유주가 말했던 거처럼 악취가 나지도 않아.",
  ui_story_5035_50350801_75_dialog_content = "오히려 누가 청소했던 흔적이 남아 있는걸.",
  ui_story_5035_50350801_76_dialog_content = "저기 밀랍 인형이 있어.",
  ui_story_5035_50350801_77_dialog_content = "너무 엉성해서 봐도 별로 재미있지가 않네.",
  ui_story_5035_50350801_78_dialog_content = "먼지에 남아 있는 무늬 있잖아. 발자국 같이 생기지 않았어?",
  ui_story_5035_50350801_79_dialog_content = "어! 진짜네!",
  ui_story_5035_50350801_80_dialog_content = "옆에 있는 벽에는 손자국도 찍혀 있어. 내 손보다 훨씬 작아.",
  ui_story_5035_50350801_81_dialog_content = "아이가 남긴 흔적일까?",
  ui_story_5035_50350801_82_dialog_content = "기둥에 칼로 새긴 흔적이 있어. 이건 우리 집에도 있어, 그래서 뭔지 알아.",
  ui_story_5035_50350801_83_dialog_content = "알겠어! 이를 간 흔적 맞지?",
  ui_story_5035_50350801_84_dialog_content = "...이를 왜 갈아? 멍멍이야?",
  ui_story_5035_50350801_85_dialog_content = "키를 잴 때 새긴 거야. 키가 조금 자랄 때마다 새로 하나 새긴 거지.",
  ui_story_5035_50350801_86_dialog_content = "아, 그랬구나.",
  ui_story_5035_50350801_87_dialog_content = "누군진 모르겠지만 이렇게 작다니. 맨 위에 있는 흔적도 새디 키보다 작네.",
  ui_story_5035_50350801_88_dialog_content = "너...",
  ui_story_5035_50350801_89_dialog_content = "바로 그렇습니다. 이 손자국과 발자국들은 모두 어린아이가 남긴 겁니다.",
  ui_story_5035_50350801_90_dialog_content = "모양이 제각각인 걸 보면 아이가 한 명이 아니라 여러 명이었던 것 같군요.",
  ui_story_5035_50350801_91_dialog_content = "어째서 이런 곳에서 생활했던 걸까요...",
  ui_story_5035_50350801_92_dialog_content = "다들, 이쪽으로 좀 와 봐.",
  ui_story_5035_50350801_93_dialog_content = "바닥에 버려진 종이들에 뭔가 적혀 있어.",
  ui_story_5035_50350801_94_dialog_content = "어? 뭐라고 적혀 있는데?",
  ui_story_5035_50350801_95_dialog_content = "글자가 삐뚤빼뚤하긴 한데, 읽어 볼게. 크흠.",
  ui_story_5035_50350801_96_dialog_content = "「이것 하나만 기억하면 된단다.」",
  ui_story_5035_50350801_97_dialog_content = "「말을 듣지 않는 아이는 여주인님에게 <color=#FFB400>벌</color>을 받게 된다는 것.」",
  ui_story_5035_50350801_98_dialog_content = "「지하실 문이 열리면 그가 그 안으로 끌려 들어오겠지.」",
  ui_story_5035_50350801_99_dialog_content = "「아, 그뿐만 아니라 그와 가장 가까운 동료까지도.」",
  ui_story_5035_50350801_100_dialog_content = "「말을 듣지 않으면 어떤 결과에 이르게 되는지 기억되야 한단다.」",
  ui_story_5035_50350801_101_dialog_content = "「동료는 걱정할 필요 없어. 네게는 아무 일도 일어나지 않을 거야.」",
  ui_story_5035_50350801_102_dialog_content = "「너는 착하게 내 말대로 방 가장자리에서 구석을 보고 서 있기만 하면 돼.」",
  ui_story_5035_50350801_103_dialog_content = "「잘 듣되 그 어떤 소리를 듣더라도 절대로 뒤를 돌아봐서는 안 된단다.」",
  ui_story_5035_50350801_104_dialog_content = "「여주인님께서는 자기가 <color=#FFB400>벌</color>을 주는 모습을 남이 보길 원치 않으시거든.」",
  ui_story_5035_50350801_105_dialog_content = "...음, 이게 끝이야. 내용이 너무 이상해.",
  ui_story_5035_50350801_106_dialog_content = "일종의 경고 같은데? 종이에 쓰여 있는 내용이 진짜인지 아닌진 모르겠지만.",
  ui_story_5035_50350801_107_dialog_content = "「여주인」은... 미노스가 말해 줬던 그 「에스더 부인」이야?",
  ui_story_5035_50350801_108_dialog_content = "저도 확신은 못 하겠습니다.\n「에스더 부인」의 행적은 전해져 내려오는 이야기에 불과하니까요.",
  ui_story_5035_50350801_109_dialog_content = "설마 에스더 부인이 과거에 이 지하실에서 아이들한테 벌을 준 걸까?",
  ui_story_5035_50350801_110_dialog_content = "한 아이한테는 벌을 주고, 다른 아이한테는 벽을 보고 서서 벌받는 소리를 들게 하다니...",
  ui_story_5035_50350801_111_dialog_content = "그거 완전히 변태잖아. 실제로 그런 일은... 일어난 적 없었으면 좋겠어.",
  ui_story_5035_50350801_112_dialog_content = "글씨체를 보면 이 쪽지들은 전부 아이가 적은 것 같아.",
  ui_story_5035_50350801_113_dialog_content = "아이들이 지어낸 이야기일 수도 있지 않을까?",
  ui_story_5035_50350801_114_dialog_content = "그건 아닐 거야. 다른 쪽지들을 봐.",
  ui_story_5035_50350801_115_dialog_content = "다 글자가 적혀 있어. 게다가 내용들도 똑같고.",
  ui_story_5035_50350801_116_dialog_content = "「이것 하나만 기억하면 된단다.」",
  ui_story_5035_50350801_117_dialog_content = "「말을 듣지 않는 아이는 여주인님에게 <color=#FFB400>벌</color>을 받게 된다는 것...」",
  ui_story_5035_50350801_118_dialog_content = "지어낸 이야기를 이렇게 많이 베껴 쓰지는 않잖아?",
  ui_story_5035_50350801_119_dialog_content = "그, 그건 그렇네.",
  ui_story_5035_50350801_120_dialog_content = "많이라고 할 필요도 없어. 한 번만 적어도 힘들어서 싫다고 할 거야.\n마지막으로 뭔가를 적었던 적이 언제더라? 10살 때인가?",
  ui_story_5035_50350801_121_dialog_content = "반복해서 뭔가를 베껴 쓰는 건 진짜 따분한 일이야.\n이런 걸 좋아하는 사람은 아무도 없을걸.",
  ui_story_5035_50350801_122_dialog_content = "아니면...",
  ui_story_5035_50350801_123_dialog_content = "누가 강제로 베껴 쓰라고 시킨 거겠지.\n알겠어. 이건 벌이었던 거야.",
  ui_story_5035_50350801_124_dialog_content = "아이한테 벌로 이런 내용을 베껴 쓰라고 한다고? 그거 완전...",
  ui_story_5035_50350801_125_dialog_content = "집사 씨, 이 저택의 이전 소유주에 대해 얼마나 알고 있어?",
  ui_story_5035_50350801_126_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5035_50350801_127_dialog_content = "집사 씨?",
  ui_story_5035_50350801_128_dialog_content = "다른 물건을 발견했습니다. 다들 이것 좀 보시지요.",
  ui_story_5035_50350801_129_dialog_content = "어? 노트네요! 거기에도 쪽지랑 같은 내용이 적혀 있어요?",
  ui_story_5035_50350801_130_dialog_content = "다릅니다. 이 노트는 낡지 않았으니, 분명히 최근에 남겨진 겁니다.",
  ui_story_5035_50350801_131_dialog_content = "커버에는 「영화 제작팀 업무 일지」라고 적혀 있습니다.\n이걸 작성한 사람은 프로듀서군요.",
  ui_story_5035_50350801_132_dialog_content = "프로듀서? 그거 미노스 씨 본인 아니에요?",
  ui_story_5035_50350801_133_dialog_content = "제가 적었을 리 없잖습니까. 아마 예전에 다른 제작 스태프가 왔다 갔던 모양입니다.",
  ui_story_5035_50350801_134_dialog_content = "그것도 그렇네요. 그럼 노트에 뭐라고 적혀 있는데요?",
  ui_story_5035_50350801_135_dialog_content = "「촬영지: 침실.」",
  ui_story_5035_50350801_136_dialog_content = "「정말 엉망인 곳이다. 창문이랑 벽에서도 바람이 새어 들어오는 것 같다. 추워서 온몸이 떨린다.」",
  ui_story_5035_50350801_137_dialog_content = "「감독을 기다리는 동안 텔레비전을 보고 싶었지만,\n무슨 텔레비전이 신호 수신도 제대로 못 한다. 쓸모가 없다.」",
  ui_story_5035_50350801_138_dialog_content = "「최악인 것은, 감독을 기다리고 있었는데 감독이 아니라 암귀가 들이닥쳤다.」",
  ui_story_5035_50350801_139_dialog_content = "「소품들은 절반이 망가졌고 동료 셋이 다쳤다.\n이제 더는 여기서 촬영을 못 하겠다고 감독한테 말했다.」",
  ui_story_5035_50350801_140_dialog_content = "내용을 보니 이 사람들도 침실에 갔던 것 같군요.",
  ui_story_5035_50350801_141_dialog_content = "이 저택은 원래부터 암귀들이 자주 습격해 왔었나 봐요...\n싼값에 판 이유가 있었네요.",
  ui_story_5035_50350801_142_dialog_content = "다음 내용에서도 익숙한 곳이 등장합니다.",
  ui_story_5035_50350801_143_dialog_content = "「촬영지: 전시실.」",
  ui_story_5035_50350801_144_dialog_content = "「여기서 일하고 싶지 않다. 만약 감독이 계속 이 저택에서 촬영하겠다고\n고집을 부린다면 다 때려치우고 집에 갈 거다.」",
  ui_story_5035_50350801_145_dialog_content = "「소름 끼치는 노랫소리는 도대체 언제나 멈출까.\n거기다 망할 물방울 소리까지. 아주 협주곡 나셨다.」",
  ui_story_5035_50350801_146_dialog_content = "「집주인의 독특한 취향 때문일까? 그런 거라면 그 인간 머리를 제대로 걷어차 줄 거다.」",
  ui_story_5035_50350801_147_dialog_content = "「나는 공포 영화를 찍으러 온 거지, 공포 현장에 오려던 게 아니다.」",
  ui_story_5035_50350801_148_dialog_content = "이 사람도 노랫소리랑 물방울 소리를 전부 다 들었어요!\n우리가 전시실에서 겪었던 상황이랑 똑같아요!",
  ui_story_5035_50350801_149_dialog_content = "미노스 씨, 진짜 미노스 씨가 적은 거 아니에요?",
  ui_story_5035_50350801_150_dialog_content = "제가 적었다면 그게 더 무섭지 않겠습니까?",
  ui_story_5035_50350801_151_dialog_content = "화, 확실히 그렇네요...",
  ui_story_5035_50350801_152_dialog_content = "그리고? 이 노트의 주인도 지하실에 왔었어?",
  ui_story_5035_50350801_153_dialog_content = "아, 미안. 내가 괜한 걸 물어봤네. 그 노트가 발견된 장소가 바로 이 지하실인데 말이야.",
  ui_story_5035_50350801_154_dialog_content = "이다음이 바로 지하실에 관련된 내용입니다.",
  ui_story_5035_50350801_155_dialog_content = "「촬영지: 지하실.」",
  ui_story_5035_50350801_156_dialog_content = "......",
  ui_story_5035_50350801_157_dialog_content = "왜 갑자기 아무 말이 없어요?",
  ui_story_5035_50350801_158_dialog_content = "여러분께서 직접 읽으시는 편이 좋겠습니다.",
  ui_story_5035_50350801_159_dialog_content = "네? 대체 뭐라고 적혀 있길래...",
  ui_story_5035_50350801_160_dialog_content = "......",
  ui_story_5035_50350801_161_dialog_content = "「그녀가 왔다.」",
  ui_story_5035_50350801_162_dialog_content = "이 한 줄이 다야?",
  ui_story_5035_50350801_163_dialog_content = "누가 왔다는 거지?",
  ui_story_5035_50350801_164_dialog_content = "혹시 쪽지 속에 나왔던 그 「여주인」이라든가...",
  ui_story_5035_50350801_165_dialog_content = "더 이상의 정보는 없습니다. 지하실에 있는 물건들도 이게 전부입니다.",
  ui_story_5035_50350801_166_dialog_content = "과거에 무슨 일이 있었는지는 직접 추측해 보는 수밖에 없겠군요.",
  ui_story_5035_50350801_167_dialog_content = "여러분께서는 어떻게 생각하십니까?",
  ui_story_5035_50350801_168_dialog_content = "사실 난 여기서 좀 나가고 싶어졌어...",
  ui_story_5035_50350801_169_dialog_content = "나, 나도.",
  ui_story_5035_50350801_170_dialog_content = "잠깐~ 잠깐만! 다들 왜 이렇게 텐션이 다운된 거야?",
  ui_story_5035_50350801_171_dialog_content = "우리 《비명의 집 탐험》 완성이 코앞이라구. 완전 신나는 일이잖아!",
  ui_story_5035_50350801_172_dialog_content = "방금 저런 걸 봤는데... 넌 안 무서워?",
  ui_story_5035_50350801_173_dialog_content = "조금 섬뜩하긴 했는데, 이럴 때일수록 텐션을 끌어 올려야 하는 거라구!",
  ui_story_5035_50350801_174_dialog_content = "아니면 괴물인지 유령인지가 나오기도 전에 내가 나 때문에 놀라게 돼 버릴 테니까!",
  ui_story_5035_50350801_175_dialog_content = "그러니까 분위기 전환도 하고, 이번 미스터리 탐험을 기념하게 우리 같이 단체 사진 찍자!",
  ui_story_5035_50350801_176_dialog_content = "여기서? 사진은 여기 말고 나가서 찍는 게...",
  ui_story_5035_50350801_177_dialog_content = "당연히 여기서 찍어야지~ 안 그럼 기념사진이란 의미가 없잖아.",
  ui_story_5035_50350801_178_dialog_content = "나쁘지 않네. 신작 홍보에 사용하고 싶으니까, 찍고 나면 나도 한 장 줘.",
  ui_story_5035_50350801_179_dialog_content = "저도 한 장 주십시오. 이전 소유주와 교섭하려면 사진이 있는 편이 더 좋을 테니까요.",
  ui_story_5035_50350801_180_dialog_content = "봤지? 모두 동의했으니까 그럼 찍자, 찍자~",
  ui_story_5035_50350801_181_dialog_content = "그래. 그럼 내가 찍어 주면 되는 거야?",
  ui_story_5035_50350801_182_dialog_content = "안 돼. 단체 사진이니까 다 같이 나와야지.",
  ui_story_5035_50350801_183_dialog_content = "이렇게 하자. PlayerName 말고 다른 사람들은 일단 다 내 쪽으로 와 줘.",
  ui_story_5035_50350801_184_dialog_content = "조금 더 가깝게, 붙어서 서 보자.",
  ui_story_5035_50350801_185_dialog_content = "이렇게?",
  ui_story_5035_50350801_186_dialog_content = "응! 그리고 PlayerName 넌 캠코더를 저쪽에 있는 삼각대에 놓고,\n렌즈가 우리 쪽을 향하게 조절해 줘.",
  ui_story_5035_50350801_187_dialog_content = "그리고 셔터를 누른 다음에 재빨리 우리가 있는 쪽으로 뛰어오는 거야. 알겠지?",
  ui_story_5035_50350801_188_dialog_content = "아, 그렇구나. 대충 알 것 같아.",
  ui_story_5035_50350801_189_dialog_content = "어디 보자. 일단 여기에 두고, 렌즈를 모두가 있는 방향에 맞춘 다음에...",
  ui_story_5035_50350801_190_dialog_content = "셔터는 여기 이 버튼이야?",
  ui_story_5035_50350801_191_dialog_content = "응! 우리도 준비를 해야 하니까, 하나, 둘, 셋하고 숫자를 세고 나서 눌러야 해.",
  ui_story_5035_50350801_192_dialog_content = "그래, 알겠어. 자, 그럼 다들 이쪽 봐!",
  ui_story_5035_50350801_193_dialog_content = "그럼 센다! 하나, 둘, 셋...!",
  ui_story_5035_50350801_194_dialog_content = "<color=#e8d9bb>팟──!</color>",
  ui_story_5035_50350801_195_dialog_content = "꺄악!",
  ui_story_5035_50350801_196_dialog_content = "뭐, 뭐지? 정전이야?",
  ui_story_5035_50350801_197_dialog_content = "아야, 누가 내 발 밟았어.",
  ui_story_5035_50350801_198_dialog_content = "미안! 미안해! 어? 잠깐만, 나 아무것도 안 밟았는데?",
  ui_story_5035_50350801_199_dialog_content = "꺄아아!",
  ui_story_5035_50350801_200_dialog_content = "몸에 뭔가 떨어지지 않았어?",
  ui_story_5035_50350801_201_dialog_content = "뭔가... 차가운 액체 같은 거...",
  ui_story_5035_50350801_202_dialog_content = "음, 나도 느꼈어...",
  ui_story_5035_50350801_203_dialog_content = "새디도 느꼈어? 그럼 잘됐네!",
  ui_story_5035_50350801_204_dialog_content = "어딜 봐서 잘됐다는 거야?!",
  ui_story_5035_50350801_205_dialog_content = "이번에는 확실히 뭔가 나타난 거잖아!",
  ui_story_5035_50350801_206_dialog_content = "뭔가 나타난 게 어디가 좋은 일인데?!",
  ui_story_5035_50350801_207_dialog_content = "PlayerName! 캠코더에 나이트 비전 기능이 있으니까 어서 켜 봐!",
  ui_story_5035_50350801_208_dialog_content = "앗! 그런 기능도 있었구나! 뭘 누르면 돼?",
  ui_story_5035_50350801_209_dialog_content = "셔터 바로 아래를 만져 보면 네모난 버튼이 있을 거야. 그걸 누르면 돼!",
  ui_story_5035_50350801_210_dialog_content = "셔터 아래쪽...",
  ui_story_5035_50350801_211_dialog_content = "꺄앗!",
  ui_story_5035_50350801_212_dialog_content = "서둘러! 뭔가 보인 것 같아! 저기! 저쪽이야!",
  ui_story_5035_50350801_213_dialog_content = "찾았어! 찾았어!",
  ui_story_5035_50350801_214_dialog_content = "<color=#e8d9bb>팟──</color>",
  ui_story_5035_50350801_215_dialog_content = "앗! 이제 화면이 보여...",
  ui_story_5035_50350801_216_dialog_content = "뭐가 보여? 저기 뭐가 있는 거야?!",
  ui_story_5035_50350801_217_dialog_content = "미, 미노스인 것 같아.",
  ui_story_5035_50350801_218_dialog_content = "미노스 씨라고? 미노스 씨는 우리 옆에 있는 거 아냐?",
  ui_story_5035_50350801_219_dialog_content = "음, 미노스가 어디 있냐면...",
  ui_story_5035_50350801_220_dialog_content = "혼자 구석에서 벽을 보고 서 있어...",
  ui_story_5035_50350801_221_dialog_content = "잠깐만... 벼, 벽을 보고 있다고?",
  ui_story_5035_50350801_222_dialog_content = "다들 잊은 거 아니지? 아까 본 쪽지에 쓰여 있었잖아...",
  ui_story_5035_50350801_223_dialog_content = "응?",
  ui_story_5035_50350801_224_dialog_content = "말을 듣지 않는 아이한테 여주인이 벌을 주는데.",
  ui_story_5035_50350801_225_dialog_content = "하나는 벌을 받고, 다른 하나는... 벽을 보고 서서 그 소리를 듣게 한다고...",
  ui_story_5035_50350801_226_dialog_content = "설마... 아니지...?",
  ui_story_5035_50350801_227_dialog_content = "근데 미노스 씨가 지금 하고 있는 행동은 꼭...",
  ui_story_5035_50350801_228_dialog_content = "잠깐만! 만약 그게 사실이라면...!",
  ui_story_5035_50350801_229_dialog_content = "미노스 씨가 '듣는' 역할이라는 거잖아. 그럼 우린...",
  ui_story_5035_50350801_230_dialog_content = "<color=#e8d9bb>또옥...</color>",
  ui_story_5035_50350801_231_dialog_content = "큰일이야. 물방울 떨어지는 소리가 들려.",
  ui_story_5035_50350801_232_dialog_content = "싫어어어어!",
  ui_story_5035_50350801_233_dialog_content = "걱정 마, 내가 출구를 찾아볼 테니까...",
  ui_story_5035_50350801_234_dialog_content = "<color=#e8d9bb>누군가는 <size=50>벌</size>을 받아야 한다.</color>",
  ui_story_5035_50350801_235_dialog_content = "?!",
  ui_story_5035_50350801_236_dialog_content = "<color=#e8d9bb>툭!</color>",
  ui_story_5035_50350801_237_dialog_content = "으아악!",
  ui_story_5035_50350801_238_dialog_content = "<size=45>꺄아아!</size>",
  ui_story_5035_50350801_239_dialog_content = "<size=55>끼야악!</size>",
  ui_story_5035_50350801_240_dialog_content = "<color=#e8d9bb>팟!</color>",
  ui_story_5035_50350801_241_dialog_content = "<color=#e8d9bb>뚜벅──</color>",
  ui_story_5035_50350801_242_dialog_content = "<color=#e8d9bb>뚜벅── 뚜벅──</color>",
  ui_story_5035_50350801_243_dialog_content = "카메라까지 떨어트리시고, 다들 뭐 하십니까?",
  ui_story_5035_50350801_244_dialog_content = "PlayerName 님, 받으시지요.",
  ui_story_5035_50350801_245_dialog_content = "아, 응. 근데 미노스, 방금 너...",
  ui_story_5035_50350801_246_dialog_content = "조명의 전원이 나가는 바람에 가서 손을 좀 봤습니다.",
  ui_story_5035_50350801_247_dialog_content = "음, 그게 다야?",
  ui_story_5035_50350801_248_dialog_content = "그럼 벽을 보고 있었던 건...",
  ui_story_5035_50350801_249_dialog_content = "스위치가 그곳에 있었기 때문입니다만.",
  ui_story_5035_50350801_250_dialog_content = "......",
  ui_story_5035_50350801_251_dialog_content = "어둠 속에서 손의 감각만으로 스위치를 찾으려면 집중을 해야 합니다.\n여러분께서 조금만 조용히 해 주셨더라면 더 빨리 고칠 수 있었을 겁니다.",
  ui_story_5035_50350801_252_dialog_content = "그래서 여러분께서는 조금 전에 뭘 보신 겁니까?",
  ui_story_5035_50350801_253_dialog_content = "아, 뭘 봤냐면요... 그게...",
  ui_story_5035_50350801_254_dialog_content = "에이~ 새카맣게 어두워서 보이지도 않더라구요.",
  ui_story_5035_50350801_255_dialog_content = "후, 또 그냥 착각한 거라 다행이야.",
  ui_story_5035_50350801_256_dialog_content = "으으으, 아쉬워! 왜 또 착각인 거야!",
  ui_story_5035_50350801_257_dialog_content = "뭘 자꾸 기대하는 거냐고!",
  ui_story_5035_50350801_258_dialog_content = "에이~ 재미없어. 관두지 뭐, 오늘 밤의 《비명의 집 탐험》도 별 성과는 없을 것 같으니까.",
  ui_story_5035_50350801_259_dialog_content = "하암~ 졸리네. 졸리니까 단체 사진 다시 찍고 얼른 돌아가자.",
  ui_story_5035_50350801_260_dialog_content = "단체 사진 찍는 건 절대 안 잊어버리는구나...",
  ui_story_5035_50350801_261_dialog_content = "당연하지! 기념사진을 찍는 건 가장 중요한 일이라구!",
  ui_story_5035_50350801_262_dialog_content = "그리고 아까 캠코더를 떨어트렸으니까, 고장은 안 났는지 확인도 해 봐야 하구.\n만약에 고장 났으면, PlayerName 네가... 후훗.",
  ui_story_5035_50350801_263_dialog_content = "으악!",
  ui_story_5035_50350801_264_dialog_content = "아, 알겠어! 다들 빨리 자리에 서!",
  ui_story_5035_50350801_265_dialog_content = "그래, 그럴게.",
  ui_story_5035_50350801_266_dialog_content = "캠코더야, 내가 이렇게 부탁할게. 네가 튼튼한 녀석이란 거 다 알아.",
  ui_story_5035_50350801_267_dialog_content = "셔터 누르고 나면 이쪽으로 뛰어와야 하는 거 잊으면 안 돼~",
  ui_story_5035_50350801_268_dialog_content = "넌 할 수 있어! 자, 힘내자!",
  ui_story_5035_50350801_269_dialog_content = "하나... 둘... 셋...",
  ui_story_5035_50350801_270_dialog_content = "<color=#e8d9bb>찰칵!</color>",
  ui_story_5035_50350901_1_dialog_content = "《비명의 집 탐험》, 크랭크업!",
  ui_story_5035_50350901_2_dialog_content = "최고야~ 아주 좋아! 그럼 미노스 씨, 이 저택에서 사진을 현상하려면 어디로 가야 해?",
  ui_story_5035_50350901_3_dialog_content = "사진을 출력해서 모두한테 선물해 주고 싶어!",
  ui_story_5035_50350901_4_dialog_content = "따라오십시오. 제 사무실에 사진을 현상할 수 있는 암실이 있습니다.",
  ui_story_5035_50350901_5_dialog_content = "다른 분들도 함께 가시지요. 여러분께 오늘 밤에 묵으실 방을 준비해 드리겠습니다.",
  ui_story_5035_50350901_6_dialog_content = "그리고 오늘 일어났던 수많은 일들 중 몇 부분은 우리 모두 차분히 생각해 봐야 하니까요.",
  ui_story_5035_50350901_7_dialog_content = "음, 맞는 말이야. 그러고 보니까 오늘 하루 동안 너무 생각 없이 다닌 것 같아.",
  ui_story_5035_50350901_8_dialog_content = "생각할 시간 없이 사건들 발생,\n머리를 안 쓰면 손발이 고생?\n차라리 손발을 쓸래 난 평생♪",
  ui_story_5035_50350901_9_dialog_content = "갑자기 생각난 건데, 아까 지하실에서 불이 꺼졌을 때 누가 이상한 말 하지 않았어?",
  ui_story_5035_50350901_10_dialog_content = "이상한 말?",
  ui_story_5035_50350901_11_dialog_content = "「누군가는 벌을 받아야 한다」였나 그랬어. 누구 목소린지 모르겠더라고.",
  ui_story_5035_50350901_12_dialog_content = "어라? 누가 그런 말을 했다고?",
  ui_story_5035_50350901_13_dialog_content = "난 못 들은 것 같은데.",
  ui_story_5035_50350901_14_dialog_content = "어? 다들 못 들었어?",
  ui_story_5035_50350901_15_dialog_content = "설마 거기에 우리 말고 다른...",
  ui_story_5035_50350901_16_dialog_content = "으으, 사람 겁주지 좀 마!",
  ui_story_5035_50350901_17_dialog_content = "빨리 가자!",
  ui_story_5035_50350901_18_dialog_content = "와! 미노스 씨의 방은 정말 깔끔하구나!",
  ui_story_5035_50350901_19_dialog_content = "방 안에는 촬영팀의 기자재가 많이 쌓여 있으니, 함부로 만지시면 안 됩니다.",
  ui_story_5035_50350901_20_dialog_content = "응, 나도 알아. 암실은 안쪽에 있어?",
  ui_story_5035_50350901_21_dialog_content = "네, 저쪽에 있는 작은 문 뒤에 있습니다. 사진 현상 방법은 알고 계십니까?",
  ui_story_5035_50350901_22_dialog_content = "당연하지! 난 프로 촬영...",
  ui_story_5035_50350901_23_dialog_content = "음, 촬영 마니아잖아.",
  ui_story_5035_50350901_24_dialog_content = "자기가 지금 뭐라고 했는지 들어볼래?",
  ui_story_5035_50350901_25_dialog_content = "하핫, 사진을 현상하려면 시간이 좀 필요하니까 다들 기다려 줘.",
  ui_story_5035_50350901_26_dialog_content = "휴우~ 힘들어 죽겠네. 좀 쉬자.",
  ui_story_5035_50350901_27_dialog_content = "이번에 「안데르센 비명의 집」에 오길 잘했어. 진짜 너무 짜릿해!",
  ui_story_5035_50350901_28_dialog_content = "그렇게나 놀라 놓고 「오길 잘했다」라니...",
  ui_story_5035_50350901_29_dialog_content = "초자연적인 걸 좋아하는 마음이랑, 그걸 무서워하는 마음은 공존할 수 있는 거야.",
  ui_story_5035_50350901_30_dialog_content = "쉽게 말하면 초자연적인 사건을 무서워하기 때문에,\n초자연적인 현상이 지닌 미스터리함을 좋아하게 된다는 거지!",
  ui_story_5035_50350901_31_dialog_content = "그런 거야?",
  ui_story_5035_50350901_32_dialog_content = "물론이지. 니나 양이 이 저택을 산 이유도 나 같은 초자연적 현상 마니아들의\n마음을 사로잡기 위해서라구.",
  ui_story_5035_50350901_33_dialog_content = "「안데르센 비명의 집」을 이렇게 열심히 준비해 준 니나 양한테 고마워 해야겠어.\n여긴 앞으로 분명히 대박 날 거야!",
  ui_story_5035_50350901_34_dialog_content = "두 분께서는 오늘 밤에 일어났던 일들이 모두 비명의 집에서\n준비해 둔 연출이라고 생각하시는 겁니까?",
  ui_story_5035_50350901_35_dialog_content = "네?",
  ui_story_5035_50350901_36_dialog_content = "니나 아가씨께서 몇몇 준비를 해 두신 것은 맞습니다.",
  ui_story_5035_50350901_37_dialog_content = "하지만, 오늘 밤에 겪은 일들은 대부분 사전에 준비해 둔 것들이 아니었습니다.",
  ui_story_5035_50350901_38_dialog_content = "예를 들면, 방금 전에 지하실이 정전된 것처럼요?",
  ui_story_5035_50350901_39_dialog_content = "맞습니다. 말씀드렸다시피 지하실은 비명의 집의 영업 범위에 속하지 않습니다.",
  ui_story_5035_50350901_40_dialog_content = "어쩌면 뜻밖의 사고일 수도 있단 건가요?",
  ui_story_5035_50350901_41_dialog_content = "뜻밖의 상황은 초자연적 사건에서 빼놓을 수 없는 필수 요소예요!",
  ui_story_5035_50350901_42_dialog_content = "네, 저도 조금 전까지는 그렇게 생각했었습니다.",
  ui_story_5035_50350901_43_dialog_content = "설명할 수 없는 사건을 마주하게 됐을 때는 '뜻밖의 상황',\n'우연히 발생한 일'이라는 답을 내리는 것이 가장 좋습니다.",
  ui_story_5035_50350901_44_dialog_content = "제 말이 그 말이에요! 게다가 저랑 PlayerName 주변에선 뜻밖의 일들이 자주 일어나거든요...",
  ui_story_5035_50350901_45_dialog_content = "그러나 조금 전, 저는 그 '뜻밖의 상황'들 속에서 모순을 발견했습니다.",
  ui_story_5035_50350901_46_dialog_content = "네? 무슨 모순이요?",
  ui_story_5035_50350901_47_dialog_content = "얼마 전 신문에 이런 기사가 실렸던 적이 있습니다. 두 분 다 보신 적이 있으실지 모르겠군요.",
  ui_story_5035_50350901_48_dialog_content = "아마 「모 공포 영화 여주인공의 기묘한 실종」 비슷한 제목이었을 겁니다.",
  ui_story_5035_50350901_49_dialog_content = "아! 그 기사! 나 그거 기억나!",
  ui_story_5035_50350901_50_dialog_content = "「바람과 함께 사라지다! 어떤 삼류 공포 영화 여주인공의 기묘한 실종」?!",
  ui_story_5035_50350901_51_dialog_content = "확실히 움브라톤은 그런 사건이 일어나도 이상할 게 없는 곳이긴 한데...",
  ui_story_5035_50350901_52_dialog_content = "아무래도 노이즈 마케팅 냄새가 나는걸?",
  ui_story_5035_50350901_53_dialog_content = "사실 그 여배우가 출연했던 영화가 바로 조니 감독의 제작팀의 전작이었습니다.",
  ui_story_5035_50350901_54_dialog_content = "어?! 그럼 내 선배네?",
  ui_story_5035_50350901_55_dialog_content = "맞습니다. 단지 그때는 아가씨께서 이 비명의 집을 구매하시기 전이라\n저는 그 영화의 제작 스태프가 아니었습니다.",
  ui_story_5035_50350901_56_dialog_content = "이 사건에 대해서는 제작팀이 기록해 둔 서류를 통해 알게 되었지요.",
  ui_story_5035_50350901_57_dialog_content = "그래서? 그 여배우는 어쩌다 실종된 거야?",
  ui_story_5035_50350901_58_dialog_content = "그건 저도 모릅니다. 서류에는 그 여배우가 촬영에 참여했다는 내용밖에\n기록되어있지 않았으니까요.",
  ui_story_5035_50350901_59_dialog_content = "그러면 아까 말한 모순이라는 건 뭐야?",
  ui_story_5035_50350901_60_dialog_content = "조금 전, 지하실에서 「영화 제작팀 업무 일지」를 주웠지요. 기억하십니까?",
  ui_story_5035_50350901_61_dialog_content = "거기에 바로 전작의 촬영 현장 상황이 기록돼 있었습니다.",
  ui_story_5035_50350901_62_dialog_content = "앗! 그럼 그게 바로 실종된 여배우가 출연했다는 그 영화겠네?!",
  ui_story_5035_50350901_63_dialog_content = "그렇습니다. 그 영화는 중간에 촬영이 중단되었지요.\n분명히 여배우의 실종과 관계가 있을 겁니다.",
  ui_story_5035_50350901_64_dialog_content = "그래서 전 그 업무 일지에 기록되어 있던 촬영 일정을 자세히 살펴보았습니다.",
  ui_story_5035_50350901_65_dialog_content = "그리고 알게 되었습니다. 그때 뜻밖의 상황이 벌어지지만 않았더라면,\n오늘이 바로 촬영이 종료되는 날이더군요.",
  ui_story_5035_50350901_66_dialog_content = "모순점을 발견하셨습니까?",
  ui_story_5035_50350901_67_dialog_content = "일정에 문제가 있다는 거야?",
  ui_story_5035_50350901_68_dialog_content = "네. 실종된 여배우의 가족과 친구들은 아직도 그녀가\n영화를 촬영하고 있는 줄 알고 있겠지요.",
  ui_story_5035_50350901_69_dialog_content = "제작진이 여배우 가족의 연락처를 가지고 있지 않다면,\n제작팀 이외의 사람들은 그녀의 행방에 대해 알 수 없습니다.",
  ui_story_5035_50350901_70_dialog_content = "그녀가 실종되었다고 여기지 않을 것이라는 겁니다.",
  ui_story_5035_50350901_71_dialog_content = "음, 듣고 보니까 진짜 그러네...",
  ui_story_5035_50350901_72_dialog_content = "<color=#e8d9bb>짝! 짝! 짝!</color>",
  ui_story_5035_50350901_73_dialog_content = "대단해! 놀라운 추리력이야!",
  ui_story_5035_50350901_74_dialog_content = "리리카, 언제 나타난 거야? 사진은 다 현상했어?",
  ui_story_5035_50350901_75_dialog_content = "응, 근데 마를 때까지 좀 더 기다려야 해.",
  ui_story_5035_50350901_76_dialog_content = "계속 추리해 봐~ 아무도 여배우가 실종된 걸 모른다면, 그 기사는 어떻게 된 건데?",
  ui_story_5035_50350901_77_dialog_content = "가능성은 두 가지뿐입니다.",
  ui_story_5035_50350901_78_dialog_content = "제작팀, 혹은 여배우 자신이 신문사에 실종 소식을 전달했거나.",
  ui_story_5035_50350901_79_dialog_content = "우와! 맞아, 사정을 알고 있는 건 그 사람들뿐일 테니까!",
  ui_story_5035_50350901_80_dialog_content = "그렇다곤 해도 잘 생각해 보면, 양쪽 다 그렇게 해야 할 이유가 없지 않아?",
  ui_story_5035_50350901_81_dialog_content = "배우가 실종됐다는 뉴스가 제작진한테 무슨 도움이 된다고\n굳이 부정적인 기사를 내보내 달라고 하겠어.",
  ui_story_5035_50350901_82_dialog_content = "여배우 쪽도 자기가 실종됐다는 소식을 퍼트릴 이유가 없는 것 같은데?",
  ui_story_5035_50350901_83_dialog_content = "그 문제에 대해서는 저도 생각 중입니다만, 아직도 결론을 내리지는 못했습니다.",
  ui_story_5035_50350901_84_dialog_content = "음... 내가 볼 땐 여배우가 자작극을 벌인 건 아닌 것 같아.",
  ui_story_5035_50350901_85_dialog_content = "별로 유명하지도 않으니까 실종 기사가 나도 별로 주목도 못 받잖아.",
  ui_story_5035_50350901_86_dialog_content = "이런 기사는 돈을 내야 실어 줄 텐데, 그 여배우한테는 그럴 돈도 없을걸.",
  ui_story_5035_50350901_87_dialog_content = "한 가지 가능성에 집중해 생각해 보는 게 나을지도 몰라.\n만약에 그 소식을 퍼트린 게 제작팀이면, 제작팀의 목적은 뭘까?",
  ui_story_5035_50350901_88_dialog_content = "제작팀 입장만 고려해 본다면...",
  ui_story_5035_50350901_89_dialog_content = "실종 기사를 내려면 돈을 쓰고 부정적인 이미지를 얻는 게 될 테니,\n아무리 생각해도 그런 일을 벌여야 할 가치가 없습니다.",
  ui_story_5035_50350901_90_dialog_content = "기꺼이 이 모든 대가를 치를 정도로, 기사를 내보내고 난 후의 결과가\n제작팀에게 매우 중요한 게 아니라면 말이지요.",
  ui_story_5035_50350901_91_dialog_content = "호오?",
  ui_story_5035_50350901_92_dialog_content = "다시 말해서, 제작팀이 여배우의 행방에 무척 신경을 쓰고 있다는 겁니다.",
  ui_story_5035_50350901_93_dialog_content = "아마 이런 방식을 통해 실종된 여배우를 찾으려는 걸지도 모릅니다.",
  ui_story_5035_50350901_94_dialog_content = "<color=#e8d9bb>짝! 짝! 짝!</color>",
  ui_story_5035_50350901_95_dialog_content = "아주 좋아! 그거면 모든 게 설명이 돼!",
  ui_story_5035_50350901_96_dialog_content = "가능성의 돌파구를 하나 찾았다고 볼 수 있겠지요.",
  ui_story_5035_50350901_97_dialog_content = "근데 생각해 봐야 할 문제는 아직도 많습니다. 왜 여배우를 찾으려고 하는 걸까요?\n그리고 여배우는 대체 어쩌다 실종된 것일까요...",
  ui_story_5035_50350901_98_dialog_content = "<color=#e8d9bb>짝! 짝! 짝!</color>",
  ui_story_5035_50350901_99_dialog_content = "리리카 양, 박수를 자제해 주시겠습니까? 생각하는 데 집중력이 분산됩니다.",
  ui_story_5035_50350901_100_dialog_content = "어라? 나?",
  ui_story_5035_50350901_101_dialog_content = "나 박수 안 치고 있는데?",
  ui_story_5035_50350901_102_dialog_content = "<color=#e8d9bb>짝! 짝! 짝!</color>",
  ui_story_5035_50350901_103_dialog_content = "누구든 좋으니 제발 그만해 주십시오. 자꾸 소음을 내시면 곤란합니다.",
  ui_story_5035_50350901_104_dialog_content = "......",
  ui_story_5035_50350901_105_dialog_content = "......",
  ui_story_5035_50350901_106_dialog_content = "......",
  ui_story_5035_50350901_107_dialog_content = "<color=#e8d9bb>짝짝짝짝짝짝짝짝짝짝짝짝!</color>",
  ui_story_5035_50350901_108_dialog_content = "밖에서 들리는 것 같아.",
  ui_story_5035_50350901_109_dialog_content = "바, 밖에 사람이 있나?",
  ui_story_5035_50350901_110_dialog_content = "사람이면 다행인데...",
  ui_story_5035_50350901_111_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5035_50350901_112_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5035_50350901_113_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5035_50350901_114_dialog_content = "그어어어!",
  ui_story_5035_50350901_115_dialog_content = "또야! 짜증 나는 녀석들!",
  ui_story_5035_50350901_116_dialog_content = "이 안으로 들어오게 하면 안 돼!\n미노스 씨가 이 안에 있는 장비들은 함부로 건드리면 안 된댔어!",
  ui_story_5035_50350901_117_dialog_content = "장비보다 자기 안전부터 생각해야 하는 거 아냐?!",
  ui_story_5035_50350901_118_dialog_content = "난 도망칠 수 있지만, 장비들은 그게 안 되잖아!",
  ui_story_5035_50350901_119_dialog_content = "듣고 보니까 맞는 말이네...",
  ui_story_5035_50350901_120_dialog_content = "아무튼! 녀석들을 다 쫓아내는 거야!",
  ui_story_5035_50351002_1_dialog_content = "훗, 이 정도쯤은 문제없다구~",
  ui_story_5035_50351002_2_dialog_content = "뭔가 가끔씩 암귀 몇 마리를 쓰러트리는 일상에 조금 익숙해진 기분이야.",
  ui_story_5035_50351002_3_dialog_content = "그럼 미노스한테 방을 하나 빌려주라고 할 테니까,\n앞으로 쭉 이 비명의 집에 살면 되겠네.",
  ui_story_5035_50351002_4_dialog_content = "참, 미노스는 뭐 하고 있어? 전투할 때 못 본 것 같은데?",
  ui_story_5035_50351002_5_dialog_content = "암귀한텐 전혀 관심이 없어 보이는데...",
  ui_story_5035_50351002_6_dialog_content = "장부에는... 이상이 없군요.",
  ui_story_5035_50351002_7_dialog_content = "임대계약서에도... 이상이 없습니다.",
  ui_story_5035_50351002_8_dialog_content = "이럴 리가... 분명히 어딘가에 수상한 흔적을 남겼을 텐데. 다시 한번 살펴봐야겠군요...",
  ui_story_5035_50351002_9_dialog_content = "으앗! 바닥에 서류가 잔뜩이네.",
  ui_story_5035_50351002_10_dialog_content = "미노스 씨, 서류에 파묻히려는 거야?",
  ui_story_5035_50351002_11_dialog_content = "이 제작팀의 신뢰성을 확인하고 있습니다.",
  ui_story_5035_50351002_12_dialog_content = "만약 운영에 문제가 있다면 즉시 파트너십을 종료해야 하니까요.",
  ui_story_5035_50351002_13_dialog_content = "아가씨의 사업에 조금이라도 오점을 남기게 둘 수는 없습니다.",
  ui_story_5035_50351002_14_dialog_content = "우와! 본분에 엄청 충실한 집사구나!",
  ui_story_5035_50351002_15_dialog_content = "여기 있는 건 전부 제작팀과 관련된 서류입니다.",
  ui_story_5035_50351002_16_dialog_content = "그 여배우의 실종은 무엇과도 무관한 별개의 사건이 아닙니다.",
  ui_story_5035_50351002_17_dialog_content = "사건이 발생하게 된 이유, 사건이 벌어지고 나서의 결과가 분명히 존재해야 하지요.",
  ui_story_5035_50351002_18_dialog_content = "그리고 그 실종 사건에서 뻗어나간 가지들이 바로 이 서류들 속에 숨어 있습니다.",
  ui_story_5035_50351002_19_dialog_content = "진상에 다가가기 위해서는 그 가지들을 찾아내야 합니다.",
  ui_story_5035_50351002_20_dialog_content = "맞는 말이긴 한데... 서류가 너무 많은걸?",
  ui_story_5035_50351002_21_dialog_content = "나 태어나서 지금까지 이렇게 많은 글자는 본 적 없었어.",
  ui_story_5035_50351002_22_dialog_content = "제가 다 한 번씩 읽어 봤습니다만, 수상쩍은 점은 발견하지 못했습니다.",
  ui_story_5035_50351002_23_dialog_content = "빨라!",
  ui_story_5035_50351002_24_dialog_content = "나, 난 글자를 많이 읽어야 하는 일은 잘 못하거든. 그러니까 괜히 옆에서 귀찮게 안 할게.",
  ui_story_5035_50351002_25_dialog_content = "마침 현상한 사진들도 거의 다 말랐을 테니까, 그거나 확인하러 갈게.",
  ui_story_5035_50351002_26_dialog_content = "소품 목록... 구매 기록... 비즈니스 파트너십...",
  ui_story_5035_50351002_27_dialog_content = "잠깐... 사진?",
  ui_story_5035_50351002_28_dialog_content = "사진... 사진...",
  ui_story_5035_50351002_29_dialog_content = "사진! 답은 사진이었습니다!",
  ui_story_5035_50351002_30_dialog_content = "미노스, 왜 그래? 깜짝 놀랐잖아.",
  ui_story_5035_50351002_31_dialog_content = "제 생각이 너무 편협했습니다.",
  ui_story_5035_50351002_32_dialog_content = "제가 살펴본 문서들 속에 수상한 점은 확실히 없었습니다.",
  ui_story_5035_50351002_33_dialog_content = "왜냐하면 수상한 건 문서에 적혀 있는 부분들이 아니라,\n'어떤 물건'이 보이지 않는다는 사실이니까요.",
  ui_story_5035_50351002_34_dialog_content = "무슨 말이야? 무슨 물건?",
  ui_story_5035_50351002_35_dialog_content = "촬영 현장을 찍은 사진입니다.",
  ui_story_5035_50351002_36_dialog_content = "사진은 반드시 기록해 두어야 하는 물건이 아니기에, 전 그걸 잊고 있었던 겁니다.",
  ui_story_5035_50351002_37_dialog_content = "일반적으로는 기념용이든 홍보용이든 영화 촬영을 할 때는\n현장 사진을 많이 찍어 두기 마련입니다.",
  ui_story_5035_50351002_38_dialog_content = "그렇지만 이 서류들 속에는 사진이 단 한 장도 없습니다.",
  ui_story_5035_50351002_39_dialog_content = "아니야, 그건 좀 말이 안 돼.\n오늘만 해도 감독님이 날 데리고 촬영 현장 사진을 찍었는걸.",
  ui_story_5035_50351002_40_dialog_content = "딱 한 번이긴 하지만, 예전에도 현장 사진을 찍었을 거야.",
  ui_story_5035_50351002_41_dialog_content = "현장 사진을 '촬영한 적이 있다'와 '남기지 않았다'는 공존할 수 있는 상황입니다.",
  ui_story_5035_50351002_42_dialog_content = "어쩌면 다른 사람들에게 그 사진들을 보여서는 안 되기 때문일지도 모르지요...",
  ui_story_5035_50351002_43_dialog_content = "사진 다 인화했어!",
  ui_story_5035_50351002_44_dialog_content = "꽤 잘 찍었더라~ 다들 와서 확인해 볼래?",
  ui_story_5035_50351002_45_dialog_content = "어? 지금?",
  ui_story_5035_50351002_46_dialog_content = "사진을 볼 분위기는 아닌 것 같아. 방금 막 사건 조사에 조금 진전이 있었거든...",
  ui_story_5035_50351002_47_dialog_content = "에이~ 뭘 그렇게 긴장하구 그래~",
  ui_story_5035_50351002_48_dialog_content = "기분 전환을 하면 추리할 때도 더 좋을 거야.",
  ui_story_5035_50351002_49_dialog_content = "자, 자, 자~ 다들 여기 모여 봐.",
  ui_story_5035_50351002_50_dialog_content = "새디, 너 표정 완전 굳었네.",
  ui_story_5035_50351002_51_dialog_content = "무슨 상관이야.",
  ui_story_5035_50351002_52_dialog_content = "집사 씨~ 다음에 사진 찍을 때는 꼭 카메라를 바라봐야 해!",
  ui_story_5035_50351002_53_dialog_content = "네.",
  ui_story_5035_50351002_54_dialog_content = "PlayerName하고 바이스는 꽤 잘 찍혔어~ 배우가 될 자질이 보여!",
  ui_story_5035_50351002_55_dialog_content = "배우라는 게 이 정도로도 할 수 있는 직업이었어?!",
  ui_story_5035_50351002_56_dialog_content = "그냥 카메라 보고 표정만 지은 거야. 배우가 되려면 한참...",
  ui_story_5035_50351002_57_dialog_content = "우리 있잖아... 5명 맞지?",
  ui_story_5035_50351002_58_dialog_content = "응! 하나, 둘, 셋, 넷, 다섯, 다섯 명 맞아!",
  ui_story_5035_50351002_59_dialog_content = "근데 왜 사진에 손이 하나 더 있는 거지...?",
  ui_story_5035_50351002_60_dialog_content = "!!!",
  ui_story_5035_50351002_61_dialog_content = "지, 진짜야! 누구 건지 모를 손이 하나 있어!",
  ui_story_5035_50351002_62_dialog_content = "어라? 뭐?! 으앗!",
  ui_story_5035_50351002_63_dialog_content = "...지하실에 우리 이외에 다른 사람은 없었다고 장담할 수 있습니다.",
  ui_story_5035_50351002_64_dialog_content = "응, 나도 마찬가지야. 하지만 사진에 나온 이 손은...",
  ui_story_5035_50351002_65_dialog_content = "사진... 제작팀...",
  ui_story_5035_50351002_66_dialog_content = "설마 제작팀이 촬영 현장 사진을 남겨두지 않은 이유가...",
  ui_story_5035_50351002_67_dialog_content = "PlayerName, 갑자기 생각난 건데...",
  ui_story_5035_50351002_68_dialog_content = "바바 야가가 우리한테 했던 말, 아직 기억해...?",
  ui_story_5035_50351002_69_dialog_content = "PlayerName... 아직 <color=#FFB400>그녀</color>가 네 곁에 없는 것 같아.",
  ui_story_5035_50351002_70_dialog_content = "아마 내가 너희보다 먼저 <color=#FFB400>그녀</color>를 알아챈 모양이네.",
  ui_story_5035_50351002_71_dialog_content = "<color=#FFB400>그녀한테 사로잡히지 않도록 조심해...</color>",
  ui_story_5035_50351002_72_dialog_content = "왜냐하면, 오직 나만이 <color=#FFB400>그녀를 사랑의 「만찬」으로 끌어들일 수 있으니까</color>.",
  ui_story_5035_50351002_73_dialog_content = "응, 기억나.",
  ui_story_5035_50351002_74_dialog_content = "바바 야가가 말한 「그녀」가 우리 중 누구인지 맞혀 보려고 했었는데,\n그게 누군지 지금까지 알아낼 수 없었어.",
  ui_story_5035_50351002_75_dialog_content = "근데 이제 보니 진짜로 「그녀」가 있었던 거야...",
  ui_story_5035_50351002_76_dialog_content = "「그녀한테 사로잡히지 않도록 조심해...」",
  ui_story_5035_50351002_77_dialog_content = "바바 야가는 우리한테 경고했던 거였어...",
  ui_story_5035_50351002_78_dialog_content = "이 저택 어딘가에 있으면서, 우리가 단 한 번도 만나지 못한 무언가를...",
  ui_story_5035_50351002_79_dialog_content = "우리 뒤에 나타나는 「유령 여인」을 조심하라고 말이야.",
  ui_story_5035_50351101_1_dialog_content = "(정말 이 세상에 유령이 존재한다고 믿어야 하는 걸까?)",
  ui_story_5035_50351101_2_dialog_content = "(난 잡생각을 하기 좋을 때 이 문제에 대해서 여러 번 생각해 봤었다.)",
  ui_story_5035_50351101_3_dialog_content = "(아무리 생각해 봐야 답을 얻을 수도 없고, 증명할 방법도 없으니까\n매번 그냥 심심풀이로만 생각했다.)",
  ui_story_5035_50351101_4_dialog_content = "(그런데 갑자기 이 문제가 내 앞에 떡하니 나타났다.)",
  ui_story_5035_50351101_5_dialog_content = "(사진 속에 나온 유령 여인과 나 사이의 거리처럼, 이 문제는 이제 내 코앞에 닥쳤다.)",
  ui_story_5035_50351101_6_dialog_content = "(나 자신을 구하려면 유령의 손이 내 목을 조르기 전까지,\n서둘러 이 문제에 대한 답을 찾아야만 한다.)",
  ui_story_5035_50351101_7_dialog_content = "아무래도 진짜로 이 세상에...",
  ui_story_5035_50351101_8_dialog_content = "역시 그랬던 거야! 이 저택 안엔 진짜로 유령이 있었어!",
  ui_story_5035_50351101_9_dialog_content = "어...?",
  ui_story_5035_50351101_10_dialog_content = "역시! 사진이 바로 결정적인 증거였던 거야!",
  ui_story_5035_50351101_11_dialog_content = "이렇게 손쉽게 문제를 해결하다니! 역시 이 심령 탐정 리리카는 대단하다니까!",
  ui_story_5035_50351101_12_dialog_content = "가자! 가서 제작팀한테 따져야지!",
  ui_story_5035_50351101_13_dialog_content = "잠깐만, 다시 좀 생각해 보면 안 돼? 아무리 그래도 유령이니 뭐니 하는 건 너무...",
  ui_story_5035_50351101_14_dialog_content = "그리고 왜 제작팀한테 따지겠다는 건데?",
  ui_story_5035_50351101_15_dialog_content = "그들이 유령 여인의 존재에 대해 알고 있었기 때문에\n일부러 촬영 현장 사진을 숨긴 것일 수도 있습니다.",
  ui_story_5035_50351101_16_dialog_content = "하지만 어디까지나 추측일 뿐입니다.\n지금은 아직 「유령 여인」과 「제작팀」을 연결할 단서가 없습니다.",
  ui_story_5035_50351101_17_dialog_content = "경솔하게 행동했다가는 긁어 부스럼만 날 뿐이니 충동적으로 행동하지 마십시오.",
  ui_story_5035_50351101_18_dialog_content = "후훗, 「유령 여인」과 「제작팀」을 연결할 단서가 부족하다면 말이야...",
  ui_story_5035_50351101_19_dialog_content = "실종됐다는 그 여배우를 더하면 어떻게 될까?",
  ui_story_5035_50351101_20_dialog_content = "<color=#e8d9bb>촤악──</color>",
  ui_story_5035_50351101_21_dialog_content = "짜자잔! 모두한테 리리카의 진짜 모습을 보여 줄게!",
  ui_story_5035_50351101_22_dialog_content = "아까랑 별 차이가 없잖아!",
  ui_story_5035_50351101_23_dialog_content = "근데 진작부터 물어보고 싶긴 했어. 그 어색한 콧수염은 대체 왜 붙인 거야?!",
  ui_story_5035_50351101_24_dialog_content = "아니지... 잠깐만, 뭐라고? 실종된 여배우?!",
  ui_story_5035_50351101_25_dialog_content = "딩동댕! 「기묘하게 실종됐다는 어떤 삼류 공포 영화 여주인공」이 바로 나, 리리카야!",
  ui_story_5035_50351101_26_dialog_content = "뭐?!",
  ui_story_5035_50351101_27_dialog_content = "엥?",
  ui_story_5035_50351101_28_dialog_content = "음...",
  ui_story_5035_50351101_29_dialog_content = "그럼 문제가 쉽게 해결되겠군요. 어서 어떻게 된 일인지 알려 주시겠습니까?",
  ui_story_5035_50351101_30_dialog_content = "일단 내가 조니 감독이 저번에 촬영한 공포 영화에 출연했을 때부터 얘기해야 할 것 같아.",
  ui_story_5035_50351101_31_dialog_content = "난 어렸을 때부터 영화를 좋아했거든. 특히 공포 영화를 좋아했어.",
  ui_story_5035_50351101_32_dialog_content = "그래서 조니 감독이 자기 신작에 출연해 달라고 했을 땐 정말 기뻤어.",
  ui_story_5035_50351101_33_dialog_content = "그 영화의 촬영 장소는, 모두 이미 알고 있듯이 바로 이 저택이었고.",
  ui_story_5035_50351101_34_dialog_content = "처음에는 촬영도 순조로웠어.\n근데 지하실 장면 촬영에 들어갔을 때... 뜻밖의 상황이 벌어졌어.",
  ui_story_5035_50351101_35_dialog_content = "뜻밖의 상황? 무슨 일이 있었던 거야?",
  ui_story_5035_50351101_36_dialog_content = "현장이 좀 혼란스러웠어. 우선은 물방울 떨어지는 소리랑 방울 소리가 들리더라고.",
  ui_story_5035_50351101_37_dialog_content = "참, 그리고 촛불도 있었어. 뜬금없이 지하실에 촛불이 놓여 있었던 걸 봤어.",
  ui_story_5035_50351101_38_dialog_content = "그러더니 무언가가 나타났어. 제대로 보진 못했지만... 사람은 아닌 것 같았어.",
  ui_story_5035_50351101_39_dialog_content = "그 무언가는 날 죽이고 싶어 했어. 그 욕망은 정말, 정말로 강렬했어.",
  ui_story_5035_50351101_40_dialog_content = "난 습격을 받고 심하게 다쳤어. 하마터면 거기서 죽는 줄 알았을 정도였고.",
  ui_story_5035_50351101_41_dialog_content = "다행히 내가 어렸을 때부터 잘하는 게 바로 도망치는 거였거든.",
  ui_story_5035_50351101_42_dialog_content = "깊은 밤에 난 한참을 달리고 또 달려서 드디어 움브라톤으로 돌아갈 수 있었고,\n한 의사가 날 구해 줬어.",
  ui_story_5035_50351101_43_dialog_content = "그 의사의 병원에서 이틀 동안 기절해 있고 나서야,\n난 간신히 위기를 넘기고 다시 깨어날 수 있었어.",
  ui_story_5035_50351101_44_dialog_content = "어떻게 그런 일이... 하마터면 큰일 날 뻔했구나.",
  ui_story_5035_50351101_45_dialog_content = "그럼 지하실에 갔을 때 나한테 캠코더를 켜고 촬영을 해 달라고 했던 것도...",
  ui_story_5035_50351101_46_dialog_content = "맞아. 혹시라도 무슨 일이 일어난다면,\n적어도 캠코더 속 영상을 통해 진실을 알 수 있을 테니까.",
  ui_story_5035_50351101_47_dialog_content = "그런 일을 겪고도 다시 돌아오다니. 담력이 대단하네.",
  ui_story_5035_50351101_48_dialog_content = "나였으면 평생 두 번 다시는 이 근처에 오려고 하지도 않았을 거야.",
  ui_story_5035_50351101_49_dialog_content = "사실 나도 처음엔 돌아오고 싶지 않았어.\n그렇게 무서운 유령을 내가 왜 그걸 건드리려고 하겠어.",
  ui_story_5035_50351101_50_dialog_content = "근데 곧 내 귀에 이상한 소식이 들려왔어.\n조니 감독의 촬영팀이 같은 저택에서 계속 영화 촬영을 한다는 거야.",
  ui_story_5035_50351101_51_dialog_content = "...그런 상황을 겪었는데도 계속 그러는 건 확실히 이상해.",
  ui_story_5035_50351101_52_dialog_content = "곧이어 난 신문에 내 실종 기사가 났다는 걸 보게 됐어.",
  ui_story_5035_50351101_53_dialog_content = "......",
  ui_story_5035_50351101_54_dialog_content = "그리고 리리카 양은 저와 같은 결론을 내리신 것이군요.",
  ui_story_5035_50351101_55_dialog_content = "어쩌면 조금 전 리리카 양께서 제가 그런 추리를 할 수 있도록 이끌어 주셨는지도 모르겠군요.",
  ui_story_5035_50351101_56_dialog_content = "「음... 내가 볼 땐 여배우가 자작극을 벌인 건 아닌 것 같아.」",
  ui_story_5035_50351101_57_dialog_content = "「한 가지 가능성에 집중해 생각해 보는 게 나을지도 몰라.\n만약에 그 소식을 퍼트린 게 제작팀이면, 제작팀의 목적은 뭘까?」",
  ui_story_5035_50351101_58_dialog_content = "에헤헷, 이끌어주긴~ 그냥 미노스 씨를 위해 틀린 선택지를 좀 없애 줬을 뿐인걸.",
  ui_story_5035_50351101_59_dialog_content = "그때 난 오랫동안 생각한 끝에, 제작팀이 이상한 행동을 한 이유에 대해\n소름 돋는 추측을 하게 됐어.",
  ui_story_5035_50351101_60_dialog_content = "이 저택에는 진짜로 유령이 있고, 제작팀도 그 사실을 알고 있다는 거였어.",
  ui_story_5035_50351101_61_dialog_content = "이 촬영지는 제작팀이 찾아낸 곳이었고, 여긴 정말로 유령이 나타나는 곳이었으니까.",
  ui_story_5035_50351101_62_dialog_content = "어떻게 그런 일이... 그렇다면 저 사람들의 목적은...",
  ui_story_5035_50351101_63_dialog_content = "가짜인 것 같은 실제 상황을 만드는 거야.\n그리고 나처럼 사정을 모르는 여배우를 속여서 촬영에 참여하게 하는 거지.",
  ui_story_5035_50351101_64_dialog_content = "인위적으로 만들어낸 공포가 아무리 정교하다고 해도,\n진짜 귀신 소동만큼 사람들의 마음을 뒤흔들지는 못할 테니까.",
  ui_story_5035_50351101_65_dialog_content = "녀석들은 단 하나밖에 없는 공포 영화를 만들기 위해 수단과 방법을 가리지 않았던 거야.",
  ui_story_5035_50351101_66_dialog_content = "가짜인 것 같은 실제 상황을 만든다...",
  ui_story_5035_50351101_67_dialog_content = "그럼 그 사람들은 리리카가 돌아오게 만들어서,\n그 영화를 완성하기 위해 실종 기사를 낸 거라는 말이네?",
  ui_story_5035_50351101_68_dialog_content = "응, 분명히 그럴 거야.",
  ui_story_5035_50351101_69_dialog_content = "그때 촬영은 결말 부분만 남겨 둔 상태였거든.\n내가 남은 일을 마치지 않는다면, 촬영해 뒀던 필름들도 다 헛수고가 되는 거야.",
  ui_story_5035_50351101_70_dialog_content = "결국 나를 못 찾은 제작팀은 어쩔 수 없이 다시 배우를 모집해서 처음부터 다시 찍고 있는 거고.",
  ui_story_5035_50351101_71_dialog_content = "이 일자리가 이런 이유 때문에 생긴 거였구나. 리리카한테 고마워해야겠네.",
  ui_story_5035_50351101_72_dialog_content = "에이~ 그럴 거 없어~",
  ui_story_5035_50351101_73_dialog_content = "아무튼 다시 이야기로 돌아와서. 제작팀의 음모를 알아챈 다음부턴\n나도 가만히 당하고 있지만은 않았어.",
  ui_story_5035_50351101_74_dialog_content = "그래서 제작진이 부린 꾀를 역이용했어.\n제작팀이 날 찾기 위해 기사까지 내줬으니까, 나도 진짜 실종된 것처럼 행동했어.",
  ui_story_5035_50351101_75_dialog_content = "그리고 나 같이 피해를 입는 배우가 더 생기지 않도록, 그 사람들의 음모를 폭로하기로 했지.",
  ui_story_5035_50351101_76_dialog_content = "앗! 그럼 나랑 골디를 구하러 왔단 얘기네!",
  ui_story_5035_50351101_77_dialog_content = "<anim type=Shake><size=45>불운들을</size> 몰고 <size=45>오는</size> <size=50>검은쥐</size>,\n<size=45>불현듯이</size> 알고 <size=45>보니</size> <size=50>구원자</size>♪</anim>",
  ui_story_5035_50351101_78_dialog_content = "후훗~ 당연하지! 그리고 날 속인 저 녀석들에게 본때를 보여 주기 위해서기도 해.",
  ui_story_5035_50351101_79_dialog_content = "단서만 충분히 모으면, 제작팀의 음모를 대중에게 공개할 수 있어.",
  ui_story_5035_50351101_80_dialog_content = "그래서 변장해서 잠입하는 작전을 실행하게 된 거야!",
  ui_story_5035_50351101_81_dialog_content = "「변장해서 잠입」이라고 하기엔 좀...",
  ui_story_5035_50351101_82_dialog_content = "왜! 뭐! 작전은 대성공이었거든!",
  ui_story_5035_50351101_83_dialog_content = "유령이 나온 이 사진이 있으니까, 드디어 내 추측을 뒷받침할 증거를 손에 넣은 거야!",
  ui_story_5035_50351101_84_dialog_content = "그 사람들을 만나서 결판을 낼 거야!\n양심 없는 제작팀에게 철퇴를 내리고, 영화계를 정화하겠어!",
  ui_story_5035_50351101_85_dialog_content = "나랑 함께해 줄래?",
  ui_story_5035_50351101_86_dialog_content = "물론 함께하겠습니다. 제작팀이 사실을 기만한 이상, 우리의 협력 파트너십도 무효입니다.",
  ui_story_5035_50351101_87_dialog_content = "「안데르센 비명의 집」은 이제 더는 저자들을 환영하지 않습니다.",
  ui_story_5035_50351101_88_dialog_content = "녀석들은 담지 필름에 내 고통, 선 넘으면 맞지 팔무릎에 격통!",
  ui_story_5035_50351101_89_dialog_content = "우릴 이렇게 겁준 이상, 절대로 가만두지 않겠어!",
  ui_story_5035_50351101_90_dialog_content = "그래! 그냥 못 넘어가!",
  ui_story_5035_50351101_91_dialog_content = "<color=#e8d9bb>터벅!</color>",
  ui_story_5035_50351101_92_dialog_content = "<color=#e8d9bb>터벅!</color>",
  ui_story_5035_50351101_93_dialog_content = "뭐, 뭐가 어떻게 된 거야?",
  ui_story_5035_50351101_94_dialog_content = "<color=#e8d9bb>터벅!</color>",
  ui_story_5035_50351101_95_dialog_content = "발소리... 엄청 큰 발소리가 들려...",
  ui_story_5035_50351101_96_dialog_content = "이 시간에 이렇게 기운차게 발길질을 하다니... 집을 다 부수려는 건가?",
  ui_story_5035_50351101_97_dialog_content = "<color=#e8d9bb>터벅!</color>",
  ui_story_5035_50351101_98_dialog_content = "어이, 우리 아직도 사람들 놀래키러 나가야 돼?",
  ui_story_5035_50351101_99_dialog_content = "네가 가서 상황 좀 보고 와...",
  ui_story_5035_50351101_100_dialog_content = "캬악!",
  ui_story_5035_50351101_101_dialog_content = "어라? 너, 넌... 진짜 암귀잖아?",
  ui_story_5035_50351101_102_dialog_content = "실례했어...",
  ui_story_5035_50351101_103_dialog_content = "오늘 밤 일어나는 일들은 전부 직원 수칙의 내용이랑 다르잖아.\n돈 벌기 참 힘드네...",
  ui_story_5035_50351101_104_dialog_content = "캬아아악!",
  ui_story_5035_50351101_105_dialog_content = "으헉! 무슨 일이야?!",
  ui_story_5035_50351101_106_dialog_content = "대체 뭐가 오고 있는 거야? 괴물인가?",
  ui_story_5035_50351101_107_dialog_content = "<color=#e8d9bb>퍼억!</color>",
  ui_story_5035_50351101_108_dialog_content = "길 막지 마! 짜증 나는 녀석들!",
  ui_story_5035_50351101_109_dialog_content = "나 지금 완전 화났으니까!",
  ui_story_5035_50351101_110_dialog_content = "엇?! 저기, 선생님? 전...",
  ui_story_5035_50351101_111_dialog_content = "징그러우니까 저리 비켜!",
  ui_story_5035_50351101_112_dialog_content = "으아아아아아!",
  ui_story_5035_50351102_1_dialog_content = "<color=#e8d9bb>딸랑... 딸랑...</color>",
  ui_story_5035_50351102_2_dialog_content = "조금 전 위층이 굉장히 시끄럽지 않았나요?",
  ui_story_5035_50351102_3_dialog_content = "아, 들었어.",
  ui_story_5035_50351102_4_dialog_content = "이 비명의 집에 놀러 온 사람들이겠지. 놀라는 것도 당연해.",
  ui_story_5035_50351102_5_dialog_content = "아, 참 부럽네요. 저도 저렇게 놀고 싶어요.",
  ui_story_5035_50351102_6_dialog_content = "그런 소리 마. 우린 돈을 벌기 위해 아르바이트를 하러 온 거잖아.",
  ui_story_5035_50351102_7_dialog_content = "쓸데없는 생각할 시간 있으면, 감독이 기다리고 있으니까 어서 소품들부터 문 쪽으로 옮겨.",
  ui_story_5035_50351102_8_dialog_content = "<color=#e8d9bb>딸랑... 딸랑...</color>",
  ui_story_5035_50351102_9_dialog_content = "아까 들어 보니까 여기엔 진짜로 유령이 있대요.",
  ui_story_5035_50351102_10_dialog_content = "그렇게 거짓말이라도 해야겠지. 안 그러면 티켓을 팔 수 없을 테니까.",
  ui_story_5035_50351102_11_dialog_content = "그런 소리 마세요. 진짜일 수도 있잖아요.\n지금까지 계속 으스스한 느낌을 받았거든요.",
  ui_story_5035_50351102_12_dialog_content = "꼭... 누가 제 뒤를 따라오고 있는 것처럼요.",
  ui_story_5035_50351102_13_dialog_content = "네 뒤를 따라다닐 정도로 한가한 사람이 있을 리 없잖아.",
  ui_story_5035_50351102_14_dialog_content = "그 얘기 못 들었어요? 제일 처음에 이 저택을 세운 사람은 항상 더러운 게\n자기 목숨을 빼앗으러 올까 봐 두려워했다고 해요.",
  ui_story_5035_50351102_15_dialog_content = "만약 그 더러운 게 사람을 착각하기라도 한다면...",
  ui_story_5035_50351102_16_dialog_content = "너희들!",
  ui_story_5035_50351102_17_dialog_content = "꺄악!",
  ui_story_5035_50351102_18_dialog_content = "이, 이러지 마세요! 저는 아니에요! 정말이에요!",
  ui_story_5035_50351102_19_dialog_content = "거기 서!",
  ui_story_5035_50351102_20_dialog_content = "어라? 살아 있는 사람이잖아?",
  ui_story_5035_50351102_21_dialog_content = "너희 말한 거야! 양심도 없는 제작팀 녀석들!",
  ui_story_5035_50351102_22_dialog_content = "너희가 무슨 음모를 꾸미고 있는지 나한테 다 들켰어!",
  ui_story_5035_50351102_23_dialog_content = "달콤한 말로 배우를 기만하고, 너희의 추악한 욕망을 충족하기 위해\n배우의 목숨을 헌신짝 취급하다니!",
  ui_story_5035_50351102_24_dialog_content = "정말 극... 극...",
  ui_story_5035_50351102_25_dialog_content = "극악무도, 후안무치입니다.",
  ui_story_5035_50351102_26_dialog_content = "아, 그렇지! 극악무도하고! 후안무치해!",
  ui_story_5035_50351102_27_dialog_content = "으이구... 방금 전에 외운 거잖아. 중요한 순간에 잊어버리면 어떡해...",
  ui_story_5035_50351102_28_dialog_content = "미, 미노스 씨 탓이야. 단어가 너무 어려워서 기억하기 힘들다구!",
  ui_story_5035_50351102_29_dialog_content = "「문화적 소양을 돋보일 수 있는 오프닝 대사」를 몇 줄 적어달라고\n하신 건 리리카 양 본인이십니다만.",
  ui_story_5035_50351102_30_dialog_content = "에잇! 됐어! 일단은 신경 안 쓸래!",
  ui_story_5035_50351102_31_dialog_content = "아무튼, 저번에는 잘도 날 그렇게 공포에 떨게 만들더니,\n이제는 새로운 배우한테도 그런 짓을 하려고 해?!",
  ui_story_5035_50351102_32_dialog_content = "난 이 저택에 진짜로 유령이 있단 증거를 충분히 가지고 있어!",
  ui_story_5035_50351102_33_dialog_content = "너희가 이 저택에 돌아왔단 건, 너희가 유령에 대해 알고 있었고,\n그걸 이용하기로 했단 뜻이겠지!",
  ui_story_5035_50351102_34_dialog_content = "이젠 끝이야! 내일이면 너흰 이스타반 클랜의 제재를 받게 될 테니까!",
  ui_story_5035_50351102_35_dialog_content = "그 전에 내 주먹을 받아!",
  ui_story_5035_50351102_36_dialog_content = "피해자의 분노를 맛보라구!",
  ui_story_5035_50351102_37_dialog_content = "제재?! 주먹?! 큰일 났네, 큰일 났어!",
  ui_story_5035_50351102_38_dialog_content = "흥, 이제 와서 후회해도 늦었어!",
  ui_story_5035_50351102_39_dialog_content = "싫어어어어어!",
  ui_story_5035_50351102_40_dialog_content = "음, 그 전에 먼저 질문부터 하고 싶군.",
  ui_story_5035_50351102_41_dialog_content = "당신은 누구지?",
  ui_story_5035_50351102_42_dialog_content = "뭐어? 날 모른다고? 우리 저번에 같이 영화...",
  ui_story_5035_50351102_43_dialog_content = "어라? 잠깐만.",
  ui_story_5035_50351102_44_dialog_content = "너...",
  ui_story_5035_50351102_45_dialog_content = "누구?",
  ui_story_5035_50351102_X45_dialog_content = "앗...!",
  ui_story_5035_50351102_X46_dialog_content = "아는 사이야?",
  ui_story_5035_50351102_X47_dialog_content = "레스터랑 콘스탄틴 씨잖아!",
  ui_story_5035_50351102_X48_dialog_content = "어! PlayerName 님도 여기 오신 건가요?",
  ui_story_5035_50351102_X49_dialog_content = "안데르센 비명의 집은 인기가 정말 많군.",
  ui_story_5035_50351102_X50_dialog_content = "두 사람이 영화 스태프일 리가 없잖아? 리리카가 잘못 안 거 아냐?",
  ui_story_5035_50351102_46_dialog_content = "에에엥?",
  ui_story_5035_50351102_47_dialog_content = "그건 내가 묻고 싶은 말이야.\n다짜고짜 욕설을 퍼부었지만 정작 모르는 사이 같은데?",
  ui_story_5035_50351102_48_dialog_content = "이게 무슨 상황이야? 다들 전에 같이 영화 촬영했던 거 아니었어?",
  ui_story_5035_50351102_49_dialog_content = "미안해, 정말 미안해! 난 두 사람이 제작 스태프인 줄 알았어.\n근데 내가 사람을 잘못 봤나 봐!",
  ui_story_5035_50351102_50_dialog_content = "정말 너무 미안해!",
  ui_story_5035_50351102_51_dialog_content = "아니, 저기요. 저희 제작 스태프 맞아요! 아직 안 짤렸거든요?",
  ui_story_5035_50351102_52_dialog_content = "우린 소품을 옮기던 중이었다. 이런 쓸모없는 짓을 하는 건 스태프밖에 없지.",
  ui_story_5035_50351102_53_dialog_content = "소품이요?",
  ui_story_5035_50351102_54_dialog_content = "<color=#e8d9bb>딸랑... 딸랑...</color>",
  ui_story_5035_50351102_55_dialog_content = "앗, 방울이 달린... 관이네요?",
  ui_story_5035_50351102_56_dialog_content = "맞아요. 공포 영화는 이게 문제죠. 뭐든지 다 으스스해요. 불길함이 느껴질 정도라고요.",
  ui_story_5035_50351102_57_dialog_content = "레스터는 스크립터를, 나는 촬영 기사를 맡고 있다.",
  ui_story_5035_50351102_58_dialog_content = "우린 제작 스태프인데, 우리가 그쪽이랑 모르는 사이인 게 문제가 되는 건가?",
  ui_story_5035_50351102_59_dialog_content = "어라? 하지만 저번에 스크립터랑 촬영 기사를 맡았던 건...",
  ui_story_5035_50351102_60_dialog_content = "어째서... 왜 바꾼 거지?",
  ui_story_5035_50351102_61_dialog_content = "저희는 확실히 얼마 전에야 이 일을 하기 시작했어요.\n그래도 아마추어라고 얕보진 말아요...",
  ui_story_5035_50351102_62_dialog_content = "아차!",
  ui_story_5035_50351102_63_dialog_content = "왜, 왜 그래?",
  ui_story_5035_50351102_64_dialog_content = "제작 스태프가 변경됐다면, 전에 일하던 스태프들은 어디 갔습니까?",
  ui_story_5035_50351102_65_dialog_content = "음...",
  ui_story_5035_50351102_66_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5035_50351102_67_dialog_content = "!!!",
  ui_story_5035_50351102_68_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5035_50351102_69_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5035_50351102_70_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_5035_50351102_71_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5035_50351102_72_dialog_content = "무슨 소리지...? 대체 무슨 일이 일어나고 있는 거야...?",
  ui_story_5035_50351102_73_dialog_content = "문이 닫히면서 나는 소리야. 이 주변 방문들은 다 닫혔어.",
  ui_story_5035_50351102_74_dialog_content = "누가 우릴 가두려고 하는 모양이야.",
  ui_story_5035_50351102_75_dialog_content = "대체 누가 이런 짓을...",
  ui_story_5035_50351102_76_dialog_content = "리리카, 리리카.",
  ui_story_5035_50351102_77_dialog_content = "변변치 못한 나의 「여주인공」.",
  ui_story_5035_50351102_78_dialog_content = "드디어 찾았구나.",
  ui_story_5035_50351102_79_dialog_content = "(음산한 목소리와 함께, 조니 감독의 모습이 점차 뚜렷해졌다.)",
  ui_story_5035_50351102_80_dialog_content = "(조니 감독은 1층 계단 난간 옆에 서서, 천장을 사이에 둔 채로 우리를 마주 봤다.)",
  ui_story_5035_50351102_81_dialog_content = "(한 층이라는 높이 차이는 조니 감독의 시선을 더 무겁게 만들었고,\n위에서 우릴 짓누르는 듯한 압박감을 선사했다.)",
  ui_story_5035_50351102_82_dialog_content = "(이가 부딪히는 소리 이외엔, 주변의 공기까지 그 압박감 때문에 굳어 버렸다.)",
  ui_story_5035_50351102_83_dialog_content = "조. 니. 감. 독.",
  ui_story_5035_50351102_84_dialog_content = "솔직히 말하면, 네 연기는 나쁘지 않았어.",
  ui_story_5035_50351102_85_dialog_content = "저번에 너랑 같이 찍었던 것들, 난 마음에 들었어.\n내가 예전에 찍었던 그 어떤 작품보다도 좋았지.",
  ui_story_5035_50351102_86_dialog_content = "하지만 넌 배우로서 미완성이었어. 아쉽게도 배우로서의 기본 소양이 부족했지.",
  ui_story_5035_50351102_87_dialog_content = "넌 영화란 건 <color=#FFB400>끝까지</color> 촬영해야 한단 걸 몰랐지.",
  ui_story_5035_50351102_88_dialog_content = "그래서 그 영화를 완성하려고 여기저기 날 찾아 다닌 거야?",
  ui_story_5035_50351102_89_dialog_content = "이젠 아니야.",
  ui_story_5035_50351102_90_dialog_content = "네가 도망쳤을 때부터, 그 영화는 시한부 판정을 받은 거거든.",
  ui_story_5035_50351102_91_dialog_content = "그 영화는 이제 뭘 덧입혀도 비디오 대여점 선반 위에 놓인\n그저 그런 작품밖엔 될 수 없어. 난 그 꼴은 못 본다고.",
  ui_story_5035_50351102_92_dialog_content = "내가 널 찾은 건 다른 이유 때문이야.",
  ui_story_5035_50351102_93_dialog_content = "알고 싶었거든. 네 눈이 어둠 속에서 무엇을 얼마나 봤는지.",
  ui_story_5035_50351102_94_dialog_content = "너무 많은 걸 봐 버린 사람들에겐 입을 열 기회를 주면 안 되거든.",
  ui_story_5035_50351102_95_dialog_content = "입을 열 기회를 주면 안 돼? 그게 대체 무슨 소리야...?",
  ui_story_5035_50351102_96_dialog_content = "감독님! 조니 감독님!",
  ui_story_5035_50351102_97_dialog_content = "여기 계셨네요. 한참 찾았어요.",
  ui_story_5035_50351102_98_dialog_content = "제가 시나리오를 좀 봤는데요, 여기 이 부분 대사를 감독님이랑 좀 상의하고 싶어서요.",
  ui_story_5035_50351102_99_dialog_content = "어느 부분이지? 한번 볼까.",
  ui_story_5035_50351102_100_dialog_content = "여기요...",
  ui_story_5035_50351102_101_dialog_content = "큰일이야! 골디는 아무것도 모르고 있어!",
  ui_story_5035_50351102_102_dialog_content = "골디! 그 남자한테 가면 안 돼!",
  ui_story_5035_50351102_103_dialog_content = "네? 그게 무슨...",
  ui_story_5035_50351102_104_dialog_content = "쉿!",
  ui_story_5035_50351102_105_dialog_content = "네 촬영은 여기까지야.",
  ui_story_5035_50351102_106_dialog_content = "골디가...",
  ui_story_5035_50351102_107_dialog_content = "꺄아아악──!",
  ui_story_5035_50351201_1_dialog_content = "저, 저 사람이... 골디를 죽인 거야?",
  ui_story_5035_50351201_2_dialog_content = "......",
  ui_story_5035_50351201_3_dialog_content = "역시 그랬군요.",
  ui_story_5035_50351201_4_dialog_content = "지금 저 남자에게 사람 한 명 더 죽이는 건 문제가 전혀 아닌 겁니다.",
  ui_story_5035_50351201_5_dialog_content = "저번 영화의 제작진도 모두 당신이 처리해 버렸겠군요, 조니.",
  ui_story_5035_50351201_6_dialog_content = "모두라니...",
  ui_story_5035_50351201_7_dialog_content = "그것참 재미있군, 프로듀서, 왜 그런 말을 하는 거지?",
  ui_story_5035_50351201_8_dialog_content = "리리카는 제작팀 전원이 음모의 주모자일 거라고 여겼지만 그게 아니었던 겁니다.",
  ui_story_5035_50351201_9_dialog_content = "이건 처음부터 끝까지 다 당신 한 사람이 꾸민 음모였습니다.",
  ui_story_5035_50351201_10_dialog_content = "제작팀의 서류에는 그 어떤 촬영 현장 사진도 남아 있지 않았지요.",
  ui_story_5035_50351201_11_dialog_content = "처음에는 그저 당신이 「유령」의 존재를 숨기기 위해서 그런 짓을 했다고 생각했습니다.",
  ui_story_5035_50351201_12_dialog_content = "근데 지금 보니 당신이 은폐하려던 건 유령이 아니더군요.",
  ui_story_5035_50351201_13_dialog_content = "숨기려던 건 촬영 사진 속에 담겨 있던, '살아 있는' 스태프들의 존재였습니다.",
  ui_story_5035_50351201_14_dialog_content = "스태프들의 인원 변동 사항은 수정할 수 있지만, 사진은 반박할 수 없는 증거니 말입니다.",
  ui_story_5035_50351201_15_dialog_content = "그 사진들이라면 이 영화의 스태프들이 비정상적으로\n대규모 물갈이됐다는 사실을 증명할 수 있겠죠.",
  ui_story_5035_50351201_16_dialog_content = "그리고 당신이 그들을 모두 살해했다는 사실을 만천하에 드러낼 겁니다.",
  ui_story_5035_50351201_17_dialog_content = "쳇, 역시 당신과 협업하기로 한 건 옳은 선택이었어. 관찰력이 대단하군, 프로듀서.",
  ui_story_5035_50351201_18_dialog_content = "그 부분을 발견해 준 덕분에 지금부터 내가 할 얘기가 그렇게 따분하지만은 않겠어.",
  ui_story_5035_50351201_19_dialog_content = "맞아. 저번 영화의 스태프들은 다 목숨을 잃었지.\n남은 거라곤 지금 거기 서 있는 녀석뿐이야. 남들과 어울리지 못하고 겉돌던 「여주인공」.",
  ui_story_5035_50351201_20_dialog_content = "네가 얼마나 큰 잘못을 저질렀는지 알기나 해?\n원래라면 그들의 죽음은 더할 나위 없이 훌륭한 영화 작품이 되었을 거다.",
  ui_story_5035_50351201_21_dialog_content = "근데 네가 도망쳐 버린 바람에, 필름은 물론이고 수많은 목숨이 낭비되어 버렸지.",
  ui_story_5035_50351201_22_dialog_content = "다... 당신...",
  ui_story_5035_50351201_23_dialog_content = "비열하게 사람의 목숨을 가지고 궤변을 늘어놓지 마십시오.",
  ui_story_5035_50351201_24_dialog_content = "왜 모두를 죽였어...?",
  ui_story_5035_50351201_25_dialog_content = "왜 골디를 죽이고... 모든 스태프를 죽인 거야...?",
  ui_story_5035_50351201_26_dialog_content = "왜 그랬어! 왜!",
  ui_story_5035_50351201_27_dialog_content = "말했잖아, 너무 많은 걸 봐 버린 사람들에겐 입을 열 기회를 주면 안 된다고.",
  ui_story_5035_50351201_28_dialog_content = "난 언제나 스크린은 참 신비롭다고 생각해 왔다.",
  ui_story_5035_50351201_29_dialog_content = "스크린 너머라면, 관객들은 자기가 본 모든 걸 합리화하고 일상을 예술로 승화시킬 수 있거든.",
  ui_story_5035_50351201_30_dialog_content = "우리 같은 창작자에게, 스크린이란 최고의 보호 장치인 거다.",
  ui_story_5035_50351201_31_dialog_content = "그래서 난 그 보호막을 지키기 위해,\n무대 뒤의 그 어떤 「비밀」도 무대 앞에 누설되게 만들지 않을 거다.",
  ui_story_5035_50351201_32_dialog_content = "비밀? 네가 여기에 유령이 나오는 걸 뻔히 알면서도 영화를 촬영하러 온 것처럼 말이야?",
  ui_story_5035_50351201_33_dialog_content = "아, 그렇게 추측한 거냐.",
  ui_story_5035_50351201_34_dialog_content = "나쁘지 않아. 진상에 꽤 가까웠어. 다만, 가장 기본적인 논리를 착각하고 있군.",
  ui_story_5035_50351201_35_dialog_content = "난 여기에 유령이 나와서 촬영을 하러 온 게 아니야.",
  ui_story_5035_50351201_36_dialog_content = "내가 여기 왔기 때문에, 여기에 유령이 나오는 거지.",
  ui_story_5035_50351201_37_dialog_content = "!!!",
  ui_story_5035_50351201_38_dialog_content = "뭐?! 그게 대체 무슨...",
  ui_story_5035_50351201_39_dialog_content = "오직 나만이 이 저택의 진정한 가치를 선보일 수 있다.",
  ui_story_5035_50351201_40_dialog_content = "나보다 이 저택에 대해 잘 아는 사람은 없고,\n나보다 <color=#FFB400>그녀</color>를 잘 아는 사람도 없거든.",
  ui_story_5035_50351201_41_dialog_content = "어렸을 때, 내 부모님은 조상님이 남긴 그 이상한 지도에 호기심을 갖지 말라고 하셨지.",
  ui_story_5035_50351201_42_dialog_content = "그렇지만 이 저택과 그녀의 존재는 정말 너무나도 매력적이었다.",
  ui_story_5035_50351201_43_dialog_content = "조상님이 지금까지 살아 있었다면 분명 내 작품을 보고 전율을 느꼈을 거다.",
  ui_story_5035_50351201_44_dialog_content = "조상님이 과거에 모셨던 에스더 부인, 그녀의 「영체」는\n백 년이 지난 지금에도 계속 이곳을 맴돌고 있다.",
  ui_story_5035_50351201_45_dialog_content = "난 흐릿해진 그녀의 지각을 일깨워 줬고, 그녀는 죽어버린 내 영감을 되살려 줬지.",
  ui_story_5035_50351201_46_dialog_content = "그래. 우린 서로에게 새 삶을 준 거다.",
  ui_story_5035_50351201_47_dialog_content = "너와 그 두 스태프는 내 첫 실험작에 지나지 않아.",
  ui_story_5035_50351201_48_dialog_content = "왜냐면 나와 <color=#FFB400>그녀</color>는 아주 오랫동안 만나지 못했거든.",
  ui_story_5035_50351201_49_dialog_content = "이 자식...!",
  ui_story_5035_50351201_50_dialog_content = "그녀는 정말 최고야. 처음으로 모습을 드러냈을 때부터 내 예상을 뛰어넘었었지.",
  ui_story_5035_50351201_51_dialog_content = "네가 덜렁대다가 마스터 테이프를 망가트리지만 않았으면 좋았을 텐데 말이야.\n그건 정말 움브라톤 전역을 뒤흔들만한 귀한 영상이었거든.",
  ui_story_5035_50351201_52_dialog_content = "고작 그런 이유 때문에... 죄 없는 피해자들의 목숨을 빼앗았다는 거야?",
  ui_story_5035_50351201_53_dialog_content = "지금까지 계속 영화를 찍고, 공포 영화를 만든 것도...\n다 그 유령 여인이랑 같이 일하게 될 오늘을 위해서였어?",
  ui_story_5035_50351201_54_dialog_content = "내가 만든 조잡한 작품들을 좋아해 줘서 고맙군.",
  ui_story_5035_50351201_55_dialog_content = "그쪽이 공포 영화 마니아라면 잘 알겠지.\n공포 영화에서는 주인공보다는 악역을 어떻게 묘사하느냐가 훨씬 더 중요하다는걸.",
  ui_story_5035_50351201_56_dialog_content = "배우는 몇 명이라도 바꿀 수 있지만, <color=#FFB400>그녀</color>는 대체 불가능한 존재다.",
  ui_story_5035_50351201_57_dialog_content = "나의 진정한 「여주인공」은 오직 <color=#FFB400>그녀</color>뿐이니까.",
  ui_story_5035_50351201_58_dialog_content = "그, 그럼... 계속 유령 여인을 데리고 영화를 찍으러 다녔다는 거야?!",
  ui_story_5035_50351201_59_dialog_content = "뭐 그런 소름 끼치는 일이 다 있어?!",
  ui_story_5035_50351201_60_dialog_content = "더 소름 돋는 사실이 있습니다.",
  ui_story_5035_50351201_61_dialog_content = "같은 방식으로 영화를 여러 편이나 찍었다면...",
  ui_story_5035_50351201_62_dialog_content = "당신 손에 당한 제작팀도 하나뿐이 아니겠죠, 조니.",
  ui_story_5035_50351201_63_dialog_content = "그래! 설마 다른 제작팀들도...",
  ui_story_5035_50351201_64_dialog_content = "쯧쯧, 프로듀서, 내가 당신이었다면 그 질문은 안 했어.",
  ui_story_5035_50351201_65_dialog_content = "나였다면 내게 눈과 귀가 없길, 내가 아는 건 빙산의 일각뿐이길 빌었을 거다.",
  ui_story_5035_50351201_66_dialog_content = "답을 얻는다는 게 무슨 의미인지, 당신은 잘 알잖아?",
  ui_story_5035_50351201_67_dialog_content = "......",
  ui_story_5035_50351201_68_dialog_content = "허세 부리지 마십시오. 당신이 모습을 드러냈을 때부터 답은 나와 있었습니다.",
  ui_story_5035_50351201_69_dialog_content = "우리도 저번 스태프들처럼 비밀을 너무 알아 버렸습니다.",
  ui_story_5035_50351201_70_dialog_content = "당신이 문을 잠가 버린 것도 그래서겠죠.",
  ui_story_5035_50351201_71_dialog_content = "당신은 이 비명의 집에서 단 한 명도 돌려보낼 생각이 없지 않습니까.",
  ui_story_5035_50351201_72_dialog_content = "프로듀서, 그렇게 적개심을 보일 필요는 없어.",
  ui_story_5035_50351201_73_dialog_content = "우린 비밀을 공유한 사이잖아. 아닌가?",
  ui_story_5035_50351201_74_dialog_content = "네가 원하든, 원하지 않든 우린 같은 배를 탔어.",
  ui_story_5035_50351201_75_dialog_content = "그럼 환영 인사를 해 보도록 하지.",
  ui_story_5035_50351201_76_dialog_content = "모두 내 영화의 <color=#FFB400>제작팀</color>이 된 걸 환영한다.",
  ui_story_5035_50351201_77_dialog_content = "<color=#e8d9bb>또옥...</color>",
  ui_story_5035_50351201_78_dialog_content = "!!!",
  ui_story_5035_50351201_79_dialog_content = "다들 들었어?! 물방울이 떨어지는 소리야!",
  ui_story_5035_50351201_80_dialog_content = "<color=#e8d9bb>또옥...</color>",
  ui_story_5035_50351201_81_dialog_content = "저, 점점 가까워지고 있어.",
  ui_story_5035_50351201_82_dialog_content = "대체 이 소리는 왜 나는 거야?!",
  ui_story_5035_50351201_83_dialog_content = "아! 카메라!",
  ui_story_5035_50351201_84_dialog_content = "리리카! 빨리 카메라 들어 봐!",
  ui_story_5035_50351201_85_dialog_content = "응?",
  ui_story_5035_50351201_86_dialog_content = "정면을 촬영해! 빨리!",
  ui_story_5035_50351201_87_dialog_content = "응, 알았어.",
  ui_story_5035_50351201_88_dialog_content = "전원을 켜고... 앞쪽을 향해서...",
  ui_story_5035_50351201_89_dialog_content = "!!!",
  ui_story_5035_50351201_90_dialog_content = "이... 이거 좀 봐! 빨리!",
  ui_story_5035_50351201_91_dialog_content = "이건...",
  ui_story_5035_50351201_92_dialog_content = "꺄야악!",
  ui_story_5035_50351201_93_dialog_content = "왜 그래? 뭐가 보였는데?",
  ui_story_5035_50351201_94_dialog_content = "왔어! 그 여자가 왔다고!",
  ui_story_5035_50351201_95_dialog_content = "어떻게 이런 일이... 으으... 머릿속이 뒤죽박죽이야...",
  ui_story_5035_50351201_96_dialog_content = "저 여자가 우릴 죽일까...?",
  ui_story_5035_50351201_97_dialog_content = "멍하니 있으면 안 돼! 빨리 도망쳐!",
  ui_story_5035_50351201_98_dialog_content = "도망... 아! 그래! 일단 도망쳐!",
  ui_story_5035_50351201_99_dialog_content = "바짝 따라오십시오! 위층으로 올라가겠습니다!",
  ui_story_5035_50351201_100_dialog_content = "<color=#e8d9bb>타닥, 타닥, 타닥...</color>",
  ui_story_5035_50351201_101_dialog_content = "도망쳐, 열심히 도망쳐 봐. 어차피 그쪽은 출구가 아냐.",
  ui_story_5035_50351201_102_dialog_content = "이 저택에서 빠져나가지도 못하는데, 대체 어디로 도망치겠다는 거지?",
  ui_story_5035_50351201_103_dialog_content = "<color=#e8d9bb>우르르!</color>",
  ui_story_5035_50351201_104_dialog_content = "캬악──!",
  ui_story_5035_50351201_105_dialog_content = "캬오──!",
  ui_story_5035_50351201_106_dialog_content = "또 어디서 암귀가 잔뜩 나타난 거야?! 하필이면 이럴 때!",
  ui_story_5035_50351201_107_dialog_content = "이 저택에 몸을 숨기고 있던 암귀들이 다 깨어난 것 같아. 조니가 꾸민 짓일지도 모르겠어.",
  ui_story_5035_50351201_108_dialog_content = "이 저택 안에 있던 모든 암귀들이라고 해도...",
  ui_story_5035_50351201_109_dialog_content = "저택 안에 있던 암귀라고 보기엔 너무 많지 않아?",
  ui_story_5035_50351201_110_dialog_content = "평소에는 이렇지 않았습니다.",
  ui_story_5035_50351201_111_dialog_content = "저도 PlayerName 님의 추측에 동의합니다.\n암귀가 나타나게 된 건 조니와 관계가 있을 겁니다.",
  ui_story_5035_50351201_112_dialog_content = "제작팀 모두를 없애려면 유령 여인보다는 지금처럼 암귀를 동원하는 편이 좋을 테니까요.",
  ui_story_5035_50351201_113_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5035_50351201_114_dialog_content = "일부러 녀석들을 상대할 필요는 없습니다. 모퉁이를 돌아 이동하십시오!",
  ui_story_5035_50351201_115_dialog_content = "휴우... 대체 언제까지 도망쳐야 하는 거야?",
  ui_story_5035_50351201_116_dialog_content = "적어도 추격해 오는 암귀들을 따돌릴 때까지는 계속 도망쳐야 합니다.",
  ui_story_5035_50351201_117_dialog_content = "잠깐만! 다들 잠깐만! 앞에 좀 봐!",
  ui_story_5035_50351201_118_dialog_content = "앞은 왜?",
  ui_story_5035_50351201_119_dialog_content = "확실하진 않은데, 복도 끝에 여자애 두 명이 서 있는 것 같아!",
  ui_story_5035_50351201_120_dialog_content = "여자애들? 누가...",
  ui_story_5035_50351201_121_dialog_content = "퍼피, 퍼피.",
  ui_story_5035_50351201_122_dialog_content = "찾았어.",
  ui_story_5035_50351201_123_dialog_content = "퍼피? 우리 중엔... 퍼피라는 사람은 없는데?",
  ui_story_5035_50351201_124_dialog_content = "설마 저 애들이 말하는 건...",
  ui_story_5035_50351201_125_dialog_content = "빨리 와, 빨리 우리한테 와.",
  ui_story_5035_50351201_126_dialog_content = "우리 같이 놀자, 퍼피.",
  ui_story_5035_50351201_127_dialog_content = "열까지 세기 전에 결승점까지 달려오면 네가 이긴 거야.",
  ui_story_5035_50351201_128_dialog_content = "자, 퍼피, 결승점까지 달려!",
  ui_story_5035_50351201_129_dialog_content = "우, 우리 다른 길로 가자! 이 앞으로 더 가면 안 돼...",
  ui_story_5035_50351201_130_dialog_content = "암귀가 바짝 뒤쫓아 왔어! 빨리 앞을 향해 뛰어!",
  ui_story_5035_50351201_131_dialog_content = "그치만 앞엔...",
  ui_story_5035_50351201_132_dialog_content = "그래, 바로 그거야, 퍼피.",
  ui_story_5035_50351201_133_dialog_content = "이제 딱 절반 셌어, 더 빨리 움직여야 해!",
  ui_story_5035_50351201_134_dialog_content = "너네가 왜 여기 있는 거야?! 파티! 파시!",
  ui_story_5035_50351201_135_dialog_content = "난 유령의 집을 좋아해.",
  ui_story_5035_50351201_136_dialog_content = "나도 좋아해!",
  ui_story_5035_50351201_137_dialog_content = "그래서 둘이 구경하러 왔지.",
  ui_story_5035_50351201_138_dialog_content = "그래, 근데 지금은 너희랑 놀아 줄 시간이 없어.",
  ui_story_5035_50351201_139_dialog_content = "내 손 잡아!",
  ui_story_5035_50351201_140_dialog_content = "난 왼손 잡을래.",
  ui_story_5035_50351201_141_dialog_content = "그럼 난 오른손.",
  ui_story_5035_50351201_142_dialog_content = "빨리 뛰어!",
  ui_story_5035_50351302_1_dialog_content = "캬악──!",
  ui_story_5035_50351302_2_dialog_content = "이야압!",
  ui_story_5035_50351302_3_dialog_content = "<color=#e8d9bb>퍽! 퍽! 퍽!</color>",
  ui_story_5035_50351302_4_dialog_content = "흥, 약해.",
  ui_story_5035_50351302_5_dialog_content = "날 그저 배우로 안 니들 꼬라지 Error,\n나 의적 새디 어디서 꿀리진 않어♩",
  ui_story_5035_50351302_6_dialog_content = "진짜 잘했어, 새디! 뒤를 쫓아 오던 암귀들은 우리가 전부 쓰러트렸어!",
  ui_story_5035_50351302_7_dialog_content = "그럼 이제... 어라?",
  ui_story_5035_50351302_8_dialog_content = "다른 사람들은?",
  ui_story_5035_50351302_9_dialog_content = "하아?",
  ui_story_5035_50351302_10_dialog_content = "난 계속 널 따라온 건데? 너도 앞에서 가는 사람 따라 움직인 거 아니었어?",
  ui_story_5035_50351302_11_dialog_content = "나, 난 계속 널 따라온 거라구!",
  ui_story_5035_50351302_12_dialog_content = "......",
  ui_story_5035_50351302_13_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5035_50351302_14_dialog_content = "엄청 조용하네~",
  ui_story_5035_50351302_15_dialog_content = "쉿, 조용히 해.",
  ui_story_5035_50351302_16_dialog_content = "조용할수록 우리 목소리가 잘 들릴 테니까.",
  ui_story_5035_50351302_17_dialog_content = "여기라면 안전할 수도 있잖아?",
  ui_story_5035_50351302_18_dialog_content = "암귀는 없어. 그리고 유령 여인이 나타날 때 들리는 물방울 떨어지는 소리도 안 들리구.",
  ui_story_5035_50351302_19_dialog_content = "혹시 모르지. 이 앞에 있는 모퉁이를 돌면 뭔가가 우릴 기다리고 있을지도 몰라.",
  ui_story_5035_50351302_20_dialog_content = "내 배짱은 엄청나거든~ 그러니까 나 겁주지 마.",
  ui_story_5035_50351302_21_dialog_content = "근데 새디 네 말대로면... 차라리 여기저기 막 돌아다니지 않는 편이 좋지 않을까?",
  ui_story_5035_50351302_22_dialog_content = "혹시 마주칠 수도 있잖아? 엄청나게 많은 적이라든가, 아니면...",
  ui_story_5035_50351302_23_dialog_content = "만약 그런 일이 일어나면 우리 둘만으론 당해낼 수 없을 거야.",
  ui_story_5035_50351302_24_dialog_content = "...음, 네 말이 맞아.",
  ui_story_5035_50351302_25_dialog_content = "방을 하나 찾아서 그 안에 숨어 있자.",
  ui_story_5035_50351302_26_dialog_content = "이거 봐! 옆에 있는 이 문은 열릴 것 같아!",
  ui_story_5035_50351302_27_dialog_content = "쉿! 큰 소리 나지 않게, 살살...",
  ui_story_5035_50351302_28_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_5035_50351302_29_dialog_content = "문 잠글 수 있어?",
  ui_story_5035_50351302_30_dialog_content = "확인해 볼게... 잠글 수 있는 것 같아!",
  ui_story_5035_50351302_31_dialog_content = "그럼 빨리 잠가.",
  ui_story_5035_50351302_32_dialog_content = "응.",
  ui_story_5035_50351302_33_dialog_content = "<color=#e8d9bb>철컥</color>",
  ui_story_5035_50351302_34_dialog_content = "휴... 문 잠갔어.",
  ui_story_5035_50351302_35_dialog_content = "후우...",
  ui_story_5035_50351302_36_dialog_content = "으, 진짜 긴장돼 죽는 줄 알았네. 이젠 숨 좀 돌릴 수 있겠어.",
  ui_story_5035_50351302_37_dialog_content = "여기서 좀 쉬다가 다른 사람들 소리가 들리면 가서 합류하자.",
  ui_story_5035_50351302_38_dialog_content = "응, 좋아. 잠깐 쉬자.",
  ui_story_5035_50351302_39_dialog_content = "근데...",
  ui_story_5035_50351302_40_dialog_content = "이 방, 어디서 봤던 것 같지 않아?",
  ui_story_5035_50351302_41_dialog_content = "응?",
  ui_story_5035_50351302_42_dialog_content = "정말 못 살아! 아까 왔던 전시실이잖아!",
  ui_story_5035_50351302_43_dialog_content = "어쩌다가 여기로 돌아와 버린 거지...",
  ui_story_5035_50351302_44_dialog_content = "내 기억이 맞으면, 처음에 물방울 떨어지는 소리가 들렸던 것도 바로 전시실이었어.",
  ui_story_5035_50351302_45_dialog_content = "그, 그런 소리 하지 마. 자꾸 그러면 어떻게 쉬어...",
  ui_story_5035_50351302_46_dialog_content = "잠깐이라도 다른 데 주의력을 쏟을 수 있게 다른 생각 좀 해 봐.",
  ui_story_5035_50351302_47_dialog_content = "참! 기념 영상 하나 찍자!",
  ui_story_5035_50351302_48_dialog_content = "지금? 넌 정말 타이밍이랑 안 맞는 일을 하는 덴 선수구나.",
  ui_story_5035_50351302_49_dialog_content = "타이밍이랑 안 맞을 게 뭐 있어!\n카메라는 원래부터 여러 순간을 기록하기 위해 만들어진 물건이라구.",
  ui_story_5035_50351302_50_dialog_content = "기쁜 순간도, 무서운 순간도 다 기념해 둘 가치가 있는 거야.",
  ui_story_5035_50351302_51_dialog_content = "게다가 카메라는 유령 여인의 흔적을 촬영할 수 있으니까,\n아무것도 안 보이는 것보단 훨씬 안심되기도 하구.",
  ui_story_5035_50351302_52_dialog_content = "확실히 그렇긴 하네...",
  ui_story_5035_50351302_53_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5035_50351302_54_dialog_content = "으앗!",
  ui_story_5035_50351302_55_dialog_content = "무슨 소리야?!",
  ui_story_5035_50351302_56_dialog_content = "문을 봐! 방문이...",
  ui_story_5035_50351302_57_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5035_50351302_58_dialog_content = "방문이 갈라졌어!",
  ui_story_5035_50351302_59_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5035_50351302_60_dialog_content = "거기 누구야?!",
  ui_story_5035_50351302_61_dialog_content = "리리카, 새디? 하하하, 이거 풍작이네.",
  ui_story_5035_50351302_62_dialog_content = "자, 나의 여배우들, 영화 촬영을 시작해야지.",
  ui_story_5035_50351302_63_dialog_content = "조니 감독?!",
  ui_story_5035_50351302_64_dialog_content = "이, 이쪽으로 오지 마! 겨, 경고했어!",
  ui_story_5035_50351302_65_dialog_content = "경고? 아주 당당하군, 새디.",
  ui_story_5035_50351302_66_dialog_content = "네 덕분에 더 궁금해져 버렸어.",
  ui_story_5035_50351302_67_dialog_content = "내가 진짜 그쪽으로 가면, 날 어떻게 할 거지?",
  ui_story_5035_50351302_68_dialog_content = "어떻게 할 거냐고!",
  ui_story_5035_50351302_69_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5035_50351302_70_dialog_content = "으악!",
  ui_story_5035_50351302_71_dialog_content = "조니! 네가 저지른 범죄는 내가 다 녹화해 뒀어!",
  ui_story_5035_50351302_72_dialog_content = "이 테이프가 유출되면 어떤 상황이 펼쳐질진 너도 잘 알지? 당장 그 손 치워!",
  ui_story_5035_50351302_73_dialog_content = "녹화해 뒀다고?",
  ui_story_5035_50351302_74_dialog_content = "최고군, 정말 최고야. 리리카, 넌 재능이 있어. 눈썰미가 아주 좋아.",
  ui_story_5035_50351302_75_dialog_content = "그 녹화 테이프들은 당연히 외부에 유출되면 안 되지.\n편집해서 내 영화에 사용해야 하니까.",
  ui_story_5035_50351302_76_dialog_content = "그 테이프들이 있으면 이 영화는 더 완벽해질 거야.",
  ui_story_5035_50351302_77_dialog_content = "미쳤어...",
  ui_story_5035_50351302_78_dialog_content = "게다가...",
  ui_story_5035_50351302_79_dialog_content = "영화가 진짜일 거라고 믿는 사람이 어디 있어?",
  ui_story_5035_50351302_80_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5035_50351302_81_dialog_content = "으악!",
  ui_story_5035_50351302_82_dialog_content = "꺄악!",
  ui_story_5035_50351302_83_dialog_content = "그래! 바로 그거야! 계속해!",
  ui_story_5035_50351302_84_dialog_content = "비명을 멈추면 안 돼!",
  ui_story_5035_50351302_85_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5035_50351302_86_dialog_content = "꺄악!",
  ui_story_5035_50351302_87_dialog_content = "이제 한 번만 더 내려치면 이 문도 끝이야.",
  ui_story_5035_50351302_88_dialog_content = "하하하, 하하하하...",
  ui_story_5035_50351302_89_dialog_content = "으아아악──!",
  ui_story_5035_50351302_90_dialog_content = "?!",
  ui_story_5035_50351302_91_dialog_content = "으음?",
  ui_story_5035_50351302_92_dialog_content = "아, 저쪽에서 나는 소리군.",
  ui_story_5035_50351302_93_dialog_content = "시작이다. 시작이라고!",
  ui_story_5035_50351302_94_dialog_content = "이러면 안 되지. 카메라를 아직 안 켰잖아.",
  ui_story_5035_50351302_95_dialog_content = "안 돼, 이러면 안 돼. 단 한 장면도 놓칠 순 없어. 절대로...",
  ui_story_5035_50351302_96_dialog_content = "허억.... 허억...",
  ui_story_5035_50351302_97_dialog_content = "휴우... 헉...",
  ui_story_5035_50351302_98_dialog_content = "가, 갔어?",
  ui_story_5035_50351302_99_dialog_content = "그, 그런 것 같아.",
  ui_story_5035_50351302_100_dialog_content = "어떻게 된 건지는 잘 모르겠지만... 아까 그 소리 들었어?",
  ui_story_5035_50351302_101_dialog_content = "응, 나도 그 생각 중이었어. 거리가 좀 있긴 했지만, 아마 아래층에서 들려왔을 거야.",
  ui_story_5035_50351302_102_dialog_content = "게다가... 어디서 들어 본 목소리 같지 않았어?",
  ui_story_5035_50351302_103_dialog_content = "맞아, PlayerName 목소리 같았어.",
  ui_story_5035_50351401_1_dialog_content = "<color=#e8d9bb>3분 전</color>",
  ui_story_5035_50351401_2_dialog_content = "휴우, 드디어 암귀를 따돌렸네. 다들 괜찮아?",
  ui_story_5035_50351401_3_dialog_content = "괜찮습니다만, 저희와 거리가 벌어진 건 암귀뿐만이 아닌 것 같습니다.",
  ui_story_5035_50351401_4_dialog_content = "응?",
  ui_story_5035_50351401_5_dialog_content = "앗! 리리카랑 새디는?!",
  ui_story_5035_50351401_6_dialog_content = "방금 전 한바탕 혼전이 벌어졌을 때 저희와 떨어지게 된 모양입니다.\n지금 어디에 있는지는 알 수 없습니다.",
  ui_story_5035_50351401_7_dialog_content = "큰일이야. 두 사람만으로는 뭔가 마주쳐도 대처가 안 될 거야. 빨리 찾으러 돌아가야 해!",
  ui_story_5035_50351401_8_dialog_content = "네, 두 분은 아마 계속 2층에 계실 겁니다.",
  ui_story_5035_50351401_9_dialog_content = "PlayerName 님, 감응 능력을 사용해 찾아보시는 건 어떻겠습니까.",
  ui_story_5035_50351401_10_dialog_content = "지금 찾고 있어...",
  ui_story_5035_50351401_11_dialog_content = "잠깐만!",
  ui_story_5035_50351401_12_dialog_content = "응? 왜 그래?",
  ui_story_5035_50351401_13_dialog_content = "아까 우리가 여기 올 때... 복도에 저런 게 있었나?",
  ui_story_5035_50351401_14_dialog_content = "언제 나타난 거지?!",
  ui_story_5035_50351401_15_dialog_content = "저렇게 크면 지나올 때 분명히 발견했을 텐데.",
  ui_story_5035_50351401_16_dialog_content = "음, 아니. 난 오면서 저거 못 봤어.",
  ui_story_5035_50351401_17_dialog_content = "저게 뭐야? 관인가?",
  ui_story_5035_50351401_18_dialog_content = "맞습니다. 방금 전 스태프가 옮기던 소품입니다.",
  ui_story_5035_50351401_19_dialog_content = "누가 저기까지 옮겨 둔 걸까요?",
  ui_story_5035_50351401_20_dialog_content = "나, 나중에 생각하자. 지금은 우선 리리카랑 새디를 찾는 게 더 중요해.",
  ui_story_5035_50351401_21_dialog_content = "그냥 옆으로 지나쳐 가면 돼.",
  ui_story_5035_50351401_22_dialog_content = "그래, 지나쳐 가면 되지.",
  ui_story_5035_50351401_23_dialog_content = "PlayerName, 네가 앞장서.",
  ui_story_5035_50351401_24_dialog_content = "어? 내, 내가?",
  ui_story_5035_50351401_25_dialog_content = "응.",
  ui_story_5035_50351401_26_dialog_content = "하지만...",
  ui_story_5035_50351401_27_dialog_content = "그래, 가자! 내가 앞장서면 될 거 아냐! 까짓거 소품일 뿐인데 뭐가 무섭겠어!",
  ui_story_5035_50351401_28_dialog_content = "서둘러, 빨리 두 사람을 찾아야...",
  ui_story_5035_50351401_29_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5035_50351401_30_dialog_content = "으아아악──!",
  ui_story_5035_50351401_31_dialog_content = "으음?",
  ui_story_5035_50351401_32_dialog_content = "아, 저쪽에서 나는 소리군.",
  ui_story_5035_50351401_33_dialog_content = "소리가 났어! 과, 관 안에서 소리가 났다고!",
  ui_story_5035_50351401_34_dialog_content = "나, 나도 들었어!",
  ui_story_5035_50351401_35_dialog_content = "저, 저거 그냥 소품 맞아?",
  ui_story_5035_50351401_36_dialog_content = "흐... 흑....",
  ui_story_5035_50351401_37_dialog_content = "살려 줘... 유령이 있어...",
  ui_story_5035_50351401_38_dialog_content = "어떡하지?! 저 관에 가까이 못 가겠어!",
  ui_story_5035_50351401_39_dialog_content = "다른 길로 가야 하나? 하지만 저런 걸 등지고 가기엔 그것도 좀...",
  ui_story_5035_50351401_40_dialog_content = "아무래도 다시 확인해 봐야 할 것 같습니다.",
  ui_story_5035_50351401_41_dialog_content = "제가 관의 뚜껑을 열어 보도록 하지요.",
  ui_story_5035_50351401_42_dialog_content = "뚜껑을 열겠다고?!",
  ui_story_5035_50351401_43_dialog_content = "최소한 우리 앞에 있는 저것이 뭔지는 확실히 알 수 있을 겁니다.",
  ui_story_5035_50351401_44_dialog_content = "그래도 최대한 조심해야 해...",
  ui_story_5035_50351401_45_dialog_content = "괜찮을 겁니다.",
  ui_story_5035_50351401_46_dialog_content = "저는 준비됐습니다.",
  ui_story_5035_50351401_47_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5035_50351401_48_dialog_content = "조금 더...",
  ui_story_5035_50351401_49_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5035_50351401_50_dialog_content = "조금만 더...",
  ui_story_5035_50351401_51_dialog_content = "<color=#e8d9bb>쾅! 쾅!</color>",
  ui_story_5035_50351401_52_dialog_content = "......",
  ui_story_5035_50351401_53_dialog_content = "<color=#e8d9bb>쾅! 쾅! 쾅! 쾅!</color>",
  ui_story_5035_50351401_54_dialog_content = "후... 후우...",
  ui_story_5035_50351401_55_dialog_content = "소리가 엄청 격해졌어! 우리가 가까이 왔단 걸 느낄 수 있나 봐!",
  ui_story_5035_50351401_56_dialog_content = "어서 돌아와! 미노스!",
  ui_story_5035_50351401_57_dialog_content = "죄송합니다. 더 가까이 접근할 수 없을 것 같습니다.",
  ui_story_5035_50351401_58_dialog_content = "뭐?",
  ui_story_5035_50351401_59_dialog_content = "안에 무언가가 있습니다. 우릴 죽음으로 인도할 무언가가 말입니다.",
  ui_story_5035_50351401_60_dialog_content = "역시... 소품이 아니라 진짜 관이었어...",
  ui_story_5035_50351401_61_dialog_content = "오늘은 왜 이렇게 말도 안 되는 일들이 자꾸 일어나는 거지?",
  ui_story_5035_50351401_62_dialog_content = "여기 말고 다른 길로 돌아서 가자. 저 관에서 조금이라도 멀리 떨어지게.",
  ui_story_5035_50351401_63_dialog_content = "다른 길로 돌아간다고 해서 도망칠 수 있겠습니까?",
  ui_story_5035_50351401_64_dialog_content = "여기에 갑자기 나타났던 것처럼, 얼마든지 다른 곳에도 모습을 드러낼 겁니다.",
  ui_story_5035_50351401_65_dialog_content = "그, 그럼 어떻게 하려고...?",
  ui_story_5035_50351401_66_dialog_content = "저 관을 열어야 합니다. 우리 모두 함께요.",
  ui_story_5035_50351401_67_dialog_content = "역시 관을 열 생각이잖아!",
  ui_story_5035_50351401_68_dialog_content = "어둠 속에서 저 관이 우리를 기다리고 있는 것보다는,\n차라리 정면에서 맞부딪히는 게 더 안전할 겁니다.",
  ui_story_5035_50351401_69_dialog_content = "다른 분들의 생각은 어떻습니까?",
  ui_story_5035_50351401_70_dialog_content = "일리는 있어...",
  ui_story_5035_50351401_71_dialog_content = "무섭긴 하지만... 그래도...",
  ui_story_5035_50351401_72_dialog_content = "안에 뭐가 있는지 확인하고 싶어...",
  ui_story_5035_50351401_73_dialog_content = "흑흑...",
  ui_story_5035_50351401_74_dialog_content = "그럼 해 보자! 우리 다 같이 하는 거야!",
  ui_story_5035_50351401_75_dialog_content = "그래봤자 목숨이 위험해지는 것뿐이잖아. 그런 건 이미 수없이 겪어 봤어!",
  ui_story_5035_50351401_76_dialog_content = "응, 맞아. 무서워할 거 없어, 무, 무서워할 거 없어, 무서워할 거 없어.",
  ui_story_5035_50351401_77_dialog_content = "좋습니다. 집중하시고 제 곁에 바짝 붙어 계십시오.",
  ui_story_5035_50351401_78_dialog_content = "무슨 일이라도 일어난다면, 최대한 빨리 대처해야 하니까요.",
  ui_story_5035_50351401_79_dialog_content = "이제 모두 함께 앞으로...",
  ui_story_5035_50351401_80_dialog_content = "기다려! 다들 거기 그대로 있어!",
  ui_story_5035_50351401_81_dialog_content = "아?",
  ui_story_5035_50351401_82_dialog_content = "조니 감독이잖아?",
  ui_story_5035_50351401_83_dialog_content = "다들 가만히 있어! 내가 이렇게 부탁할 테니까, 시간을 조금만 줘!",
  ui_story_5035_50351401_84_dialog_content = "이런 장면은 두 번 다시 없을 테니까, 절대 놓칠 수 없어!",
  ui_story_5035_50351401_85_dialog_content = "1분, 딱 1분이면 돼. 날 믿어, 난 프로니까!",
  ui_story_5035_50351401_86_dialog_content = "그, 그게 무슨 소리야?",
  ui_story_5035_50351401_87_dialog_content = "조니, 또 무슨 짓을 할 생각입니까?",
  ui_story_5035_50351401_88_dialog_content = "그리고! 저 관 안에는 대체 뭐가 들어 있는 거야?!",
  ui_story_5035_50351401_89_dialog_content = "조명이 필요해. 이 각도에서 빛이 들어 와야 한다고.",
  ui_story_5035_50351401_90_dialog_content = "카메라 초점은 조금 더 앞쪽으로 맞추고...",
  ui_story_5035_50351401_91_dialog_content = "좋아, 지금 이 상태가 딱 좋아.",
  ui_story_5035_50351401_92_dialog_content = "그리고 녹음기... 젠장, 버튼이 또 눌려서 안 올라 오잖아!",
  ui_story_5035_50351401_93_dialog_content = "이런 고물 덩어리... 내일 당장 고물상에 갖다줘야겠어.",
  ui_story_5035_50351401_94_dialog_content = "스크립터 녀석은 또 어디 간 거야? 스크립터!",
  ui_story_5035_50351401_95_dialog_content = "됐어, 내가 직접 하지.",
  ui_story_5035_50351401_96_dialog_content = "다들 조금만 더 기다려! 이게 마지막이야!",
  ui_story_5035_50351401_97_dialog_content = "촛불을 켜야겠어. 「에스더」는 타는 냄새를 제일 좋아하거든.",
  ui_story_5035_50351401_98_dialog_content = "<color=#e8d9bb>치익──</color>",
  ui_story_5035_50351401_99_dialog_content = "다 됐어. 배우 여러분, 오래 기다렸어!",
  ui_story_5035_50351401_100_dialog_content = "이제부터 《비명을 멈추면 안 돼!》의 마지막 장면을 촬영할 거다.",
  ui_story_5035_50351401_101_dialog_content = "난 이 영화가 예술성과 상업성을 겸비한 완벽한 영화가 되고,\n이 영화로 인해 이 자리에 계신 모두의 커리어도 완벽해질 거라 믿어.",
  ui_story_5035_50351401_102_dialog_content = "여러분, 그리고 <color=#FFB400>에스더</color>와 함께 이런 독창적인 시도를\n완성할 수 있어서 정말 영광이었어.",
  ui_story_5035_50351401_103_dialog_content = "에스더?",
  ui_story_5035_50351401_104_dialog_content = "큰일이야, 그 이름은...",
  ui_story_5035_50351401_105_dialog_content = "자, 그럼 여러분...",
  ui_story_5035_50351401_106_dialog_content = "우리의 <color=#FFB400>여주인공</color>과 만날 준비는 되셨나?",
  ui_story_5035_50351401_107_dialog_content = "여주인공?!",
  ui_story_5035_50351401_108_dialog_content = "《비명을 멈추면 안 돼!》 라스트 신, 테이크1. 레디...",
  ui_story_5035_50351401_109_dialog_content = "액션!",
  ui_story_5035_50351401_110_dialog_content = "<color=#e8d9bb>딸랑... 딸랑...</color>",
  ui_story_5035_50351401_111_dialog_content = "으악!",
  ui_story_5035_50351401_112_dialog_content = "관! 관에 달린 방울에서 소리가 났어!",
  ui_story_5035_50351401_113_dialog_content = "<color=#e8d9bb>쾅! 쾅!</color>",
  ui_story_5035_50351401_114_dialog_content = "이상하군요. 이번에는 관 근처에 아무도 다가가지 않았는데...",
  ui_story_5035_50351401_115_dialog_content = "<color=#e8d9bb>쾅! 콰앙! 쾅!</color>",
  ui_story_5035_50351401_116_dialog_content = "꺄악!",
  ui_story_5035_50351401_117_dialog_content = "관 뚜껑이! 관 뚜껑이 곧...",
  ui_story_5035_50351401_118_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5035_50351401_119_dialog_content = "우우우... 우우우우우...",
  ui_story_5035_50351401_120_dialog_content = "관에서 뭔가 기어 나왔어!",
  ui_story_5035_50351401_121_dialog_content = "저, 저게 뭐지?",
  ui_story_5035_50351401_122_dialog_content = "저, 저, 저건...",
  ui_story_5035_50351401_123_dialog_content = "아까 우리 뒤를 쫓아 왔던 그 유령 여인이야...",
  ui_story_5035_50351401_124_dialog_content = "저 여자가 바로 <color=#FFB400>에스더</color>라구!",
  ui_story_5035_50351401_125_dialog_content = "우우! 우, 우우우!",
  ui_story_5035_50351401_126_dialog_content = "조, 조니가 찍은 영화에서 이거랑 비슷한 장면을 본 기억이 있어...",
  ui_story_5035_50351401_127_dialog_content = "어떤 장면이었는데?",
  ui_story_5035_50351401_128_dialog_content = "관에서 괴물이 기어 나오더니, 살아 있는 사람을 끌고 관 안으로 들어갔어...",
  ui_story_5035_50351401_129_dialog_content = "관 뚜껑이 덮이고 나서는... 「빠직, 까드득」소리가 들렸고...",
  ui_story_5035_50351401_130_dialog_content = "마지막에는 관에서 흘러나온 피가 화면을 뒤덮으면서, 선혈 속에서 영화가 끝나...",
  ui_story_5035_50351401_131_dialog_content = "관 안으로 끌고 들어갔다고...?",
  ui_story_5035_50351401_132_dialog_content = "잠깐, 그럼 지금 우리가...",
  ui_story_5035_50351401_133_dialog_content = "그런 장면에 출연하고 있다는 거잖아!",
  ui_story_5035_50351401_134_dialog_content = "에, 에스더가 이쪽으로 오고 있어!",
  ui_story_5035_50351401_135_dialog_content = "우우우우!",
  ui_story_5035_50351401_136_dialog_content = "온다! 빨리 도망쳐! 어서 뛰어!",
  ui_story_5035_50351401_137_dialog_content = "우우우우우!",
  ui_story_5035_50351401_138_dialog_content = "바로 내 등 뒤에 있어!",
  ui_story_5035_50351401_139_dialog_content = "마, 많이 가까워?",
  ui_story_5035_50351401_140_dialog_content = "몰라! 뒤를 못 보겠어!",
  ui_story_5035_50351401_141_dialog_content = "우엑, 냄새나.",
  ui_story_5035_50351401_142_dialog_content = "나 기절할 것 같아.",
  ui_story_5035_50351401_143_dialog_content = "큰일입니다. 계속 이 방향으로 이동한다면...",
  ui_story_5035_50351401_144_dialog_content = "왜 그래?",
  ui_story_5035_50351401_145_dialog_content = "만약 조니가 이 앞에 있는 방문을 잠가 버렸다면, 이 길은 막다른 길일 겁니다.",
  ui_story_5035_50351401_146_dialog_content = "뭐어?! 그럼 이제 어떡해!",
  ui_story_5035_50351401_147_dialog_content = "길을 어느 정도 되돌아가야 합니다.",
  ui_story_5035_50351401_148_dialog_content = "우우우우우!",
  ui_story_5035_50351401_149_dialog_content = "상황을 봐! 그게 되겠어?!",
  ui_story_5035_50351401_150_dialog_content = "아니면 복도 끝의 문을 강제로 부수는 수밖에 없습니다.",
  ui_story_5035_50351401_151_dialog_content = "그게 좋겠네! 문 하나를 부수는 건 그렇게 어렵지 않을 거잖아!",
  ui_story_5035_50351401_152_dialog_content = "간단한 일이 아닙니다. 비명의 집의 모든 방문은 루미나틱스에\n강한 저항력을 지니도록 제가 보강해 뒀으니까요.",
  ui_story_5035_50351401_153_dialog_content = "보강해 뒀다고?! 왜, 왜 그런 쓸데없는 일을 한 거야?!",
  ui_story_5035_50351401_154_dialog_content = "손님들이 너무 격한 반응을 보이시다가 혹시라도 문을 부수지는 않을까\n걱정되는 마음에 해 둔 겁니다.",
  ui_story_5035_50351401_155_dialog_content = "저도 문을 부숴야 할 날이 올 줄은 몰랐습니다.",
  ui_story_5035_50351401_156_dialog_content = "그럼 우리한텐 방법이 없단 거잖아!",
  ui_story_5035_50351401_157_dialog_content = "괜찮습니다. 문을 부수는 게 어렵다면, 그 옆에 있는 벽을 부수면 되는 거니까요.",
  ui_story_5035_50351401_158_dialog_content = "그러네! 벽까지 보강해 두지는 않았지?!",
  ui_story_5035_50351401_159_dialog_content = "안 해 뒀습니다. 다만 벽 자체도 튼튼한 편이라 부수려면 시간이 조금 걸릴 겁니다.",
  ui_story_5035_50351401_160_dialog_content = "지금 우리한텐 시간이 부족한데...",
  ui_story_5035_50351401_161_dialog_content = "바로 이 벽입니다.",
  ui_story_5035_50351401_162_dialog_content = "모두 함께 전력으로 공격합시다.",
  ui_story_5035_50351401_163_dialog_content = "네!",
  ui_story_5035_50351401_164_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5035_50351401_165_dialog_content = "구멍이 뚫렸어!",
  ui_story_5035_50351401_166_dialog_content = "서, 서둘러!",
  ui_story_5035_50351401_167_dialog_content = "에스더가... 근처까지 왔어...",
  ui_story_5035_50351401_168_dialog_content = "(에스더 뒤에는... 조니 감독인가?)",
  ui_story_5035_50351401_169_dialog_content = "......",
  ui_story_5035_50351401_170_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5035_50351401_171_dialog_content = "조금만 더!",
  ui_story_5035_50351401_172_dialog_content = "우우우우우!",
  ui_story_5035_50351401_173_dialog_content = "빨리! 에스더가 따라붙었어!",
  ui_story_5035_50351401_174_dialog_content = "<color=#e8d9bb>와르르르!</color>",
  ui_story_5035_50351401_175_dialog_content = "됐습니다! 모두 어서 들어가십시오!",
  ui_story_5035_50351401_176_dialog_content = "PlayerName, 빨리 가자!",
  ui_story_5035_50351401_177_dialog_content = "응!",
  ui_story_5035_50351401_178_dialog_content = "이 앞으로 가면 2층에 도착합니다. 2층이라면 지금보다는 행동에 제약을 덜 받을 겁니다.",
  ui_story_5035_50351401_179_dialog_content = "좋았어! 그럼 이제...",
  ui_story_5035_50351401_180_dialog_content = "꺄악!",
  ui_story_5035_50351401_181_dialog_content = "바이스?! 왜 그래?",
  ui_story_5035_50351401_182_dialog_content = "뭔가가... 날 잡아당기고 있어...",
  ui_story_5035_50351401_183_dialog_content = "!!!",
  ui_story_5035_50351401_184_dialog_content = "바이스가 붙잡혔어!",
  ui_story_5035_50351401_185_dialog_content = "망할 관짝! 빨리 바이스를 놔 줘!",
  ui_story_5035_50351401_186_dialog_content = "제가 도와드리겠습니다...",
  ui_story_5035_50351401_187_dialog_content = "우우!",
  ui_story_5035_50351401_188_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5035_50351401_189_dialog_content = "미노스!",
  ui_story_5035_50351401_190_dialog_content = "퍼피, 바이스가 빠져나올 수 있게 우리가 잡아당겨 주자!",
  ui_story_5035_50351401_191_dialog_content = "으쌰, 으쌰.",
  ui_story_5035_50351401_192_dialog_content = "힘이 너무 세... 떨쳐낼 수가 없어!",
  ui_story_5035_50351401_193_dialog_content = "뭔가 방법이 없을까... 뭔가 방법이...",
  ui_story_5035_50351401_194_dialog_content = "그래! 바로 그 표정이야! 이 부분에서는 클로즈업을 해야겠군! 클로즈업!",
  ui_story_5035_50351401_195_dialog_content = "이 자식!",
  ui_story_5035_50351401_196_dialog_content = "쉿!",
  ui_story_5035_50351401_197_dialog_content = "대사는 등장 인물한테 쳐야지. 내가 아니라.",
  ui_story_5035_50351401_198_dialog_content = "네 목숨을 불태워 이제 곧 완성될 작품인데, 프로 정신을 발휘하란 말이야.",
  ui_story_5035_50351401_199_dialog_content = "너...",
  ui_story_5035_50351401_200_dialog_content = "그렇게 프로를 원한다면 내가 상대해 줄게!",
  ui_story_5035_50351401_201_dialog_content = "<color=#e8d9bb>펑, 펑, 펑!</color>",
  ui_story_5035_50351401_202_dialog_content = "아아악! 누가 플래시를 터트린 거냐!",
  ui_story_5035_50351401_203_dialog_content = "찍은 컷들이 다 헛수고가 됐잖아!",
  ui_story_5035_50351401_204_dialog_content = "우우...",
  ui_story_5035_50351401_205_dialog_content = "에스더가 손을 놨어!",
  ui_story_5035_50351401_206_dialog_content = "지금이야! 멀리 떨어져!",
  ui_story_5035_50351401_207_dialog_content = "응!",
  ui_story_5035_50351401_208_dialog_content = "방금 그건... 리리카?",
  ui_story_5035_50351401_209_dialog_content = "조니 감독, 카메라 위치를 정말 못 잡는구나.",
  ui_story_5035_50351401_210_dialog_content = "내가 있는 이 방향에서 찍어야 구도가 제대로 나올 거 아냐? 그런 것도 몰라? 어휴.",
  ui_story_5035_50351401_211_dialog_content = "리리카...",
  ui_story_5035_50351401_212_dialog_content = "네가 제 발로 다시 내 앞에 나타날 줄이야.",
  ui_story_5035_50351401_213_dialog_content = "배우는 영화를 끝까지 촬영해야 한다며? 당신이 가르쳐 준 거잖아.",
  ui_story_5035_50351401_214_dialog_content = "저번엔 나 때문에 결말 부분을 못 찍었으니까, 이번에 제대로 보상해 줄게!",
  ui_story_5035_50351401_215_dialog_content = "좋아. 그렇다면 더 좋지.",
  ui_story_5035_50351401_216_dialog_content = "사실 방금 전까지 이번 영화는 러닝 타임이 너무 짧진 않은가 걱정하고 있었거든.",
  ui_story_5035_50351401_217_dialog_content = "이제 네가 와 줬으니...",
  ui_story_5035_50351401_218_dialog_content = "뭘 걱정하고 있는 겁니까?",
  ui_story_5035_50351401_219_dialog_content = "미노스! 무사했구나!",
  ui_story_5035_50351401_220_dialog_content = "......",
  ui_story_5035_50351401_221_dialog_content = "당연히 무사합니다. 단지 유령이 관으로 저를 들이받을 줄은 예상하지 못했던 겁니다.",
  ui_story_5035_50351401_222_dialog_content = "전 이 영화의 프로듀서입니다.\n조니 감독이 영화를 찍고 싶어 한다면, 끝까지 함께 해 줘야겠지요.",
  ui_story_5035_50351401_223_dialog_content = "다들 직업 정신이 투철하네.",
  ui_story_5035_50351401_224_dialog_content = "그럼 다들 연기해. 난 배우 그만둘래.",
  ui_story_5035_50351401_225_dialog_content = "자기소개를 다시 할게.\n난 「666 새디」라고 하는 의적, 난 절대 안 해 뻔뻔한 척♪",
  ui_story_5035_50351401_226_dialog_content = "이 몸의 배트질에 들어 백기 힘없이,\n네 입에 배터지게 들이 붓지 흙먼지!",
  ui_story_5035_50351401_227_dialog_content = "내일 아침 신문 도배하겠지!\n그건 바로 너 「범죄자 조니」!",
  ui_story_5035_50351401_228_dialog_content = "와, 너도 플로우 좀 타는데?",
  ui_story_5035_50351401_229_dialog_content = "헤헤, 네가 하는 걸 많이 듣다 보니까 좀 배웠어!",
  ui_story_5035_50351401_230_dialog_content = "그럼 다들~ 준비해 줘!",
  ui_story_5035_50351401_231_dialog_content = "보고 만질 수 있는 유령이 뭐가 무서워! 그럼 그냥 괴물일 뿐이잖아!",
  ui_story_5035_50351401_232_dialog_content = "《배우의 필수 소양》도 안 읽은 주제에 내 배역을 뺏겠다구?",
  ui_story_5035_50351401_233_dialog_content = "「여주인공」 타이들은 내가 돌려받겠어!",
  ui_story_5035_50351401_234_dialog_content = "다들 그렇게나 열의를 보여 주니 기뻐서 몸 둘 바를 모르겠군.",
  ui_story_5035_50351401_235_dialog_content = "《비명을 멈추면 안 돼!》 라스트 신, 테이크2. 레디...",
  ui_story_5035_50351401_236_dialog_content = "액션!",
  ui_story_5035_50351402_1_dialog_content = "<color=#e8d9bb>퍽! 퍽퍽!</color>",
  ui_story_5035_50351402_2_dialog_content = "우우우우!",
  ui_story_5035_50351402_3_dialog_content = "<color=#e8d9bb>퍼어억!</color>",
  ui_story_5035_50351402_4_dialog_content = "다들 괜찮아?",
  ui_story_5035_50351402_5_dialog_content = "콜록...",
  ui_story_5035_50351402_6_dialog_content = "으...",
  ui_story_5035_50351402_7_dialog_content = "몸이 조금 말을 안 들어...",
  ui_story_5035_50351402_8_dialog_content = "에스더는 어떻게 됐어? 쓰러트렸어?",
  ui_story_5035_50351402_9_dialog_content = "아직 쓰러트리진 못했는데...",
  ui_story_5035_50351402_10_dialog_content = "처음보다는 약해진 것 같아.",
  ui_story_5035_50351402_11_dialog_content = "우우... 우우우우...",
  ui_story_5035_50351402_12_dialog_content = "한참 패 줘서 그런지 이젠 별로 무섭진 않은 것 같아.",
  ui_story_5035_50351402_13_dialog_content = "그러게. 근데 유령이라곤 하지만 몸에서 짙은 다크매터를 발산해서\n나한텐 암귀랑 비슷하게 느껴져.",
  ui_story_5035_50351402_14_dialog_content = "어쩌면 그냥 암귀 중에서 좀 특이한 개체일 수도 있겠어.",
  ui_story_5035_50351402_15_dialog_content = "전투도 이제 막바지입니다. 이제 우리와 에스더 중 누가 끝까지 버티느냐에 달려 있습니다.",
  ui_story_5035_50351402_16_dialog_content = "우리가 버티기만 하면...",
  ui_story_5035_50351402_17_dialog_content = "<color=#e8d9bb>치익──</color>",
  ui_story_5035_50351402_18_dialog_content = "!!!",
  ui_story_5035_50351402_19_dialog_content = "이런! 저 촛불!",
  ui_story_5035_50351402_20_dialog_content = "저 촛불이 에스더한테 힘을 주고 있어!",
  ui_story_5035_50351402_21_dialog_content = "조금 더 버텨, 에스더. 조금만 더.",
  ui_story_5035_50351402_22_dialog_content = "조금 더 버텨야 해.",
  ui_story_5035_50351402_23_dialog_content = "우우...",
  ui_story_5035_50351402_24_dialog_content = "가서 녀석들을 먹어 치워. 하나만 먹어도 힘을 회복할 수 있을 거야.",
  ui_story_5035_50351402_25_dialog_content = "하나만 먹으면, 나머지 모두를 다 먹을 수 있어.",
  ui_story_5035_50351402_26_dialog_content = "우우우우우!",
  ui_story_5035_50351402_27_dialog_content = "하지만 나한텐 더 중요한 일이 있어서 널 도와줄 수 없어.",
  ui_story_5035_50351402_28_dialog_content = "난 네 모든 행동을 하나하나 다 카메라에 담아야 해.",
  ui_story_5035_50351402_29_dialog_content = "실제로 행동하는 것보다는 이런 영상들이 더 중요하거든. 너도 이해하겠지.",
  ui_story_5035_50351402_30_dialog_content = "우우!",
  ui_story_5035_50351402_31_dialog_content = "내가 해 줄 수 있는 건 널 위해 촛불을 켜 주는 것뿐이야.",
  ui_story_5035_50351402_32_dialog_content = "<color=#e8d9bb>치익──</color>",
  ui_story_5035_50351402_33_dialog_content = "온도가 느껴져? 네가 오래전에 잃었던 그 느낌 말이야.",
  ui_story_5035_50351402_34_dialog_content = "이 뜨거움은 아직도 네 안에 흐르고 있어. 넌 아직 진정한 의미의 죽음을 맞이한 게 아니야.",
  ui_story_5035_50351402_35_dialog_content = "적어도 이 순간만큼은 넌 살아 있어. 내가 널 살려냈어.",
  ui_story_5035_50351402_36_dialog_content = "저 사람들 좀 봐. 네가 갈망하던 삶을 가지고 있으면서도,\n생명을 향한 경외 한 번 표현한 적 없는 사람들이야.",
  ui_story_5035_50351402_37_dialog_content = "<color=#e8d9bb>치익──</color>",
  ui_story_5035_50351402_38_dialog_content = "가서 저들에게는 과분한 것들을 빼앗아 와.\n네가 당연히 가지고 있어야 할 것들을 되찾아 오는 거야.",
  ui_story_5035_50351402_39_dialog_content = "우우우우!",
  ui_story_5035_50351402_40_dialog_content = "에스더가 또 이쪽을 향해 달려오고 있어!",
  ui_story_5035_50351402_41_dialog_content = "저 촛불들을 꺼야 돼! 안 그러면 힘을 금방 또 회복할 거야!",
  ui_story_5035_50351402_42_dialog_content = "그렇다면 두 팀으로 나눠 행동하지요. 저와 바이스 양은 에스더의 발목을 잡도록 합시다.\n나머지 분들께서는 촛불을 꺼 주십시오.",
  ui_story_5035_50351402_43_dialog_content = "네!",
  ui_story_5035_50351402_44_dialog_content = "두 사람만으로 에스더를 붙들어 둘 수 있겠어?",
  ui_story_5035_50351402_45_dialog_content = "해보는 수밖에 없습니다.",
  ui_story_5035_50351402_46_dialog_content = "맞아, 상황이 상황이니까 어떻게든 해 봐야지!",
  ui_story_5035_50351402_47_dialog_content = "받아라!",
  ui_story_5035_50351402_48_dialog_content = "에스더를 뒤쪽으로 유인해 주십시오.",
  ui_story_5035_50351402_49_dialog_content = "알겠어요!",
  ui_story_5035_50351402_50_dialog_content = "그럼 리리카, 새디, 우리도 서두르자!",
  ui_story_5035_50351402_51_dialog_content = "알겠어!",
  ui_story_5035_50351402_52_dialog_content = "겸사겸사 조니 감독한테 이 배트로 풀스윙 한 번만 날려도 돼?",
  ui_story_5035_50351402_53_dialog_content = "촛불 끄고 나면 너 하고 싶은 거 다 해!",
  ui_story_5035_50351402_54_dialog_content = "그거 완전 최고야! 나도 끼워 줘!",
  ui_story_5035_50351402_55_dialog_content = "에스더는 못 이기지만, 조니는 좀 괴롭혀도 되는 거잖아!",
  ui_story_5035_50351402_56_dialog_content = "어이, 지금 카메라를 가리고 있잖아!",
  ui_story_5035_50351402_57_dialog_content = "가리기만 할 것 같아? 이따가 그 카메라를 박살내 버릴 거거든!",
  ui_story_5035_50351402_58_dialog_content = "우리가 실력 발휘하는 거 보고 싶지 않으면, 빨리 촛불 내놔!",
  ui_story_5035_50351402_59_dialog_content = "그건 영화에 등장하는 소품이 아니니까, 거기에 너무 집중하지 말아 줬으면 좋겠는데.",
  ui_story_5035_50351402_60_dialog_content = "조니랑 입씨름할 시간 없어! 미노스랑 바이스도 시간을 많이 벌어 주진 못해.",
  ui_story_5035_50351402_61_dialog_content = "그럼 내 주먹을...",
  ui_story_5035_50351402_62_dialog_content = "<color=#e8d9bb>와르르르!</color>",
  ui_story_5035_50351402_63_dialog_content = "콜록, 콜록. 어떻게 된 거야?",
  ui_story_5035_50351402_64_dialog_content = "그어어어!",
  ui_story_5035_50351402_65_dialog_content = "암귀?! 그것도 이렇게 많이?!",
  ui_story_5035_50351402_66_dialog_content = "이런! 계속 주변 상황을 살폈어야 했어!",
  ui_story_5035_50351402_67_dialog_content = "우린 이미 포위됐어!",
  ui_story_5035_50351402_68_dialog_content = "너희, 에스더가 암귀와 비슷하다고 했지?",
  ui_story_5035_50351402_69_dialog_content = "근데 생각해 본 적 없는 거냐? 왜 이 저택에 암귀들이 이렇게 많이 나타나는지?",
  ui_story_5035_50351402_70_dialog_content = "!!!",
  ui_story_5035_50351402_71_dialog_content = "그거였어! 고위 암귀는 다른 암귀를 불러들일 수 있잖아!",
  ui_story_5035_50351402_72_dialog_content = "넌 에스더를 조종해서 다른 암귀들을 이 저택으로 불러들인 거야!",
  ui_story_5035_50351402_73_dialog_content = "이 녀석들은 아름답지 않아. 카메라에 이런 녀석들을 담고 싶은 마음은 없어.",
  ui_story_5035_50351402_74_dialog_content = "다만 촬영 과정이 순조로우려면, 나도 어느 정도는 경호원이 필요해.",
  ui_story_5035_50351402_75_dialog_content = "제멋대로 구는 배우가 촬영장 물을 흐리기 시작하면,\n녀석들이 모든 걸 정상으로 되돌려 줄 수 있거든.",
  ui_story_5035_50351402_76_dialog_content = "암귀가 너무 많아...",
  ui_story_5035_50351402_77_dialog_content = "녀석들을 다 쓰러트리기엔 힘이 모자랄 수도 있겠어.",
  ui_story_5035_50351402_78_dialog_content = "꺄악!",
  ui_story_5035_50351402_79_dialog_content = "바이스!",
  ui_story_5035_50351402_80_dialog_content = "이젠 끝이야! 두 사람 쪽도 더 이상 버티질 못해!",
  ui_story_5035_50351402_81_dialog_content = "에스더도 못 쓰러트렸고, 촛불도 못 껐고, 심지어는 주변에 있는 암귀들도 해치우지 못했어...",
  ui_story_5035_50351402_82_dialog_content = "이번에는 진짜...",
  ui_story_5035_50351402_83_dialog_content = "그래, 그거야. 그 대사를 치라고.",
  ui_story_5035_50351402_84_dialog_content = "너희 모두, 이번엔 진짜로 끝장이다!",
  ui_story_5035_50351402_85_dialog_content = "이 자식!",
  ui_story_5035_50351402_86_dialog_content = "PlayerName, 우리 도망치자.",
  ui_story_5035_50351402_87_dialog_content = "도망치자고?",
  ui_story_5035_50351402_88_dialog_content = "응, 나 도망치는 거 잘해. 그러니까 날 따라와.",
  ui_story_5035_50351402_89_dialog_content = "도망치는 데 성공하면, 더 많은 사람한테 사건의 진상을 알려서 조니가 벌을 받게 할 수 있어!",
  ui_story_5035_50351402_90_dialog_content = "우리가... 도망칠 수 있을까...?",
  ui_story_5035_50351402_91_dialog_content = "우리가 도망치는 데 성공했다고 해도, 비명의 집에 남은 다른 사람들은 어떡해?",
  ui_story_5035_50351402_92_dialog_content = "다른 사람들은...",
  ui_story_5035_50351402_93_dialog_content = "모두 잘 들어!",
  ui_story_5035_50351402_94_dialog_content = "녀석들을 흠씬 두들겨 주는 거다! 봐주지 마!",
  ui_story_5035_50351402_95_dialog_content = "어? 누구지?!",
  ui_story_5035_50351402_96_dialog_content = "읏쌰~",
  ui_story_5035_50351402_97_dialog_content = "오늘 이 비명의 집의 암귀는 나야! 어디서 내 일을 뺏으려고!",
  ui_story_5035_50351402_98_dialog_content = "뭐가 어떻게 된 거야? 암귀랑 암귀가 싸우기 시작했는데?",
  ui_story_5035_50351402_99_dialog_content = "암귀들 사이에 암귀 코스튬을 입은 직원들이 섞여 있어!",
  ui_story_5035_50351402_100_dialog_content = "크오오!",
  ui_story_5035_50351402_101_dialog_content = "시끄러워! 시끄럽다고!",
  ui_story_5035_50351402_102_dialog_content = "어디서 외부인들이 잔뜩 몰려온 거야? 내 영화 촬영장에서 당장 꺼져!",
  ui_story_5035_50351402_103_dialog_content = "지금 촬영 중인 거 안 보여? 영화 촬영 중이라고!",
  ui_story_5035_50351402_104_dialog_content = "저 녀석이 아직 정신없어하고 있으니까, 빨리! 얼른!",
  ui_story_5035_50351402_105_dialog_content = "아까 잘 들었지? PlayerName한텐 저 촛불이 필요해.",
  ui_story_5035_50351402_106_dialog_content = "하이고, 알겠슴미더!",
  ui_story_5035_50351402_107_dialog_content = "또 뭐야?!",
  ui_story_5035_50351402_108_dialog_content = "이건 이제 지 꺼라예! 지가 해냈심더!",
  ui_story_5035_50351402_109_dialog_content = "PlayerName 오빠야, 필요하단 게 이거 맞슴미꺼?",
  ui_story_5035_50351402_110_dialog_content = "와! 촛불을 뺏었구나!",
  ui_story_5035_50351402_111_dialog_content = "망할! 어서 내려놓지 못해?!",
  ui_story_5035_50351402_112_dialog_content = "풋! 날 잡진 못할걸!",
  ui_story_5035_50351402_113_dialog_content = "촛불 하나 더!",
  ui_story_5035_50351402_114_dialog_content = "성가신 참새 녀석들! 가만두지 않겠어!",
  ui_story_5035_50351402_115_dialog_content = "조니, 우리 아직 할 말 많이 남았거든.",
  ui_story_5035_50351402_116_dialog_content = "새디? 이제야 나타났군, 이 기회주의자 녀석.",
  ui_story_5035_50351402_117_dialog_content = "뺏겼다고 해도 촛불 두 개뿐이야. 아직 다른 촛불들이 남아서 타오르고 있지.",
  ui_story_5035_50351402_118_dialog_content = "돌아와, 에스더. 이 참새들을 먹어 치워.",
  ui_story_5035_50351402_119_dialog_content = "우우우!",
  ui_story_5035_50351402_120_dialog_content = "다른 촛불들이 있다고?",
  ui_story_5035_50351402_121_dialog_content = "이거 말하는 거야?",
  ui_story_5035_50351402_122_dialog_content = "!!!",
  ui_story_5035_50351402_123_dialog_content = "그게 왜 네 손에?! 대체 언제부터!",
  ui_story_5035_50351402_124_dialog_content = "잊었어? 난 의적이야!",
  ui_story_5035_50351402_125_dialog_content = "에스더가 그쪽으로 갔어! 빨리 촛불을 꺼 버려!",
  ui_story_5035_50351402_126_dialog_content = "응.",
  ui_story_5035_50351402_127_dialog_content = "이젠 네 촬영을 끝낼 시간이야, 조니.",
  ui_story_5035_50351402_128_dialog_content = "후──",
  ui_story_5035_50351402_129_dialog_content = "우, 우우... 우우우우...",
  ui_story_5035_50351402_130_dialog_content = "우우우우우우...",
  ui_story_5035_50351402_131_dialog_content = "좋았어! 에스더가 싸울 힘이 사라졌어!",
  ui_story_5035_50351402_132_dialog_content = "상황을 보니 우리가 악전고투 속에서도 끝까지 버텨낸 모양입니다.",
  ui_story_5035_50351402_133_dialog_content = "아직 방심하면 안 돼. 에스더의 힘은 완전히 사라진 게 아니야.\n감독이 다른 곳에 촛불을 숨겨 뒀을 수도 있어.",
  ui_story_5035_50351402_134_dialog_content = "에스더가 약해진 지금이 기회야! 단숨에 쓰러트리자!",
  ui_story_5035_50351402_135_dialog_content = "알겠어!",
  ui_story_5035_50351402_136_dialog_content = "속사 감...",
  ui_story_5035_50351402_137_dialog_content = "안 돼!",
  ui_story_5035_50351402_138_dialog_content = "이럴 순 없어! 안 돼, 이건 절대 안 돼!",
  ui_story_5035_50351402_139_dialog_content = "이 결말은 정말 최악이야! 내가 원하는 영화에 이따위 마무리는 존재할 수 없어!",
  ui_story_5035_50351402_140_dialog_content = "에스더를 보호하려는 건가?",
  ui_story_5035_50351402_141_dialog_content = "하마터면 그냥 공격해 버릴 뻔했잖아. 죽는 게 무섭지도 않나...",
  ui_story_5035_50351402_142_dialog_content = "이 난폭한 녀석들이 널 이런 꼴로 만들다니, 치마도 다 찢어져 버렸잖아.",
  ui_story_5035_50351402_143_dialog_content = "에스더, 나의 에스더, 나의 여주인공.",
  ui_story_5035_50351402_144_dialog_content = "네가 힘들어하고 있다는 거 알아.\n빛들이 하나씩 꺼져가고 있으니까, 너도 분명히 많이 추울 거야.",
  ui_story_5035_50351402_145_dialog_content = "이 세상은 언제나 그랬어. 네게 온기를 나눠 주려는 사람은 아무도 없었지.",
  ui_story_5035_50351402_146_dialog_content = "하지만 두려워 마. 에스더. 네 곁엔 내가 있잖아.",
  ui_story_5035_50351402_147_dialog_content = "내 온기를 너한테 줄게.",
  ui_story_5035_50351402_148_dialog_content = "날 먹어, 에스더. 그러면 그들과 맞설 수 있는 힘을 다시 얻을 수 있을 거야.",
  ui_story_5035_50351402_149_dialog_content = "조, 조니가 에스더한테 다가갔어!",
  ui_story_5035_50351402_150_dialog_content = "...미쳐 버렸군요.",
  ui_story_5035_50351402_151_dialog_content = "막아야 할까?",
  ui_story_5035_50351402_152_dialog_content = "저걸 어떻게 막아... 죽여서?",
  ui_story_5035_50351402_153_dialog_content = "리리카!",
  ui_story_5035_50351402_154_dialog_content = "어라? 나?",
  ui_story_5035_50351402_155_dialog_content = "어서 카메라를 들어, 리리카! 그리고 이 장면을 찍어!",
  ui_story_5035_50351402_156_dialog_content = "부탁이니까 찍어 줘. 꼭 찍어 줘야 해.",
  ui_story_5035_50351402_157_dialog_content = "대, 대체 무슨 짓이야?",
  ui_story_5035_50351402_158_dialog_content = "이 장면을 전에 찍은 영상에 편집해서 붙여 넣어 줘.",
  ui_story_5035_50351402_159_dialog_content = "그래, 이러면 결말이 완벽해질 거다. 예상했던 것보다 훨씬 완벽해!",
  ui_story_5035_50351402_160_dialog_content = "내 마지막 작품은 에스더를 숭배의 대상으로 만들어 줄 작품이다.\n이런 작품에 나 말고 다른 사람은 어울리지 않아.",
  ui_story_5035_50351402_161_dialog_content = "나와 에스더가 함께 연기해야만 최고의 시너지 효과가 날 거라고.",
  ui_story_5035_50351402_162_dialog_content = "진짜 미쳤어?! 영화 때문에 다른 사람들을 희생시키더니, 이젠 자기 목숨까지 버리겠다는 거야?!",
  ui_story_5035_50351402_163_dialog_content = "빨리 카메라 켜!",
  ui_story_5035_50351402_164_dialog_content = "난 느꼈어. 에스더에게서 따뜻한 숨결이 느껴지지 않아.",
  ui_story_5035_50351402_165_dialog_content = "어서! 이게 바로 가장 완벽한 예술이야! 한 프레임도 놓쳐선 안 돼!",
  ui_story_5035_50351402_166_dialog_content = "바보 같은 짓 말아요. 그런 건 예술이 아니라구요.",
  ui_story_5035_50351402_167_dialog_content = "뭐라고?!",
  ui_story_5035_50351402_168_dialog_content = "누구야! 방금 누가 그따위 소리를 한 거야!",
  ui_story_5035_50351402_169_dialog_content = "전 예술은 노력과 사랑이 모여서 만들어지는 거라고 생각해요.",
  ui_story_5035_50351402_170_dialog_content = "다른 사람을 우롱한 건 노력이 아니에요.",
  ui_story_5035_50351402_171_dialog_content = "시체를 향해 혼잣말을 하는 건 감정이라곤 할 수 없어요.",
  ui_story_5035_50351402_172_dialog_content = "당신에게는 예술이라고 말할 수 있는 건 단 하나도 찾아볼 수 없어요.",
  ui_story_5035_50351402_173_dialog_content = "당신이 선보이고 있는 건 그저 비참한 자아 실현극에 지나지 않아요.",
  ui_story_5035_50351402_174_dialog_content = "골디?! 어떻게 살아 있었지?",
  ui_story_5035_50351402_175_dialog_content = "당신이 못다 한 결말을 보충해 주기 위해서예요.",
  ui_story_5035_50351402_176_dialog_content = "관객들이 진심으로 만족해할 만한 그런 결말로요.",
  ui_story_5035_50351402_177_dialog_content = "이 촛불 기억하나요?\n이렇게 자그마해진 걸 보면, 아마 당신이 가장 먼저 불을 붙였던 양초일 거예요.",
  ui_story_5035_50351402_178_dialog_content = "당신한테 돌려줄게요.",
  ui_story_5035_50351402_179_dialog_content = "안 돼! 지금은 안 돼!",
  ui_story_5035_50351402_180_dialog_content = "에스더! 빨리, 우리에게 허락된 시간이 이제 시간이 얼마 남지 않았어!",
  ui_story_5035_50351402_181_dialog_content = "한번만 더 힘을 내! 네 턱으로 내 목을 꿰뚫어 줘!",
  ui_story_5035_50351402_182_dialog_content = "날 먹어, 지금 당장 날 먹어 버려!",
  ui_story_5035_50351402_183_dialog_content = "빨리!",
  ui_story_5035_50351402_184_dialog_content = "연기하느라 수고 많았어요, 조니.",
  ui_story_5035_50351402_185_dialog_content = "촬영 종료.",
  ui_story_5035_50351402_186_dialog_content = "후──",
  ui_story_5035_50351402_187_dialog_content = "안 돼──!",
  ui_story_5035_50351402_188_dialog_content = "에스더! 에스더! 아직 내 말 들리지?!",
  ui_story_5035_50351402_189_dialog_content = "나 여기 있어. 잘 들어 봐. 내 목소리야!",
  ui_story_5035_50351402_190_dialog_content = "한번만 대답해 줘! 이렇게 부탁할게! 제발!",
  ui_story_5035_50351402_191_dialog_content = "조금만 더 하면 완성할 수 있어! 에스더! 걸작으로 칭송받을 작품이 될 거라고!",
  ui_story_5035_50351402_192_dialog_content = "<anim type=Shake><size=50>에스더! 에스더어어어!</size></anim>",
  ui_story_5035_50351501_1_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5035_50351501_2_dialog_content = "그거 들었어? 아까 그 저택에서 갑자기 엄청나게 큰 소리가 들렸는데...",
  ui_story_5035_50351501_3_dialog_content = "난 비명 소리까지 들었어. 근데 평범한 비명 소리는 아닌 것 같았단 말이지...",
  ui_story_5035_50351501_4_dialog_content = "(아무래도 신경 쓰여... 저 안에서 미노스랑 PlayerName 일행한테 무슨 일이 일어나고 있는 거지?)",
  ui_story_5035_50351501_5_dialog_content = "(안 돼, 이러면 안 돼. 내가 안에 들어가 버리면 입구 쪽을 관리할 사람이 없어.)",
  ui_story_5035_50351501_6_dialog_content = "근데 저 저택 안은 얼마 전에 개업한 유령의 집이라던데?",
  ui_story_5035_50351501_7_dialog_content = "아! 정말이잖아! 저 안내판 좀 봐!",
  ui_story_5035_50351501_8_dialog_content = "(앗, 예상외로 손님들을 불러 모으는 효과가 있잖아...!)",
  ui_story_5035_50351501_9_dialog_content = "안데르센 비명의 집은 오늘 첫 영업을 시작했답니다. 한번 구경해 보시겠어요?",
  ui_story_5035_50351501_10_dialog_content = "유령의 집이라면, 조금 전 비명이나 그런 건 다 겁주려고 일부러 지른 건가?",
  ui_story_5035_50351501_11_dialog_content = "그럼 또 어때. 들어가서 좀 보다가 별로 재미없으면 그냥 나오면 되는 거지.",
  ui_story_5035_50351501_12_dialog_content = "「구경」하는 거니까 입장료는 안 내도 되죠?",
  ui_story_5035_50351501_13_dialog_content = "그건...",
  ui_story_5035_50351501_14_dialog_content = "잠깐, 더는 입장시키면 안 됩니다.",
  ui_story_5035_50351501_15_dialog_content = "앗?! 제인 씨? 갑자기 왜...",
  ui_story_5035_50351501_16_dialog_content = "(어라? 제인 씨 뒤에... 총상회의 마차가 서 있어?!)",
  ui_story_5035_50351501_17_dialog_content = "<color=#e8d9bb>워어, 워──</color>",
  ui_story_5035_50351501_18_dialog_content = "찾기 꽤 힘든 곳이군.",
  ui_story_5035_50351501_19_dialog_content = "안데르센 가문 소유의 부동산이라고 하기엔 느낌이 좀 다르지 않은가.",
  ui_story_5035_50351501_20_dialog_content = "이스타반 삼촌...?!",
  ui_story_5035_50351501_21_dialog_content = "오, 잘 지냈느냐, 니나 안데르센.",
  ui_story_5035_50351501_22_dialog_content = "보아하니 가여운 꼬마 아가씨는 아직 자기 저택에서 무슨 사건이 벌어졌는지 모르는 모양이군.",
  ui_story_5035_50351501_23_dialog_content = "개업 축하해요~ 대박 나세요~ 니나 양.",
  ui_story_5035_50351501_24_dialog_content = "(샤엘 씨도 같이 왔네. 설마... 내 사업자등록증에 무슨 문제라도 있었나?)",
  ui_story_5035_50351501_25_dialog_content = "저, 잠시만 기다려 주시겠어요? 가서 담당자를 불러올게요...",
  ui_story_5035_50351501_26_dialog_content = "미노스 씨 말인가요? 벌써 여기 있는걸요.",
  ui_story_5035_50351501_27_dialog_content = "오시느라 수고 많으셨습니다, 여러분.",
  ui_story_5035_50351501_28_dialog_content = "그자는 이미 여기 데려왔습니다.",
  ui_story_5035_50351501_29_dialog_content = "이거 풀지 못해!",
  ui_story_5035_50351501_30_dialog_content = "너흰 모두 내 영화와 함께 땅에 묻혀야 해!",
  ui_story_5035_50351501_31_dialog_content = "흥! 두고 봐. 내가 찍은 영상 속에서 네가 나온 장면들은\n다 편집해서 이상하게 만들어 버릴 테니까!",
  ui_story_5035_50351501_32_dialog_content = "웃긴 모습으로 만들어서 네 명예를 땅에 떨어트려 주겠어!",
  ui_story_5035_50351501_33_dialog_content = "자네가 구속하고 있는 그자가 바로 이번 일을 벌인 자인가?",
  ui_story_5035_50351501_34_dialog_content = "그렇습니다, 섀도우마스터.",
  ui_story_5035_50351501_35_dialog_content = "이 저택의 배치와 장치를 엉망으로 만들어, 이곳을 찾아 주신 손님들을 위험에 빠트릴 뻔했습니다.",
  ui_story_5035_50351501_36_dialog_content = "헛소리 집어치워! 내가 한 건 예술이야!",
  ui_story_5035_50351501_37_dialog_content = "그리고 감독인 주제에 계속 암귀를 조종해서 영화를 찍었어요!",
  ui_story_5035_50351501_38_dialog_content = "이 저택에서 저번 작품을 촬영할 때 영화의 작품성을 높이겠다면서\n스태프들을 무차별적으로 살해했고요!",
  ui_story_5035_50351501_39_dialog_content = "저는 그때 발이 빨랐던 덕분에 목숨을 잃지 않고 도망칠 수 있었어요.\n그때 상황을 기록한 테이프가 떨어져서 망가지지만 않았더라면 증거로 제시할 수 있었을 거예요!",
  ui_story_5035_50351501_40_dialog_content = "그 입 닥쳐!",
  ui_story_5035_50351501_41_dialog_content = "리리카, 걷어차이지 않게 조심해!",
  ui_story_5035_50351501_42_dialog_content = "<color=#e8d9bb>퍼억──</color>",
  ui_story_5035_50351501_43_dialog_content = "으악!",
  ui_story_5035_50351501_44_dialog_content = "미친개는 지팡이가 약이지.",
  ui_story_5035_50351501_45_dialog_content = "그자를 끌고 가라. 일단은 행패를 부린 죄목으로 처리하도록.",
  ui_story_5035_50351501_46_dialog_content = "그리고 그자의 모든 재산을 몰수해라.",
  ui_story_5035_50351501_47_dialog_content = "네~",
  ui_story_5035_50351501_48_dialog_content = "하지만... 이스타반 씨!",
  ui_story_5035_50351501_49_dialog_content = "당황할 것 없다.",
  ui_story_5035_50351501_50_dialog_content = "움브라톤에는 틀에 박힌 질서 따위는 존재하지 않는다.\n질서라는 건 경우에 따라 악인을 비호할 수도 있으니 말이지.",
  ui_story_5035_50351501_51_dialog_content = "아까 이 아가씨가 얘기한 저자의 죄에 대해서는...",
  ui_story_5035_50351501_52_dialog_content = "제인, 자네에게 조사를 맡기도록 하지.",
  ui_story_5035_50351501_53_dialog_content = "최대한 빨리 결과를 내줬으면 좋겠군. 나머지 일들은 이스타반 클랜에 맡겨라.",
  ui_story_5035_50351501_54_dialog_content = "네.",
  ui_story_5035_50351501_55_dialog_content = "잠깐만요! 이, 이게 대체 다 무슨 일이죠?!",
  ui_story_5035_50351501_56_dialog_content = "아, 조니는 이제 뭐 어쩔 도리가 없어♪",
  ui_story_5035_50351501_57_dialog_content = "니나 아가씨는 이 일에 뭐 아는 게 없어♪",
  ui_story_5035_50351501_58_dialog_content = "후훗, 니나 아가씨~ 안에서 무슨 일이 있었는지 궁금하면...",
  ui_story_5035_50351501_59_dialog_content = "곧 개봉할 다큐멘터리 《비명의 집 탐험》에서 확인해 줘~",
  ui_story_5035_50351501_60_dialog_content = "<color=#e8d9bb>며칠 뒤, 움브라톤 변경, 안데르센 비명의 집</color>",
  ui_story_5035_50351501_61_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5035_50351501_62_dialog_content = "우와, 사람이 너무 많아서 비집고 들어갈 틈도 안 보여!",
  ui_story_5035_50351501_63_dialog_content = "줄이 어디서 끝나는지 보이지도 않아!",
  ui_story_5035_50351501_64_dialog_content = "(미노스의 초대를 받은 나와 바이스는 안데르센 비명의 집에 다시 한번 방문했다.)",
  ui_story_5035_50351501_65_dialog_content = "(미노스는 저번에 있었던 뜻밖의 사고에 대해서 보상을 해 주겠다고\n고집을 부렸는데, 지금 이 상황은...)",
  ui_story_5035_50351501_66_dialog_content = "이러면 어떻게 들어가라는 거야!",
  ui_story_5035_50351501_67_dialog_content = "PlayerName, 너도 일하기 싫어서 여기 온 거야?",
  ui_story_5035_50351501_68_dialog_content = "뭔가 오늘은 나랑 일정이 많이 겹치는 것 같네.",
  ui_story_5035_50351501_69_dialog_content = "기운 좀 내, 도브. 줄 서고 있을 때부터 축축 처져 있으면 안 된다구!",
  ui_story_5035_50351501_70_dialog_content = "우와, 도브, 웬디, 좋은 아침이야!",
  ui_story_5035_50351501_71_dialog_content = "너희도 둘이 오면 티켓이 반값이 되니까 같이 온 거야?",
  ui_story_5035_50351501_72_dialog_content = "반값? 지금 안데르센 비명의 집은 티켓을 사려고 해도\n미리 예약을 해 둬야 하는데? 반값 할인 그런 거 없어.",
  ui_story_5035_50351501_73_dialog_content = "뭐?",
  ui_story_5035_50351501_74_dialog_content = "몰랐어? 너희 요즘 움브라톤에서 한창 인기인 《비명의 집 탐험》을 아직 안 봤구나?!",
  ui_story_5035_50351501_75_dialog_content = "이 안데르센 비명의 집이 바로 거기 나온 실제 촬영지야.",
  ui_story_5035_50351501_76_dialog_content = "인기가 하늘을 뚫을 정도라 안 봐 두면 사람들이랑 말할 때 대화 주제를 못 따라갈걸~",
  ui_story_5035_50351501_77_dialog_content = "웬디, PlayerName하고 바이스 둘 다 그 영화에 출연했어.",
  ui_story_5035_50351501_78_dialog_content = "어?! 그, 그랬구나!",
  ui_story_5035_50351501_79_dialog_content = "웬디는 계속 영화를 안 본 상태로 여기에 와 보고 싶다고 했거든.\n영화는 꼭 여기 온 다음에 볼 거래나.",
  ui_story_5035_50351501_80_dialog_content = "페피랑 다른 애들이 스포일러를 하려고 했었는데, 웬디가 전부 막아버렸어.",
  ui_story_5035_50351501_81_dialog_content = "난 그냥 직접 와서 이 공포감을 느껴 보고 싶었을 뿐이야!",
  ui_story_5035_50351501_82_dialog_content = "다행이네. PlayerName, 이제 니나 양이랑 미노스도\n더는 매출 때문에 고민할 필요는 없을 것 같아.",
  ui_story_5035_50351501_83_dialog_content = "어라? 내가 잘못 본 거 아니지?",
  ui_story_5035_50351501_84_dialog_content = "우와! 정말 아름다운 재회네!",
  ui_story_5035_50351501_85_dialog_content = "동료들과 함께 수많은 어려움을 겪고 결국엔 탈출에 성공,\n다시 한번 같은 곳에서 만나게 되는 전개!",
  ui_story_5035_50351501_86_dialog_content = "미리 알려주는 건데, 이거 절대로 극적인 연출을 위해서 조작한 거 아니야~",
  ui_story_5035_50351501_87_dialog_content = "리리카도 미노스한테 초대받은 거구나!",
  ui_story_5035_50351501_88_dialog_content = "쉿... PlayerName 나 지금 촬영 중이야! 촬영!",
  ui_story_5035_50351501_89_dialog_content = "관객 여러분 안녕! 《비명의 집 탐험-후일담》을 봐줘서 고마워!",
  ui_story_5035_50351501_90_dialog_content = "그럼 우리 여주인공 새디가 비명의 집의 현재 상황은 어떤지 안내해 줄 거야.",
  ui_story_5035_50351501_91_dialog_content = "Hey Yo! 나는 「새디 666」, 의뢰라면 절대 허투루 안 하지.",
  ui_story_5035_50351501_92_dialog_content = "축하해, 새디! 드디어 여주인공이 됐구나!",
  ui_story_5035_50351501_93_dialog_content = "그냥 진정한 의적이 되기 위해서 노력하고 있을 뿐이야.",
  ui_story_5035_50351501_94_dialog_content = "어? 전엔 배우 역할을 하는 거 보고 엉망진창인 임무라고 하지 않았어?",
  ui_story_5035_50351501_95_dialog_content = "이젠 알았어.",
  ui_story_5035_50351501_96_dialog_content = "약한 사람들을 돕고, 정의를 관철하고, 독립적인 생활을 하는 것\n모두 멋진 의적이 해야 할 일이야.",
  ui_story_5035_50351501_97_dialog_content = "그래서 이젠 의적이라는 호칭과 신분에 얽매이지 않을 거야.",
  ui_story_5035_50351501_98_dialog_content = "대단해, 새디. 벌써 그런 걸 깨우쳤구나!",
  ui_story_5035_50351501_99_dialog_content = "벼, 별거 아니야.",
  ui_story_5035_50351501_100_dialog_content = "좋았어! 분위기 좋고! 컷!",
  ui_story_5035_50351501_101_dialog_content = "모두 모이셨군요.",
  ui_story_5035_50351501_102_dialog_content = "일전에는 여러분들을 제대로 모시지 못했습니다.\n그러니 만회할 기회를 주셨으면 좋겠습니다.",
  ui_story_5035_50351501_103_dialog_content = "개선된 버전의 비명의 집을 체험해 봐. 그리고 나면 안데르센 저택에서 식사를 하는 거야!",
  ui_story_5035_50351501_104_dialog_content = "미노스랑 내 메이드 사나에는 요리 솜씨가 아주 좋거든~",
  ui_story_5035_50351501_105_dialog_content = "하하, 과찬이십니다.",
  ui_story_5035_50351501_106_dialog_content = "역시 다시 사이가 좋아졌구나.",
  ui_story_5035_50351501_107_dialog_content = "그런 셈이지. 나랑 미노스 사이에 있던 오해는 벌써 다 풀렸거든.",
  ui_story_5035_50351501_108_dialog_content = "리리카 양의 테이프가 있어서 정말 다행이었습니다.\n그게 없었다면 제 설명만으로는 역부족이었을지도 모릅니다.",
  ui_story_5035_50351501_109_dialog_content = "후후훗~ 그럼 내 다음 작품도 많이 응원해 줘!",
  ui_story_5035_50351501_110_dialog_content = "갑자기 느낀 건데, 아무래도 난 배우보단 감독 쪽에 더 재능이 있는 것 같아!",
  ui_story_5035_50351501_111_dialog_content = "그래? 그럼 이제 배우는 그만두고 감독이 되는 거야?",
  ui_story_5035_50351501_112_dialog_content = "아직 고민 중이야! 그치만 감독이 되는 건 엄청 어려운 일 같더라구.\n어디서부터 시작해야 할지도 모르겠구...",
  ui_story_5035_50351501_113_dialog_content = "아, 마침 다들 여기 있었네요.",
  ui_story_5035_50351501_114_dialog_content = "오늘 전 운이 좋은가 봐요.",
  ui_story_5035_50351501_115_dialog_content = "어! 골디! 오랜만이야!",
  ui_story_5035_50351501_116_dialog_content = "요즘 뭐 하고 지내? 새로 촬영 들어간 거 있어?",
  ui_story_5035_50351501_117_dialog_content = "한동안은 영화에 출연하지 않으려고요. 요즘은...",
  ui_story_5035_50351501_118_dialog_content = "스토옵! 잠깐, 잠깐만...",
  ui_story_5035_50351501_119_dialog_content = "(어디서 많이 본 얼굴인데?!)",
  ui_story_5035_50351501_120_dialog_content = "아! 그래! 맞아!",
  ui_story_5035_50351501_121_dialog_content = "골디잖아!",
  ui_story_5035_50351501_122_dialog_content = "어? 너희도 들었어? 골디래!",
  ui_story_5035_50351501_123_dialog_content = "그게 진짜야? 골디도 왔다고?!",
  ui_story_5035_50351501_124_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5035_50351501_125_dialog_content = "우와! 사람들이 소란스러워지기 시작했어!",
  ui_story_5035_50351501_126_dialog_content = "골디 씨! 여기 한 번만 봐주세요! 여기요! 몇 가지 질문을 드리고 싶어요!",
  ui_story_5035_50351501_127_dialog_content = "안녕하세요, 저는 《데일리 스쿠프 속보》의 수습기자 브랜디라고 해요.",
  ui_story_5035_50351501_128_dialog_content = "골디 씨가 《비명의 집 탐험》에서 겪은 일들이 사실인지 궁금해하시는 분들이 많은데요.\n정말 다 실제로 있었던 일인가요?",
  ui_story_5035_50351501_129_dialog_content = "음, 여러분 모두 관련 뉴스들을 읽어 보셨을 거라고 생각해요.",
  ui_story_5035_50351501_130_dialog_content = "확실히 저는 그 당시에 조니 감독의 음모에 휘말려 큰일을 겪었어요.",
  ui_story_5035_50351501_131_dialog_content = "그렇다면 어떻게 그런 상황에서 기적적으로 목숨을 건지신 건가요?",
  ui_story_5035_50351501_132_dialog_content = "그 부분은, 이렇게 말씀드리는 것도 참 이상하지만 사실 제가 한 건...",
  ui_story_5035_50351501_133_dialog_content = "<color=#FFB400>아무것도 없어요.</color>",
  ui_story_5035_50351501_134_dialog_content = "그때 발밑에 있던 바닥은 무너져 내렸고,\n위에서는 수많은 벽돌과 나무판자들이 떨어졌어요. 전 정말 깜짝 놀랐어요.",
  ui_story_5035_50351501_135_dialog_content = "그렇지만 조각들이 너무 컸던 모양인지 제 몸에 바로 떨어져 내리지는 않았답니다.",
  ui_story_5035_50351501_136_dialog_content = "한 돌기둥이 벽 구석에 끼어 버렸고, 대들보가 바로 그 돌기둥에 떨어졌어요.\n그리고 나무판자가 그 위를 덮어서 작은 돌들이 떨어지지 않도록 막아 줬고요,",
  ui_story_5035_50351501_137_dialog_content = "떨어져 내린 잔해들이 절묘하게 쌓여서, 사람 한 명 정도 높이의 공간을 만들어 줬어요.",
  ui_story_5035_50351501_138_dialog_content = "네에?",
  ui_story_5035_50351501_139_dialog_content = "그리고 전 그 잔해들을 하나씩 치워 나갔어요.\n쌓인 블록들을 해체하는 것 같아서 아주 재미있었어요!",
  ui_story_5035_50351501_140_dialog_content = "폐허에서 순조롭게 빠져나온 전 사람을 찾으려고 소리가 들려오는 방향을 향해 이동했어요.",
  ui_story_5035_50351501_141_dialog_content = "도중에 조니 감독이 남겨 둔 촛불을 조명으로 사용했죠.",
  ui_story_5035_50351501_142_dialog_content = "그리고 여러분이 영화에서 보신 그 상황이 발생한 거예요.",
  ui_story_5035_50351501_143_dialog_content = "다른 질문 있으신가요?",
  ui_story_5035_50351501_144_dialog_content = "그, 그게 사실인가요?!",
  ui_story_5035_50351501_145_dialog_content = "그 정도면 운이 좋았던 게 아니라, 기적이 일어났던 거네요!",
  ui_story_5035_50351501_146_dialog_content = "기적일 수도 있겠죠. 그렇지만 기적은 평소에도 일어나는걸요.",
  ui_story_5035_50351501_147_dialog_content = "우리 모두가 이 세상에 존재할 수 있다는 이 사실만 해도 하나의 기적이잖아요!",
  ui_story_5035_50351501_148_dialog_content = "음, 인기 가수의 카리스마란 게 바로 이런 거군요...",
  ui_story_5035_50351501_149_dialog_content = "으앗, 가, 간신히 여기까지 왔네!",
  ui_story_5035_50351501_150_dialog_content = "골디! 괜찮아 보여서 정말 다행이야!",
  ui_story_5035_50351501_151_dialog_content = "내가 벌써 다 생각해 뒀다구. 이 씬은 골디 너부터 촬영하기 시작할 거야!",
  ui_story_5035_50351501_152_dialog_content = "오오, 주연 배우 여러분께서 다 여기 모이셨네요.\n제가 인터뷰를 좀 할 수 있을까요?",
  ui_story_5035_50351501_153_dialog_content = "《비명의 집 탐험》이 개봉된 후 대중들 사이에서는 궁금증 하나가 꾸준히 생겨나고 있는데요.",
  ui_story_5035_50351501_154_dialog_content = "관 속에서 기어 나온 「에스더 부인」은 정말로 유령이었나요?",
  ui_story_5035_50351501_155_dialog_content = "아, 그건 말이죠. 따지고 보면...",
  ui_story_5035_50351501_156_dialog_content = "직접 들어가서 확인해 봐.",
  ui_story_5035_50351501_157_dialog_content = "네?",
  ui_story_5035_50351501_158_dialog_content = "자기 두 눈으로 직접 봐야 스스로 만족할 만한 답을 얻을 수 있거든.",
  ui_story_5035_50351501_159_dialog_content = "그 말을 들으니 저도 모르게 빨리 뛰어가서 티켓을 사야겠단 생각이 드네요!",
  ui_story_5035_50351501_160_dialog_content = "그럼 먼저 관람부터 하고 올게요.\n주연 배우 여러분은 인터뷰 예약을 하고 싶으니까 꼭 허락해 주세요!",
  ui_story_5035_50351501_161_dialog_content = "안데르센 비명의 집에 덕담을 해 주셔서 감사합니다, 새디 양.",
  ui_story_5035_50351501_162_dialog_content = "... 난 그냥 내 생각을 말한 것뿐이야.",
  ui_story_5035_50351501_163_dialog_content = "그랬구나... 근데 나도 새디 말이 맞다고 생각해.",
  ui_story_5035_50351501_164_dialog_content = "우리가 그 암귀를 처치해 버려서, 그 암귀 때문에 일어났던\n초자연적인 현상들도 더는 발생하지 않겠지만.",
  ui_story_5035_50351501_165_dialog_content = "그래도 관람객들을 위해 비명의 집에 대한 환상을 남겨 두는 것도 나쁘진 않은 것 같아.",
  ui_story_5035_50351501_166_dialog_content = "어쩌면 여기 「리얼한 초자연적 현상」 같은 건 진짜로 존재하지 않을지 몰라.",
  ui_story_5035_50351501_167_dialog_content = "그치만 PlayerName 말대로 우리가 발견해 주길 기다리는 곳이 있을지도 모르잖아~",
  ui_story_5035_50351501_168_dialog_content = "그렇게 생각한다니 다행이네!",
  ui_story_5035_50351501_169_dialog_content = "후훗, 비명의 집에 대한 관객들의 환상을 깨트리면 안 되잖아~",
  ui_story_5035_50351501_170_dialog_content = "왜냐면 난 《비명의 집 탐험 - 후일담》을 기획 중이거든!",
  ui_story_5035_50351501_171_dialog_content = "《비명의 집 탐험 - 후일담》?!",
  ui_story_5035_50351501_172_dialog_content = "우와! 그 분홍수염 탐정이잖아! 리리카 씨! 저 리리카 씨 팬입니다!",
  ui_story_5035_50351501_173_dialog_content = "와! 리리카라고? 진짜 리리카네!",
  ui_story_5035_50351501_174_dialog_content = "엣?! 잠깐만요, 여러분... 한 분씩 와 주세요!",
  ui_story_5035_50351501_175_dialog_content = "리리카가 하루아침에 벼락스타가 될 줄은 진짜 몰랐네.",
  ui_story_5035_50351501_176_dialog_content = "역시 바라던 걸 이뤘구나. 누구나 다 아는 스타가 됐잖아!",
  ui_story_5035_50351501_177_dialog_content = "정말 행복해! 골디랑 리리카한테 다 사인받았어!",
  ui_story_5035_50351501_178_dialog_content = "잠깐, 저쪽에 있는 사람들도 《비명의 집 탐험》에 나온 배우들 아냐?",
  ui_story_5035_50351501_179_dialog_content = "어? 그러네! 영화에 나온 그 사람들 맞네!",
  ui_story_5035_50351501_180_dialog_content = "실눈 백발, 큰 꼬리 달린 미녀, 야구모자 쓴 미소녀에 허약해 보이는 소년까지!",
  ui_story_5035_50351501_181_dialog_content = "(왜, 왜 나까지 끼워 넣은 거야!)",
  ui_story_5035_50351501_182_dialog_content = "어떡해, 난 몰라! 나 아직 스타가 될 준비도 제대로 못 했는데!",
  ui_story_5035_50351501_183_dialog_content = "사, 사람들이 우리 쪽으로 달려오고 있어!",
  ui_story_5035_50351501_184_dialog_content = "그럼 빨리 도망쳐! 빨리!",
  ui_story_5035_50351501_185_dialog_content = "이쪽이야! 이쪽 길로 가면 돼!",
  ui_story_5035_50351501_186_dialog_content = "아, 그리고 뛰는 김에 카메라 한 번만 봐줄래?",
  ui_story_5035_50351501_187_dialog_content = "그리고...",
  ui_story_5035_50351501_188_dialog_content = "비명을 멈추면 안 돼!",
  ui_story_5035_50351501_189_dialog_content = "후후~ 이쪽의 소란은 잠잠해지려면 시간이 좀 걸리겠네.",
  ui_story_5035_50351501_190_dialog_content = "나도 슬슬 돌아가야겠어.",
  ui_story_5035_50351501_191_dialog_content = "오늘은 방문객이 많으니까 여러 돌발 상황에 대비해야 해...",
  ui_story_5035_50351501_192_dialog_content = "으악! 바퀴벌레다!",
  ui_story_5035_50351501_193_dialog_content = "직원은 어디 있는 거야? 좀 따져야겠어!",
  ui_story_5035_50351501_194_dialog_content = "네! 손님!",
  ui_story_5035_50351501_195_dialog_content = "사장님, 화장실에 들어간 사람이 계속 안 나오는데 여기 말고 다른 화장실은 없나요?",
  ui_story_5035_50351501_196_dialog_content = "가까운 곳에는 없어요. 멀리 떨어진 곳에는 하나 있지만요.",
  ui_story_5035_50351501_197_dialog_content = "조금만 더 기다려 보세요. 저는 다른 일이 있어서 가 볼게요.",
  ui_story_5035_50351501_198_dialog_content = "미치겠네.",
  ui_story_5035_50351501_199_dialog_content = "저기요! 대체 언제 나올 겁니까?! 놀라서 바지에 실수라도 했나?",
  ui_story_5035_50351501_200_dialog_content = "화장실 칸도 부족한데 어떻게든 빨리 해결하고 좀 나와요!",
  ui_story_5035_50351501_201_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5035_50351501_202_dialog_content = "저기요? 아무도 없어요?!",
  ui_story_5035_50351501_203_dialog_content = "이상하네... 왜 아무 소리도 안 들리지...?",
  ui_story_5035_50351501_204_dialog_content = "안에 사람 있나요?",
  ui_story_5035_50351501_205_dialog_content = "<color=#e8d9bb>또옥... 똑...</color>"
}
return config
